CUBE = [0, 95, 135, 175, 215, 255]
RT = [38,115,155,196,235]
GT = [36,116,154,195,235]
BT = [35,115,155,195,235]
# pure gray mapping: list of (upper_bound_inclusive, index)
GRAY_RUNS = [(4,16),(13,232),(23,233),(33,234),(43,235),(53,236),(63,237),(73,238),(83,239),(91,240),(96,59),(103,241),(113,242),(122,243),(131,244),(136,102),(142,245),(152,246),(162,247),(171,248),(176,145),(182,249),(192,250),(202,251),(211,252),(216,188),(222,253),(232,254),(246,255),(255,231)]
def gray_index(v):
    for ub, i in GRAY_RUNS:
        if v <= ub: return i
def rgb_of(i):
    if 16 <= i < 232:
        i -= 16
        return (CUBE[i//36], CUBE[(i//6)%6], CUBE[i%6])
    if i >= 232:
        return (8+10*(i-232),)*3
def idx(v, t):
    for i,th in enumerate(t):
        if v < th: return i
    return 5
def dist(a, b):
    rs = a[0]+b[0]
    dr=a[0]-b[0]; dg=a[1]-b[1]; db=a[2]-b[2]
    return (1024+rs)*dr*dr + 2048*dg*dg + (1534-rs)*db*db
def lum(r,g,b):
    return (3567664*r + 11998547*g + 1211005*b + (1<<23)) >> 24
def to256(r,g,b):
    if r==g==b: return gray_index(r)
    ci = (idx(r,RT), idx(g,GT), idx(b,BT))
    cube = tuple(CUBE[i] for i in ci)
    cube_idx = 16 + 36*ci[0] + 6*ci[1] + ci[2]
    gi = gray_index(lum(r,g,b))
    gray = rgb_of(gi)
    if dist((r,g,b), cube) <= dist((r,g,b), gray):
        return cube_idx
    return gi
