#!/usr/bin/env python3
"""Generate src/cli_args.rs from recorded help text (gen/long_help.txt, gen/short_help.txt)."""
import re, sys, os
here = os.path.dirname(os.path.abspath(__file__))
long_help = open(os.path.join(here, "long_help.txt")).read().split("\n")
short_help = open(os.path.join(here, "short_help.txt")).read().split("\n")

# parse short help: map long name -> short help text (without [default...] etc.)
short_map = {}
for line in short_help:
    m = re.match(r"^  (?:-(\S), )?--(\S+)(?: <[^>]+>)?\s{2,}(.*)$", line)
    if m:
        txt = m.group(3)
        txt = re.sub(r" \[default: .*?\]( \[possible values: .*\])?$", r"\1", txt)
        txt = re.sub(r" \[possible values: .*\]$", "", txt)
        short_map[m.group(2)] = txt
    m = re.match(r"^  \[(\w+)\]\s{2,}(.*)$", line)
    if m:
        short_map[m.group(1)] = m.group(2)

# parse long help
opts = []  # list of dicts
i = 0
cur = None
section = None
after_long_help_start = None
while i < len(long_help):
    line = long_help[i]
    if line == "Options:":
        section = "options"; i += 1; continue
    if line == "Arguments:":
        section = "args"; i += 1; continue
    if section == "options" and line == "Git config":
        after_long_help_start = i
        break
    m = re.match(r"^  (?:-(\S), )?--(\S+)(?: <([^>]+)>)?$", line)
    if m and section == "options":
        cur = {"short": m.group(1), "long": m.group(2), "value": m.group(3), "lines": []}
        opts.append(cur); i += 1; continue
    m = re.match(r"^  \[(\w+)\]$", line)
    if m and section == "args":
        cur = {"short": None, "long": None, "positional": m.group(1), "value": None, "lines": []}
        opts.append(cur); i += 1; continue
    if cur is not None:
        if line.startswith("          "):
            cur["lines"].append(line[10:])
        elif line == "":
            cur["lines"].append("")
        else:
            cur = None
    i += 1

after_long_help = "\n".join(long_help[after_long_help_start:]).rstrip("\n")

def process(o):
    lines = o["lines"]
    # strip trailing blanks
    while lines and lines[-1] == "": lines.pop()
    while lines and lines[0] == "": lines.pop(0)
    default = None; possible = None; possible_help = None
    out = []
    j = 0
    while j < len(lines):
        l = lines[j]
        m = re.match(r"^\[default: (.*)\]$", l)
        if m:
            d = m.group(1)
            if d.startswith('"') and d.endswith('"'):
                d = d[1:-1]
            default = d; j += 1; continue
        m = re.match(r"^\[possible values: (.*)\]$", l)
        if m:
            possible = m.group(1).split(", "); j += 1; continue
        if l == "Possible values:":
            possible_help = []
            j += 1
            while j < len(lines) and lines[j].strip():
                m = re.match(r"^- (\S+):\s+(.*)$", lines[j])
                if m:
                    possible_help.append([m.group(1), m.group(2)])
                else:
                    possible_help[-1][1] += "\n" + lines[j].strip()
                j += 1
            continue
        out.append(l); j += 1
    while out and out[-1] == "": out.pop()
    o["long_help"] = "\n".join(out)
    o["default"] = default
    o["possible"] = possible
    o["possible_help"] = possible_help

for o in opts: process(o)

def rs(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'

print("// Generated by gen/gen_cli.py from recorded help output. Do not edit.")
print("use clap::{Arg, ArgAction, Command, builder::PossibleValue};")
print("pub fn add_args(cmd: Command) -> Command {")
print("    cmd")
for o in opts:
    if o.get("positional"):
        name = o["positional"]
        key = name.lower()
        print(f"        .arg(Arg::new({rs(key)}).value_name({rs(name)}).help({rs(short_map[name])}).long_help({rs(o['long_help'])}))")
        continue
    name = o["long"]
    key = name.replace("-", "_")
    parts = [f"Arg::new({rs(key)})", f".long({rs(name)})"]
    if o["short"]:
        parts.append(f".short('{o['short']}')")
    if o["value"]:
        parts.append(f".value_name({rs(o['value'])})")
        parts.append(".num_args(1)")
    else:
        parts.append(".action(ArgAction::SetTrue)")
    parts.append(f".help({rs(short_map[name])})")
    parts.append(f".long_help({rs(o['long_help'])})")
    if o["default"] is not None:
        parts.append(f".default_value({rs(o['default'])})")
    if o["possible_help"]:
        pv = ", ".join(f"PossibleValue::new({rs(v)}).help({rs(h)})" for v, h in o["possible_help"])
        parts.append(f".value_parser([{pv}])")
    elif o["possible"]:
        pv = ", ".join(rs(v) for v in o["possible"])
        parts.append(f".value_parser([{pv}])")
    print("        .arg(" + "".join(parts) + ")")
print("}")
print()
print("pub const AFTER_LONG_HELP: &str = " + rs(after_long_help) + ";")
EOF
