//! ANSI escape sequence handling: a minimal re-implementation of the parts of
//! `ansi_term`-style output that we need, plus a parser for ANSI-colored input.

use std::fmt::Write as _;
use unicode_width::UnicodeWidthStr;

pub const RESET: &str = "\x1b[0m";

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum Color {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Purple,
    Cyan,
    White,
    Fixed(u8),
    RGB(u8, u8, u8),
}

impl Color {
    fn write_fg(&self, out: &mut String) {
        match *self {
            Color::Black => out.push_str("30"),
            Color::Red => out.push_str("31"),
            Color::Green => out.push_str("32"),
            Color::Yellow => out.push_str("33"),
            Color::Blue => out.push_str("34"),
            Color::Purple => out.push_str("35"),
            Color::Cyan => out.push_str("36"),
            Color::White => out.push_str("37"),
            Color::Fixed(n) => {
                let _ = write!(out, "38;5;{}", n);
            }
            Color::RGB(r, g, b) => {
                let _ = write!(out, "38;2;{};{};{}", r, g, b);
            }
        }
    }
    fn write_bg(&self, out: &mut String) {
        match *self {
            Color::Black => out.push_str("40"),
            Color::Red => out.push_str("41"),
            Color::Green => out.push_str("42"),
            Color::Yellow => out.push_str("43"),
            Color::Blue => out.push_str("44"),
            Color::Purple => out.push_str("45"),
            Color::Cyan => out.push_str("46"),
            Color::White => out.push_str("47"),
            Color::Fixed(n) => {
                let _ = write!(out, "48;5;{}", n);
            }
            Color::RGB(r, g, b) => {
                let _ = write!(out, "48;2;{};{};{}", r, g, b);
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default, Hash)]
pub struct AnsiStyle {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub is_bold: bool,
    pub is_dimmed: bool,
    pub is_italic: bool,
    pub is_underline: bool,
    pub is_blink: bool,
    pub is_reverse: bool,
    pub is_hidden: bool,
    pub is_strikethrough: bool,
}

impl AnsiStyle {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn is_plain(&self) -> bool {
        *self == Self::default()
    }

    pub fn prefix(&self) -> String {
        let mut out = String::new();
        self.write_prefix(&mut out);
        out
    }

    pub fn write_prefix(&self, out: &mut String) {
        if self.is_plain() {
            return;
        }
        out.push_str("\x1b[");
        let mut written = false;
        let mut sep = |out: &mut String| {
            if written {
                out.push(';');
            }
            written = true;
        };
        if self.is_bold {
            sep(out);
            out.push('1');
        }
        if self.is_dimmed {
            sep(out);
            out.push('2');
        }
        if self.is_italic {
            sep(out);
            out.push('3');
        }
        if self.is_underline {
            sep(out);
            out.push('4');
        }
        if self.is_blink {
            sep(out);
            out.push('5');
        }
        if self.is_reverse {
            sep(out);
            out.push('7');
        }
        if self.is_hidden {
            sep(out);
            out.push('8');
        }
        if self.is_strikethrough {
            sep(out);
            out.push('9');
        }
        if let Some(bg) = self.background {
            sep(out);
            bg.write_bg(out);
        }
        if let Some(fg) = self.foreground {
            sep(out);
            fg.write_fg(out);
        }
        out.push('m');
    }

    pub fn suffix(&self) -> &'static str {
        if self.is_plain() {
            ""
        } else {
            RESET
        }
    }

    /// Paint a single string: prefix + text + reset (if styled).
    pub fn paint(&self, text: &str) -> String {
        let mut out = String::with_capacity(text.len() + 24);
        self.write_prefix(&mut out);
        out.push_str(text);
        out.push_str(self.suffix());
        out
    }

    pub fn fg(mut self, c: Color) -> Self {
        self.foreground = Some(c);
        self
    }
    pub fn on(mut self, c: Color) -> Self {
        self.background = Some(c);
        self
    }
    pub fn bold(mut self) -> Self {
        self.is_bold = true;
        self
    }
    pub fn reverse(mut self) -> Self {
        self.is_reverse = true;
        self
    }
}

enum Difference {
    ExtraStyles(AnsiStyle),
    Reset,
    NoDifference,
}

fn difference(first: &AnsiStyle, next: &AnsiStyle) -> Difference {
    if first == next {
        return Difference::NoDifference;
    }
    if (first.is_bold && !next.is_bold)
        || (first.is_dimmed && !next.is_dimmed)
        || (first.is_italic && !next.is_italic)
        || (first.is_underline && !next.is_underline)
        || (first.is_blink && !next.is_blink)
        || (first.is_reverse && !next.is_reverse)
        || (first.is_hidden && !next.is_hidden)
        || (first.is_strikethrough && !next.is_strikethrough)
        || (first.foreground.is_some() && next.foreground.is_none())
        || (first.background.is_some() && next.background.is_none())
    {
        return Difference::Reset;
    }
    let mut extra = AnsiStyle::default();
    if first.is_bold != next.is_bold {
        extra.is_bold = true;
    }
    if first.is_dimmed != next.is_dimmed {
        extra.is_dimmed = true;
    }
    if first.is_italic != next.is_italic {
        extra.is_italic = true;
    }
    if first.is_underline != next.is_underline {
        extra.is_underline = true;
    }
    if first.is_blink != next.is_blink {
        extra.is_blink = true;
    }
    if first.is_reverse != next.is_reverse {
        extra.is_reverse = true;
    }
    if first.is_hidden != next.is_hidden {
        extra.is_hidden = true;
    }
    if first.is_strikethrough != next.is_strikethrough {
        extra.is_strikethrough = true;
    }
    if first.foreground != next.foreground {
        extra.foreground = next.foreground;
    }
    if first.background != next.background {
        extra.background = next.background;
    }
    Difference::ExtraStyles(extra)
}

/// A styled piece of text (equivalent of ansi_term's ANSIString).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Painted {
    pub style: AnsiStyle,
    pub text: String,
}

impl Painted {
    pub fn new(style: AnsiStyle, text: impl Into<String>) -> Self {
        Painted {
            style,
            text: text.into(),
        }
    }
}

/// Render a sequence of styled strings, emitting minimal escape sequences
/// between adjacent strings (ANSIStrings semantics).
pub fn paint_strings(strings: &[Painted]) -> String {
    let mut out = String::new();
    let first = match strings.first() {
        None => return out,
        Some(f) => f,
    };
    first.style.write_prefix(&mut out);
    out.push_str(&first.text);
    for w in strings.windows(2) {
        match difference(&w[0].style, &w[1].style) {
            Difference::ExtraStyles(s) => s.write_prefix(&mut out),
            Difference::Reset => {
                out.push_str(RESET);
                w[1].style.write_prefix(&mut out);
            }
            Difference::NoDifference => {}
        }
        out.push_str(&w[1].text);
    }
    if let Some(last) = strings.last() {
        if !last.style.is_plain() {
            out.push_str(RESET);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Parsing of ANSI-colored input
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Element {
    /// A SGR (select graphic rendition) escape sequence, with the style it describes.
    Sgr(AnsiStyle, usize, usize),
    /// A CSI escape sequence other than SGR.
    Csi(usize, usize),
    /// An escape sequence other than CSI (e.g. OSC)
    Esc(usize, usize),
    /// A run of text
    Text(usize, usize),
}

impl Element {
    pub fn range(&self) -> (usize, usize) {
        match *self {
            Element::Sgr(_, s, e) | Element::Csi(s, e) | Element::Esc(s, e) | Element::Text(s, e) => {
                (s, e)
            }
        }
    }
}

fn parse_sgr_params(params: &str) -> AnsiStyle {
    let mut style = AnsiStyle::default();
    let parts: Vec<&str> = params.split(';').collect();
    // A trailing empty parameter (e.g. "31;") is ignored.
    let n = if parts.len() > 1 && parts.last() == Some(&"") {
        parts.len() - 1
    } else {
        parts.len()
    };
    let mut vals: Vec<Option<u32>> = Vec::with_capacity(n);
    for p in &parts[..n] {
        // Sub-parameters separated by ':' are not supported: take the leading number.
        let p = p.split(':').next().unwrap_or("");
        if p.is_empty() {
            vals.push(Some(0));
        } else {
            vals.push(p.parse::<u32>().ok());
        }
    }
    let mut i = 0;
    while i < vals.len() {
        let v = match vals[i] {
            Some(v) => v,
            None => {
                i += 1;
                continue;
            }
        };
        match v {
            1 => style.is_bold = true,
            2 => style.is_dimmed = true,
            3 => style.is_italic = true,
            4 => style.is_underline = true,
            5 => style.is_blink = true,
            7 => style.is_reverse = true,
            8 => style.is_hidden = true,
            9 => style.is_strikethrough = true,
            30 => style.foreground = Some(Color::Black),
            31 => style.foreground = Some(Color::Red),
            32 => style.foreground = Some(Color::Green),
            33 => style.foreground = Some(Color::Yellow),
            34 => style.foreground = Some(Color::Blue),
            35 => style.foreground = Some(Color::Purple),
            36 => style.foreground = Some(Color::Cyan),
            37 => style.foreground = Some(Color::White),
            40 => style.background = Some(Color::Black),
            41 => style.background = Some(Color::Red),
            42 => style.background = Some(Color::Green),
            43 => style.background = Some(Color::Yellow),
            44 => style.background = Some(Color::Blue),
            45 => style.background = Some(Color::Purple),
            46 => style.background = Some(Color::Cyan),
            47 => style.background = Some(Color::White),
            38 | 48 => {
                let color = match vals.get(i + 1).copied().flatten() {
                    Some(5) => {
                        let c = vals.get(i + 2).copied().flatten();
                        i += 2;
                        match c {
                            Some(n) if n <= 255 => Some(Color::Fixed(n as u8)),
                            _ => None,
                        }
                    }
                    Some(2) => {
                        let r = vals.get(i + 2).copied().flatten();
                        let g = vals.get(i + 3).copied().flatten();
                        let b = vals.get(i + 4).copied().flatten();
                        i += 4;
                        match (r, g, b) {
                            (Some(r), Some(g), Some(b)) if r <= 255 && g <= 255 && b <= 255 => {
                                Some(Color::RGB(r as u8, g as u8, b as u8))
                            }
                            _ => None,
                        }
                    }
                    _ => {
                        i += 1;
                        None
                    }
                };
                if let Some(c) = color {
                    if v == 38 {
                        style.foreground = Some(c);
                    } else {
                        style.background = Some(c);
                    }
                }
            }
            90..=97 => style.foreground = Some(Color::Fixed((v - 90 + 8) as u8)),
            100..=107 => style.background = Some(Color::Fixed((v - 100 + 8) as u8)),
            _ => {}
        }
        i += 1;
    }
    style
}

/// Iterate over the elements (text and escape sequences) of a string.
pub fn elements(s: &str) -> Vec<Element> {
    let bytes = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    let mut text_start = 0;
    let n = bytes.len();
    while i < n {
        if bytes[i] == 0x1b {
            // Determine the extent of the escape sequence.
            let start = i;
            let mut j = i + 1;
            if j >= n {
                // Lone ESC at end: treat as text.
                i += 1;
                continue;
            }
            match bytes[j] {
                b'[' => {
                    // CSI: parameter bytes 0x30-0x3f, intermediate 0x20-0x2f, final 0x40-0x7e
                    j += 1;
                    let params_start = j;
                    while j < n && (0x30..=0x3f).contains(&bytes[j]) {
                        j += 1;
                    }
                    let params_end = j;
                    while j < n && (0x20..=0x2f).contains(&bytes[j]) {
                        j += 1;
                    }
                    if j < n && (0x40..=0x7e).contains(&bytes[j]) {
                        let final_byte = bytes[j];
                        j += 1;
                        if text_start < start {
                            out.push(Element::Text(text_start, start));
                        }
                        if final_byte == b'm' && params_end == j - 1 {
                            let style = parse_sgr_params(&s[params_start..params_end]);
                            out.push(Element::Sgr(style, start, j));
                        } else {
                            out.push(Element::Csi(start, j));
                        }
                        i = j;
                        text_start = j;
                    } else {
                        // Malformed/unterminated: consume to end of string as an escape
                        if text_start < start {
                            out.push(Element::Text(text_start, start));
                        }
                        out.push(Element::Esc(start, n));
                        i = n;
                        text_start = n;
                    }
                }
                b']' => {
                    // OSC: terminated by BEL or ESC \
                    j += 1;
                    let mut end = None;
                    while j < n {
                        if bytes[j] == 0x07 {
                            end = Some(j + 1);
                            break;
                        }
                        if bytes[j] == 0x1b && j + 1 < n && bytes[j + 1] == b'\\' {
                            end = Some(j + 2);
                            break;
                        }
                        j += 1;
                    }
                    let end = end.unwrap_or(n);
                    if text_start < start {
                        out.push(Element::Text(text_start, start));
                    }
                    out.push(Element::Esc(start, end));
                    i = end;
                    text_start = end;
                }
                _ => {
                    // Other escape: ESC followed by one char (or intermediate + final)
                    let mut k = j;
                    while k < n && (0x20..=0x2f).contains(&bytes[k]) {
                        k += 1;
                    }
                    let end = if k < n { k + 1 } else { n };
                    // make sure we end on a char boundary
                    let mut end = end;
                    while end < n && !s.is_char_boundary(end) {
                        end += 1;
                    }
                    if text_start < start {
                        out.push(Element::Text(text_start, start));
                    }
                    out.push(Element::Esc(start, end));
                    i = end;
                    text_start = end;
                }
            }
        } else {
            i += 1;
        }
    }
    if text_start < n {
        out.push(Element::Text(text_start, n));
    }
    out
}

pub fn strip_ansi_codes(s: &str) -> String {
    if !s.contains('\x1b') {
        return s.to_string();
    }
    let mut out = String::with_capacity(s.len());
    for el in elements(s) {
        if let Element::Text(a, b) = el {
            out.push_str(&s[a..b]);
        }
    }
    out
}

pub fn measure_text_width(s: &str) -> usize {
    if !s.contains('\x1b') {
        return s.width();
    }
    let mut w = 0;
    for el in elements(s) {
        if let Element::Text(a, b) = el {
            w += s[a..b].width();
        }
    }
    w
}

/// Parse a string into (style, text) sections.
pub fn parse_style_sections(s: &str) -> Vec<(AnsiStyle, &str)> {
    let mut sections = Vec::new();
    let mut curr = AnsiStyle::default();
    for el in elements(s) {
        match el {
            Element::Text(a, b) => sections.push((curr, &s[a..b])),
            Element::Sgr(style, _, _) => curr = style,
            _ => {}
        }
    }
    sections
}

/// Return the first style found in the string (the style in effect for the
/// first text element), if any text follows a style.
pub fn parse_first_style(s: &str) -> Option<AnsiStyle> {
    let mut curr: Option<AnsiStyle> = None;
    for el in elements(s) {
        match el {
            Element::Sgr(style, _, _) => curr = Some(style),
            Element::Text(_, _) => return curr,
            _ => {}
        }
    }
    None
}

/// Truncate a string (which may contain ANSI escape sequences) to the given
/// display width, appending `tail` (which counts towards the width).
pub fn truncate_str<'a>(s: &'a str, display_width: usize, tail: &str) -> std::borrow::Cow<'a, str> {
    let items = elements(s);
    let width = measure_text_width(s);
    if width <= display_width {
        return std::borrow::Cow::Borrowed(s);
    }
    let tail_width = tail.width();
    let max_width = display_width.saturating_sub(tail_width);
    let mut out = String::new();
    let mut curr_width = 0;
    for el in items {
        match el {
            Element::Text(a, b) => {
                for g in unicode_segmentation::UnicodeSegmentation::graphemes(&s[a..b], true) {
                    let gw = g.width();
                    if curr_width + gw > max_width {
                        out.push_str(tail);
                        return std::borrow::Cow::Owned(out);
                    }
                    curr_width += gw;
                    out.push_str(g);
                }
            }
            other => {
                let (a, b) = other.range();
                out.push_str(&s[a..b]);
            }
        }
    }
    out.push_str(tail);
    std::borrow::Cow::Owned(out)
}

/// Return the byte index of the `display_width`-th display cell in `s`,
/// counting only text (skipping escape sequences).
pub fn ansi_preserving_index(s: &str, display_width: usize) -> Option<usize> {
    let mut width = 0;
    for el in elements(s) {
        if let Element::Text(a, b) = el {
            for (gi, g) in unicode_segmentation::UnicodeSegmentation::grapheme_indices(&s[a..b], true) {
                if width >= display_width {
                    return Some(a + gi);
                }
                width += g.width();
            }
        }
    }
    None
}

/// Return the substring of `s` starting at display column `start`, preserving
/// all ANSI escape sequences (which do not count toward width).
pub fn ansi_preserving_slice(s: &str, start: usize) -> String {
    let mut out = String::new();
    let mut width = 0;
    for el in elements(s) {
        match el {
            Element::Text(a, b) => {
                for g in unicode_segmentation::UnicodeSegmentation::graphemes(&s[a..b], true) {
                    if width >= start {
                        out.push_str(g);
                    }
                    width += g.width();
                }
            }
            other => {
                let (a, b) = other.range();
                out.push_str(&s[a..b]);
            }
        }
    }
    out
}

/// Explain the ANSI escape sequences in a line, for --parse-ansi.
pub fn explain_ansi(line: &str, colorful: bool) -> String {
    let mut out = String::new();
    for (style, text) in parse_style_sections(line) {
        let s = crate::style::Style::from_ansi_style(style);
        if colorful {
            let _ = write!(out, "({}){}", s.to_painted_string(), style.paint(text));
        } else {
            let _ = write!(out, "({}){}", s, text);
        }
    }
    out
}
