//! Color parsing and conversion.

use crate::ansi::Color;

/// Parse a color name/code as used in delta style strings.
/// Returns Err(()) if the string is not a valid color.
/// "normal" yields Ok(None).
pub fn parse_color(s: &str, true_color: bool) -> Result<Option<Color>, ()> {
    if s == "normal" {
        return Ok(None);
    }
    let die = || Err(());
    let syntect_color = if s.starts_with('#') {
        match parse_hex(s) {
            Some(c) => c,
            None => return die(),
        }
    } else {
        let lower = s.to_lowercase();
        if let Some(c) = ansi_16_color_name_to_number(&lower) {
            return Ok(Some(color_from_ansi_number(c)));
        }
        if let Ok(n) = s.parse::<u8>() {
            return Ok(Some(color_from_ansi_number(n)));
        }
        match css_color(&lower) {
            Some(c) => c,
            None => return die(),
        }
    };
    Ok(Some(rgb_to_ansi_color(syntect_color, true_color)))
}

fn color_from_ansi_number(n: u8) -> Color {
    match n {
        0 => Color::Black,
        1 => Color::Red,
        2 => Color::Green,
        3 => Color::Yellow,
        4 => Color::Blue,
        5 => Color::Purple,
        6 => Color::Cyan,
        7 => Color::White,
        n => Color::Fixed(n),
    }
}

/// Parse "#rgb", "#rrggbb", "#rrggbbaa" in the (quirky) manner of syntect:
/// a 3-digit form yields each digit as the channel value.
fn parse_hex(s: &str) -> Option<(u8, u8, u8)> {
    let mut d = Vec::new();
    for c in s[1..].chars() {
        d.push(c.to_digit(16)? as u8);
    }
    match d.len() {
        3 => Some((d[0], d[1], d[2])),
        6 | 8 => Some(((d[0] << 4) | d[1], (d[2] << 4) | d[3], (d[4] << 4) | d[5])),
        _ => None,
    }
}

pub fn rgb_to_ansi_color(rgb: (u8, u8, u8), true_color: bool) -> Color {
    if true_color {
        Color::RGB(rgb.0, rgb.1, rgb.2)
    } else {
        Color::Fixed(ansi256_from_rgb(rgb.0, rgb.1, rgb.2))
    }
}

pub fn ansi_16_color_name_to_number(name: &str) -> Option<u8> {
    Some(match name {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" | "purple" => 5,
        "cyan" => 6,
        "white" => 7,
        "bright-black" | "brightblack" => 8,
        "bright-red" | "brightred" => 9,
        "bright-green" | "brightgreen" => 10,
        "bright-yellow" | "brightyellow" => 11,
        "bright-blue" | "brightblue" => 12,
        "bright-magenta" | "brightmagenta" | "bright-purple" | "brightpurple" => 13,
        "bright-cyan" | "brightcyan" => 14,
        "bright-white" | "brightwhite" => 15,
        _ => return None,
    })
}

pub fn ansi_16_color_number_to_name(n: u8) -> Option<&'static str> {
    Some(match n {
        0 => "black",
        1 => "red",
        2 => "green",
        3 => "yellow",
        4 => "blue",
        5 => "purple",
        6 => "cyan",
        7 => "white",
        8 => "bright-black",
        9 => "bright-red",
        10 => "bright-green",
        11 => "bright-yellow",
        12 => "bright-blue",
        13 => "bright-magenta",
        14 => "bright-cyan",
        15 => "bright-white",
        _ => return None,
    })
}

pub fn color_to_string(color: Color) -> String {
    match color {
        Color::Black => "black".to_string(),
        Color::Red => "red".to_string(),
        Color::Green => "green".to_string(),
        Color::Yellow => "yellow".to_string(),
        Color::Blue => "blue".to_string(),
        Color::Purple => "purple".to_string(),
        Color::Cyan => "cyan".to_string(),
        Color::White => "white".to_string(),
        Color::Fixed(n) if n < 16 => ansi_16_color_number_to_name(n).unwrap().to_string(),
        Color::Fixed(n) => n.to_string(),
        Color::RGB(r, g, b) => format!("\"#{:02x}{:02x}{:02x}\"", r, g, b),
    }
}

// ---------------------------------------------------------------------------
// RGB -> ANSI 256 palette conversion (perceptually weighted).
// ---------------------------------------------------------------------------

const CUBE: [u8; 6] = [0, 95, 135, 175, 215, 255];
const RED_THRESHOLDS: [u8; 5] = [38, 115, 155, 196, 235];
const GREEN_THRESHOLDS: [u8; 5] = [36, 116, 154, 195, 235];
const BLUE_THRESHOLDS: [u8; 5] = [35, 115, 155, 195, 235];
// Mapping of a pure grey level to the closest palette entry: (upper bound inclusive, index)
const GREY_RUNS: [(u8, u8); 30] = [
    (4, 16), (13, 232), (23, 233), (33, 234), (43, 235), (53, 236), (63, 237), (73, 238), (83, 239),
    (91, 240), (96, 59), (103, 241), (113, 242), (122, 243), (131, 244), (136, 102), (142, 245),
    (152, 246), (162, 247), (171, 248), (176, 145), (182, 249), (192, 250), (202, 251), (211, 252),
    (216, 188), (222, 253), (232, 254), (246, 255), (255, 231),
];

fn grey_index(v: u8) -> u8 {
    for (ub, i) in GREY_RUNS.iter() {
        if v <= *ub {
            return *i;
        }
    }
    231
}

pub fn rgb_from_ansi256(i: u8) -> (u8, u8, u8) {
    match i {
        16..=231 => {
            let i = i - 16;
            (CUBE[(i / 36) as usize], CUBE[((i / 6) % 6) as usize], CUBE[(i % 6) as usize])
        }
        232..=255 => {
            let v = 8 + 10 * (i - 232);
            (v, v, v)
        }
        _ => {
            // Standard 16 colors (approximate values)
            let table: [(u8, u8, u8); 16] = [
                (0, 0, 0), (128, 0, 0), (0, 128, 0), (128, 128, 0), (0, 0, 128), (128, 0, 128),
                (0, 128, 128), (192, 192, 192), (128, 128, 128), (255, 0, 0), (0, 255, 0),
                (255, 255, 0), (0, 0, 255), (255, 0, 255), (0, 255, 255), (255, 255, 255),
            ];
            table[i as usize]
        }
    }
}

fn cube_idx(v: u8, thresholds: &[u8; 5]) -> usize {
    for (i, t) in thresholds.iter().enumerate() {
        if v < *t {
            return i;
        }
    }
    5
}

fn distance(a: (u8, u8, u8), b: (u8, u8, u8)) -> i64 {
    let rs = a.0 as i64 + b.0 as i64;
    let dr = a.0 as i64 - b.0 as i64;
    let dg = a.1 as i64 - b.1 as i64;
    let db = a.2 as i64 - b.2 as i64;
    (1024 + rs) * dr * dr + 2048 * dg * dg + (1534 - rs) * db * db
}

fn luminance(r: u8, g: u8, b: u8) -> u8 {
    let v: u64 = 3567664 * r as u64 + 11998547 * g as u64 + 1211005 * b as u64 + (1 << 23);
    (v >> 24) as u8
}

pub fn ansi256_from_rgb(r: u8, g: u8, b: u8) -> u8 {
    if r == g && g == b {
        return grey_index(r);
    }
    let ci = (cube_idx(r, &RED_THRESHOLDS), cube_idx(g, &GREEN_THRESHOLDS), cube_idx(b, &BLUE_THRESHOLDS));
    let cube = (CUBE[ci.0], CUBE[ci.1], CUBE[ci.2]);
    let cube_index = 16 + 36 * ci.0 + 6 * ci.1 + ci.2;
    let gi = grey_index(luminance(r, g, b));
    let grey = rgb_from_ansi256(gi);
    if distance((r, g, b), cube) < distance((r, g, b), grey) {
        cube_index as u8
    } else {
        gi
    }
}

// ---------------------------------------------------------------------------
// CSS named colors
// ---------------------------------------------------------------------------

pub fn css_color(name: &str) -> Option<(u8, u8, u8)> {
    let name = name.replace("grey", "gray");
    CSS_COLORS
        .iter()
        .find(|(n, _, _, _)| *n == name)
        .map(|(_, r, g, b)| (*r, *g, *b))
}

