//! Delta styles: an ANSI style plus delta-specific flags.

use std::fmt;

use crate::ansi::AnsiStyle;
use crate::color;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum DecorationStyle {
    Box(AnsiStyle),
    Underline(AnsiStyle),
    Overline(AnsiStyle),
    UnderOverline(AnsiStyle),
    BoxWithUnderline(AnsiStyle),
    BoxWithOverline(AnsiStyle),
    BoxWithUnderOverline(AnsiStyle),
    NoDecoration,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Style {
    pub ansi_term_style: AnsiStyle,
    pub is_emph: bool,
    pub is_omitted: bool,
    pub is_raw: bool,
    pub is_syntax_highlighted: bool,
    pub decoration_style: DecorationStyle,
}

impl Default for Style {
    fn default() -> Self {
        Self::new()
    }
}

pub fn die_invalid_color(word: &str) -> ! {
    eprintln!("Invalid color or style attribute: {}", word);
    std::process::exit(2);
}

impl Style {
    pub fn new() -> Self {
        Style {
            ansi_term_style: AnsiStyle::new(),
            is_emph: false,
            is_omitted: false,
            is_raw: false,
            is_syntax_highlighted: false,
            decoration_style: DecorationStyle::NoDecoration,
        }
    }

    pub fn from_ansi_style(ansi_term_style: AnsiStyle) -> Self {
        Style {
            ansi_term_style,
            ..Style::new()
        }
    }

    pub fn from_colors(fg: Option<crate::ansi::Color>, bg: Option<crate::ansi::Color>) -> Self {
        Style {
            ansi_term_style: AnsiStyle {
                foreground: fg,
                background: bg,
                ..AnsiStyle::default()
            },
            ..Style::new()
        }
    }

    /// Construct a style from a style string, with the given default style used
    /// to resolve the special color "auto".
    pub fn from_str(
        style_string: &str,
        default: Option<Style>,
        decoration_style_string: Option<&str>,
        true_color: bool,
        is_emph: bool,
    ) -> Self {
        let (ansi_term_style, is_omitted, is_raw, is_syntax_highlighted) =
            parse_ansi_term_style(style_string, default, true_color);
        let decoration_style =
            DecorationStyle::from_str(decoration_style_string.unwrap_or(""), true_color);
        Style {
            ansi_term_style,
            is_emph,
            is_omitted,
            is_raw,
            is_syntax_highlighted,
            decoration_style,
        }
    }

    /// Like from_str, but also accepts style strings consisting of special
    /// attributes used in the hunk header ("file", "line-number") and in
    /// decoration styles.
    pub fn from_str_with_handling_of_special_decoration_attributes(
        style_string: &str,
        default: Option<Style>,
        decoration_style_string: Option<&str>,
        true_color: bool,
        is_emph: bool,
    ) -> Self {
        let (special, rest) = extract_special_decoration_attributes(style_string);
        let mut style = Style::from_str(&rest, default, decoration_style_string, true_color, is_emph);
        if special.contains(&"omit") || style.is_omitted {
            style.is_omitted = true;
        }
        style
    }

    pub fn from_git_str(git_str: &str) -> Self {
        Style::from_str(git_str, None, None, true, false)
    }

    pub fn paint(&self, text: &str) -> String {
        self.ansi_term_style.paint(text)
    }

    pub fn to_painted_string(&self) -> String {
        self.ansi_term_style.paint(&self.to_string())
    }

    pub fn is_applied_to(&self, s: &str) -> bool {
        match crate::ansi::parse_first_style(s) {
            Some(style) => style == self.ansi_term_style,
            None => false,
        }
    }

    pub fn has_background(&self) -> bool {
        self.ansi_term_style.background.is_some()
    }
}

/// Extract words that are special decoration attributes ("box", "ul", "ol",
/// "overline", "underline", "file", "line-number", "omit") -- used for
/// styles that may contain them. Returns (specials, remaining string).
fn extract_special_decoration_attributes(s: &str) -> (Vec<&'static str>, String) {
    let mut specials = Vec::new();
    let mut rest = Vec::new();
    for word in s.split_whitespace() {
        let lower = word.to_lowercase();
        let lower = lower.trim_matches(|c| c == '"' || c == '\'').to_string();
        match lower.as_str() {
            "box" => specials.push("box"),
            "ol" | "overline" => specials.push("ol"),
            "ul" | "underline" => specials.push("ul"),
            "file" => specials.push("file"),
            "line-number" => specials.push("line-number"),
            "omit" => specials.push("omit"),
            _ => rest.push(word),
        }
    }
    (specials, rest.join(" "))
}

fn parse_ansi_term_style(
    s: &str,
    default: Option<Style>,
    true_color: bool,
) -> (AnsiStyle, bool, bool, bool) {
    let mut style = AnsiStyle::new();
    let mut seen_foreground = false;
    let mut seen_background = false;
    let mut is_omitted = false;
    let mut is_raw = false;
    let mut is_syntax_highlighted = false;
    for word in s
        .to_lowercase()
        .split_whitespace()
        .map(|w| w.trim_matches(|c| c == '"' || c == '\''))
    {
        match word {
            "blink" => style.is_blink = true,
            "bold" => style.is_bold = true,
            "dim" => style.is_dimmed = true,
            "hidden" => style.is_hidden = true,
            "italic" => style.is_italic = true,
            "omit" => is_omitted = true,
            "raw" => is_raw = true,
            "reverse" => style.is_reverse = true,
            "strike" => style.is_strikethrough = true,
            "ul" | "underline" => style.is_underline = true,
            // Special attributes that may appear in hunk-header-style etc.
            "file" | "line-number" => {}
            _ if !seen_foreground => {
                if word == "syntax" {
                    is_syntax_highlighted = true;
                } else if word == "auto" {
                    style.foreground = default.and_then(|d| d.ansi_term_style.foreground);
                } else {
                    match color::parse_color(word, true_color) {
                        Ok(c) => style.foreground = c,
                        Err(()) => die_invalid_color(word),
                    }
                }
                seen_foreground = true;
            }
            _ if !seen_background => {
                if word == "syntax" {
                    eprintln!("You have used the special color 'syntax' as a background color (second color in a style string). It may only be used as a foreground color (first color in a style string).");
                    std::process::exit(2);
                } else if word == "auto" {
                    style.background = default.and_then(|d| d.ansi_term_style.background);
                } else {
                    match color::parse_color(word, true_color) {
                        Ok(c) => style.background = c,
                        Err(()) => die_invalid_color(word),
                    }
                }
                seen_background = true;
            }
            _ => {
                eprintln!(
                    "Invalid style string: {}. See the STYLES section of delta --help.",
                    s
                );
                std::process::exit(2);
            }
        }
    }
    (style, is_omitted, is_raw, is_syntax_highlighted)
}

impl DecorationStyle {
    pub fn from_str(style_string: &str, true_color: bool) -> Self {
        let (specials, rest) = extract_special_decoration_attributes(style_string);
        let (ansi_style, _, _, _) = parse_ansi_term_style(&rest, None, true_color);
        let has_box = specials.contains(&"box");
        let has_ul = specials.contains(&"ul");
        let has_ol = specials.contains(&"ol");
        if specials.contains(&"omit") {
            return DecorationStyle::NoDecoration;
        }
        match (has_box, has_ul, has_ol) {
            (true, false, false) => DecorationStyle::Box(ansi_style),
            (false, true, false) => DecorationStyle::Underline(ansi_style),
            (false, false, true) => DecorationStyle::Overline(ansi_style),
            (false, true, true) => DecorationStyle::UnderOverline(ansi_style),
            (true, true, false) => DecorationStyle::BoxWithUnderline(ansi_style),
            (true, false, true) => DecorationStyle::BoxWithOverline(ansi_style),
            (true, true, true) => DecorationStyle::BoxWithUnderOverline(ansi_style),
            (false, false, false) => DecorationStyle::NoDecoration,
        }
    }

    pub fn ansi_style(&self) -> Option<AnsiStyle> {
        match self {
            DecorationStyle::Box(s)
            | DecorationStyle::Underline(s)
            | DecorationStyle::Overline(s)
            | DecorationStyle::UnderOverline(s)
            | DecorationStyle::BoxWithUnderline(s)
            | DecorationStyle::BoxWithOverline(s)
            | DecorationStyle::BoxWithUnderOverline(s) => Some(*s),
            DecorationStyle::NoDecoration => None,
        }
    }
}

impl fmt::Display for Style {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        if self.is_raw {
            return f.write_str("raw");
        }
        let mut words: Vec<String> = Vec::new();
        if self.is_omitted {
            words.push("omit".into());
        }
        let a = &self.ansi_term_style;
        if a.is_blink {
            words.push("blink".into());
        }
        if a.is_bold {
            words.push("bold".into());
        }
        if a.is_dimmed {
            words.push("dim".into());
        }
        if a.is_italic {
            words.push("italic".into());
        }
        if a.is_reverse {
            words.push("reverse".into());
        }
        if a.is_strikethrough {
            words.push("strike".into());
        }
        if a.is_underline {
            words.push("ul".into());
        }
        if self.is_syntax_highlighted {
            words.push("syntax".into());
        } else {
            match a.foreground {
                Some(c) => words.push(color::color_to_string(c)),
                None => words.push("normal".into()),
            }
        }
        if let Some(bg) = a.background {
            words.push(color::color_to_string(bg));
        }
        f.write_str(&words.join(" "))
    }
}
