                if include_condition_matches(cond) {
                    let inc = expand_include_path(&value, path);
                    self.load_file(&inc, depth + 1);
                }
            } else {
                self.insert(&key, value);
            }
        }
    }

    pub fn get_string(&self, key: &str) -> Option<String> {
        self.entries
            .get(&normalize_key(key))
            .and_then(|v| v.last().cloned())
    }

    pub fn get_bool(&self, key: &str) -> Option<bool> {
        self.get_string(key).and_then(|s| parse_bool(&s))
    }

    pub fn get_i64(&self, key: &str) -> Option<i64> {
        self.get_string(key).and_then(|s| parse_int(&s))
    }

    pub fn get_f64(&self, key: &str) -> Option<f64> {
        self.get_string(key).and_then(|s| s.trim().parse::<f64>().ok())
    }

    /// Does the config contain any key under the given section (e.g. "delta.myfeature")?
    pub fn has_section(&self, section: &str) -> bool {
        let prefix = format!("{}.", normalize_key(section));
        self.entries.keys().any(|k| k.starts_with(&prefix))
    }

    /// Return names of subsections of `section` (e.g. feature names under "delta").
    pub fn subsections(&self, section: &str) -> Vec<String> {
        let prefix = format!("{}.", section.to_lowercase());
        let mut out = Vec::new();
        for k in self.entries.keys() {
            if let Some(rest) = k.strip_prefix(&prefix) {
                if let Some(idx) = rest.rfind('.') {
                    let sub = &rest[..idx];
                    if !out.contains(&sub.to_string()) {
                        out.push(sub.to_string());
                    }
                }
            }
        }
        out.sort();
        out
    }
}

/// Normalize "Section.SubSection.Key" -> "section.SubSection.key"
fn normalize_key(key: &str) -> String {
    let parts: Vec<&str> = key.splitn(2, '.').collect();
    if parts.len() < 2 {
        return key.to_lowercase();
    }
    let section = parts[0].to_lowercase();
    let rest = parts[1];
    match rest.rfind('.') {
        Some(idx) => format!("{}.{}.{}", section, &rest[..idx], rest[idx + 1..].to_lowercase()),
        None => format!("{}.{}", section, rest.to_lowercase()),
    }
}

pub fn parse_bool(s: &str) -> Option<bool> {
    match s.to_lowercase().as_str() {
        "true" | "yes" | "on" | "1" => Some(true),
        "false" | "no" | "off" | "0" | "" => Some(false),
        _ => None,
    }
}

fn parse_int(s: &str) -> Option<i64> {
    let s = s.trim();
    let (num, mult) = if let Some(n) = s.strip_suffix(|c| c == 'k' || c == 'K') {
        (n, 1024)
    } else if let Some(n) = s.strip_suffix(|c| c == 'm' || c == 'M') {
        (n, 1024 * 1024)
    } else if let Some(n) = s.strip_suffix(|c| c == 'g' || c == 'G') {
        (n, 1024 * 1024 * 1024)
    } else {
        (s, 1)
    };
    num.parse::<i64>().ok().map(|n| n * mult)
}

fn expand_include_path(value: &str, current: &Path) -> PathBuf {
    let p = if let Some(rest) = value.strip_prefix("~/") {
        match std::env::var_os("HOME") {
            Some(h) => PathBuf::from(h).join(rest),
            None => PathBuf::from(value),
        }
    } else {
        PathBuf::from(value)
    };
    if p.is_absolute() {
        p
    } else {
        current.parent().unwrap_or(Path::new(".")).join(p)
    }
}

fn include_condition_matches(cond: &str) -> bool {
    // Only "gitdir:" conditions are (approximately) supported.
    let (kind, pattern) = match cond.find(':') {
        Some(i) => (&cond[..i], &cond[i + 1..]),
        None => return false,
    };
    match kind {
        "gitdir" | "gitdir/i" => {
            let gitdir = match find_git_dir() {
                Some(g) => g,
                None => return false,
            };
            let gitdir_str = gitdir.to_string_lossy().to_string();
            let mut pattern = pattern.to_string();
            if let Some(rest) = pattern.strip_prefix("~/") {
                if let Some(h) = std::env::var_os("HOME") {
                    pattern = format!("{}/{}", h.to_string_lossy(), rest);
                }
            }
            if pattern.ends_with('/') {
                pattern.push_str("**");
            }
            let (g, p) = if kind == "gitdir/i" {
                (gitdir_str.to_lowercase(), pattern.to_lowercase())
            } else {
                (gitdir_str, pattern)
            };
            glob_match(&p, &g) || glob_match(&p, &format!("{}/", g))
        }
        _ => false,
    }
}

fn glob_match(pattern: &str, text: &str) -> bool {
    // Simple glob: supports ** (any), * (no slash), ? (single non-slash char)
    fn rec(p: &[char], t: &[char]) -> bool {
        if p.is_empty() {
            return t.is_empty();
        }
        if p.len() >= 2 && p[0] == '*' && p[1] == '*' {
            let mut rest = &p[2..];
            if !rest.is_empty() && rest[0] == '/' {
                rest = &rest[1..];
                // ** followed by /: match zero or more directories
                for i in 0..=t.len() {
                    if (i == 0 || t[i - 1] == '/') && rec(rest, &t[i..]) {
                        return true;
                    }
                }
                return false;
            }
            for i in 0..=t.len() {
                if rec(rest, &t[i..]) {
                    return true;
                }
            }
            return false;
        }
        match p[0] {
            '*' => {
                for i in 0..=t.len() {
                    if i > 0 && t[i - 1] == '/' {
                        break;
                    }
                    if rec(&p[1..], &t[i..]) {
                        return true;
                    }
                }
                false
            }
            '?' => !t.is_empty() && t[0] != '/' && rec(&p[1..], &t[1..]),
            c => !t.is_empty() && t[0] == c && rec(&p[1..], &t[1..]),
        }
    }
    let p: Vec<char> = pattern.chars().collect();
    let t: Vec<char> = text.chars().collect();
    rec(&p, &t)
}

fn find_git_dir() -> Option<PathBuf> {
    let mut dir = std::env::current_dir().ok()?;
    loop {
        let candidate = dir.join(".git");
        if candidate.is_dir() {
            return Some(candidate);
        }
        if candidate.is_file() {
            // worktree / submodule: "gitdir: path"
            if let Ok(content) = std::fs::read_to_string(&candidate) {
                if let Some(rest) = content.trim().strip_prefix("gitdir:") {
                    let p = PathBuf::from(rest.trim());
                    return Some(if p.is_absolute() { p } else { dir.join(p) });
                }
            }
            return Some(candidate);
        }
        if !dir.pop() {
            return None;
        }
    }
}

fn find_repo_config() -> Option<PathBuf> {
    let gitdir = find_git_dir()?;
    let cfg = gitdir.join("config");
    if cfg.exists() {
        Some(cfg)
    } else {
        // worktree: commondir
        let commondir = gitdir.join("commondir");
        if let Ok(c) = std::fs::read_to_string(&commondir) {
            let p = gitdir.join(c.trim()).join("config");
            if p.exists() {
                return Some(p);
            }
        }
        None
    }
}

/// Parse git config content into (normalized key, value) pairs in order.
pub fn parse_git_config(content: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut section = String::new();
    let chars: Vec<char> = content.chars().collect();
    let mut i = 0;
    let n = chars.len();
    while i < n {
        // skip whitespace and blank lines
        while i < n && (chars[i] == ' ' || chars[i] == '\t' || chars[i] == '\r' || chars[i] == '\n') {
            i += 1;
        }
        if i >= n {
            break;
        }
        let c = chars[i];
        if c == '#' || c == ';' {
            while i < n && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        if c == '[' {
            // section header
            i += 1;
            let mut name = String::new();
            while i < n && chars[i] != ']' && chars[i] != '"' && chars[i] != '\n' {
                name.push(chars[i]);
                i += 1;
            }
            let mut sub: Option<String> = None;
            if i < n && chars[i] == '"' {
                i += 1;
                let mut s = String::new();
                while i < n && chars[i] != '"' && chars[i] != '\n' {
                    if chars[i] == '\\' && i + 1 < n {
                        i += 1;
                    }
                    s.push(chars[i]);
                    i += 1;
                }
                if i < n && chars[i] == '"' {
                    i += 1;
                }
                sub = Some(s);
                while i < n && chars[i] != ']' && chars[i] != '\n' {
                    i += 1;
                }
            }
            if i < n && chars[i] == ']' {
                i += 1;
            }
            let name = name.trim();
            section = match sub {
                Some(s) => format!("{}.{}", name.to_lowercase(), s),
                None => {
                    // deprecated [section.subsection] form: entire thing lowercased
                    name.to_lowercase()
                }
            };
            // skip rest of line
            while i < n && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        // key [= value]
        let mut key = String::new();
        while i < n && (chars[i].is_alphanumeric() || chars[i] == '-') {
            key.push(chars[i]);
            i += 1;
        }
        if key.is_empty() {
            // invalid; skip line
            while i < n && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        while i < n && (chars[i] == ' ' || chars[i] == '\t') {
            i += 1;
        }
        let mut value = String::new();
        let mut has_value = false;
        if i < n && chars[i] == '=' {
            has_value = true;
            i += 1;
            // parse value
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                i += 1;
            }
            let mut in_quotes = false;
            let mut pending_space = String::new();
            while i < n {
                let c = chars[i];
                if c == '\n' {
                    break;
                }
                if c == '\\' {
                    if i + 1 < n {
                        let next = chars[i + 1];
                        i += 2;
                        value.push_str(&pending_space);
                        pending_space.clear();
                        match next {
                            '\n' => {
                                // line continuation
                            }
                            '\r' => {
                                if i < n && chars[i] == '\n' {
                                    i += 1;
                                }
                            }
                            'n' => value.push('\n'),
                            't' => value.push('\t'),
                            'b' => value.push('\x08'),
                            '"' => value.push('"'),
                            '\\' => value.push('\\'),
                            other => value.push(other),
                        }
                        continue;
                    } else {
                        i += 1;
                        continue;
                    }
                }
                if c == '"' {
                    in_quotes = !in_quotes;
                    value.push_str(&pending_space);
                    pending_space.clear();
                    i += 1;
                    continue;
                }
                if !in_quotes && (c == '#' || c == ';') {
                    // comment: rest of line
                    while i < n && chars[i] != '\n' {
                        i += 1;
                    }
                    break;
                }
                if !in_quotes && (c == ' ' || c == '\t' || c == '\r') {
                    pending_space.push(c);
                    i += 1;
                    continue;
                }
                value.push_str(&pending_space);
                pending_space.clear();
                value.push(c);
                i += 1;
            }
        } else {
            // skip rest of line (may be a comment)
            while i < n && chars[i] != '\n' {
                i += 1;
            }
        }
        let full_key = if section.is_empty() {
            key.to_lowercase()
        } else {
            format!("{}.{}", section, key.to_lowercase())
        };
        if has_value {
            out.push((full_key, value));
        } else {
            out.push((full_key, "true".to_string()));
        }
    }
    out
}
