//! Builtin features: named collections of option values.

use crate::cli::Opt;
use crate::gitconfig::GitConfig;

#[derive(Clone, Debug, PartialEq)]
pub enum OptionValue {
    Boolean(bool),
    Float(f64),
    Int(usize),
    Str(String),
}

impl From<bool> for OptionValue {
    fn from(b: bool) -> Self {
        OptionValue::Boolean(b)
    }
}
impl From<&str> for OptionValue {
    fn from(s: &str) -> Self {
        OptionValue::Str(s.to_string())
    }
}
impl From<String> for OptionValue {
    fn from(s: String) -> Self {
        OptionValue::Str(s)
    }
}
impl From<usize> for OptionValue {
    fn from(n: usize) -> Self {
        OptionValue::Int(n)
    }
}
impl From<f64> for OptionValue {
    fn from(n: f64) -> Self {
        OptionValue::Float(n)
    }
}

pub type ValueFn = fn(&Opt) -> OptionValue;

/// (option name, git config key to consult first, default value function)
pub type BuiltinFeature = Vec<(&'static str, Option<&'static str>, ValueFn)>;

pub const BUILTIN_FEATURE_NAMES: &[&str] = &[
    "color-only",
    "diff-highlight",
    "diff-so-fancy",
    "hyperlinks",
    "line-numbers",
    "navigate",
    "raw",
    "side-by-side",
];

pub fn is_builtin(name: &str) -> bool {
    BUILTIN_FEATURE_NAMES.contains(&name)
}

pub fn get_builtin_feature(name: &str) -> Option<BuiltinFeature> {
    Some(match name {
        "color-only" => vec![
            ("color-only", None, |_| true.into()),
            ("commit-style", None, |_| "raw".into()),
            ("file-style", None, |_| "raw".into()),
            ("hunk-header-style", None, |_| "raw".into()),
            ("keep-plus-minus-markers", None, |_| true.into()),
            ("tabs", None, |_| 0usize.into()),
        ],
        "raw" => vec![
            ("raw", None, |_| true.into()),
            ("commit-style", None, |_| "raw".into()),
            ("file-style", None, |_| "raw".into()),
            ("hunk-header-style", None, |_| "raw".into()),
            ("minus-style", Some("color.diff.old"), |_| "red".into()),
            ("minus-emph-style", Some("color.diff.old"), |o| o.minus_style.clone().into()),
            ("zero-style", None, |_| "normal".into()),
            ("plus-style", Some("color.diff.new"), |_| "green".into()),
            ("plus-emph-style", Some("color.diff.new"), |o| o.plus_style.clone().into()),
            ("keep-plus-minus-markers", None, |_| true.into()),
            ("tabs", None, |_| 0usize.into()),
        ],
        "diff-highlight" => diff_highlight_feature(false),
        "diff-so-fancy" => {
            let mut f = diff_highlight_feature(true);
            f.extend(vec![
                ("diff-so-fancy", None, |_| true.into()) as (&str, Option<&str>, ValueFn),
                ("commit-style", Some("color.diff.commit"), |_| "bold yellow".into()),
                ("commit-decoration-style", None, |_| "none".into()),
                ("file-style", Some("color.diff.meta"), |_| "11".into()),
                ("file-decoration-style", None, |_| "bold yellow ul ol".into()),
                ("hunk-header-style", Some("color.diff.frag"), |_| "bold syntax".into()),
                ("hunk-header-decoration-style", None, |_| "magenta box".into()),
                ("minus-emph-style", Some("color.diff-highlight.oldHighlight"), |_| "bold red 52".into()),
                ("plus-emph-style", Some("color.diff-highlight.newHighlight"), |_| "bold green 22".into()),
            ]);
            f
        }
        "hyperlinks" => vec![("hyperlinks", None, |_| true.into())],
        "line-numbers" => vec![
            ("line-numbers", None, |_| true.into()),
            ("line-numbers-left-style", None, |_| "blue".into()),
            ("line-numbers-right-style", None, |_| "blue".into()),
            ("line-numbers-minus-style", None, |_| "88".into()),
            ("line-numbers-zero-style", None, |_| "#444444".into()),
            ("line-numbers-plus-style", None, |_| "28".into()),
        ],
