            ("features", None, |_| "line-numbers".into()),
            ("line-numbers-left-format", None, |_| "│{nm:^4}│".into()),
            ("line-numbers-right-format", None, |_| "│{np:^4}│".into()),
        ],
        _ => return None,
    })
}

fn diff_highlight_feature(bold: bool) -> BuiltinFeature {
    let mut f: BuiltinFeature = vec![
        ("diff-highlight", None, |_| true.into()),
        ("commit-style", Some("color.diff.commit"), |_| "raw".into()),
        ("file-style", None, |_| "raw".into()),
        ("hunk-header-style", None, |_| "raw".into()),
    ];
    if bold {
        f.push(("minus-style", Some("color.diff.old"), |_| "bold red".into()));
    } else {
        f.push(("minus-style", Some("color.diff.old"), |_| "red".into()));
    }
    f.push(("minus-non-emph-style", Some("color.diff-highlight.oldNormal"), |o| o.minus_style.clone().into()));
    f.push(("minus-emph-style", Some("color.diff-highlight.oldHighlight"), |o| format!("{} reverse", o.minus_style).into()));
    f.push(("zero-style", None, |_| "normal".into()));
    if bold {
        f.push(("plus-style", Some("color.diff.new"), |_| "bold green".into()));
    } else {
        f.push(("plus-style", Some("color.diff.new"), |_| "green".into()));
    }
    f.push(("plus-non-emph-style", Some("color.diff-highlight.newNormal"), |o| o.plus_style.clone().into()));
    f.push(("plus-emph-style", Some("color.diff-highlight.newHighlight"), |o| format!("{} reverse", o.plus_style).into()));
    f
}

/// Gather the list of active features, in order of decreasing precedence
/// (the first feature in the list that defines an option wins).
pub fn gather_features(opt: &Opt, git_config: Option<&GitConfig>) -> Vec<String> {
    let mut features: Vec<String> = Vec::new();

    let env_features = std::env::var("DELTA_FEATURES").ok();
    let mut cli_features: Option<String> = opt.features.clone();
    let mut env_prefix: Vec<String> = Vec::new();
    if let Some(env) = env_features {
        if let Some(stripped) = env.strip_prefix('+') {
            env_prefix = stripped.split_whitespace().map(|s| s.to_lowercase()).collect();
        } else {
            cli_features = Some(env);
        }
    }

    for f in env_prefix {
        gather_feature(&f, &mut features, opt, git_config);
    }

    if let Some(cli) = &cli_features {
        for f in cli.to_lowercase().split_whitespace().rev() {
            gather_feature(f, &mut features, opt, git_config);
        }
    }

    // Builtin features activated by command line flags
    let flags: [(&str, bool); 8] = [
        ("raw", opt.raw),
        ("color-only", opt.color_only),
        ("diff-highlight", opt.diff_highlight),
        ("diff-so-fancy", opt.diff_so_fancy),
        ("hyperlinks", opt.hyperlinks),
        ("line-numbers", opt.line_numbers),
        ("navigate", opt.navigate),
        ("side-by-side", opt.side_by_side),
    ];
    for (name, on) in flags {
        if on {
            gather_builtin_feature(name, &mut features, opt);
        }
    }

    if cli_features.is_none() {
        if let Some(gc) = git_config {
            if let Some(fs) = gc.get_string("delta.features") {
                for f in fs.to_lowercase().split_whitespace().rev() {
                    gather_feature(f, &mut features, opt, git_config);
                }
            }
            gather_builtin_features_from_flags_in_gitconfig("delta", &mut features, opt, gc);
        }
    }
    features
}

fn gather_feature(feature: &str, features: &mut Vec<String>, opt: &Opt, git_config: Option<&GitConfig>) {
    if is_builtin(feature) {
        gather_builtin_feature(feature, features, opt);
    } else {
        if features.iter().any(|f| f == feature) {
            return;
        }
        features.push(feature.to_string());
    }
    if let Some(gc) = git_config {
        if let Some(children) = gc.get_string(&format!("delta.{}.features", feature)) {
            for child in children.to_lowercase().split_whitespace().rev() {
                if !features.iter().any(|f| f == child) {
                    gather_feature(child, features, opt, git_config);
                }
            }
        }
        gather_builtin_features_from_flags_in_gitconfig(feature, features, opt, gc);
    }
}

fn gather_builtin_feature(feature: &str, features: &mut Vec<String>, opt: &Opt) {
    if features.iter().any(|f| f == feature) {
        return;
    }
    features.push(feature.to_string());
    if let Some(data) = get_builtin_feature(feature) {
        for (name, _, f) in data {
            if name == "features" {
                if let OptionValue::Str(children) = f(opt) {
                    for child in children.split_whitespace().rev() {
                        gather_builtin_feature(child, features, opt);
                    }
                }
            }
        }
    }
}

fn gather_builtin_features_from_flags_in_gitconfig(
    section: &str,
    features: &mut Vec<String>,
    opt: &Opt,
    gc: &GitConfig,
) {
    for name in BUILTIN_FEATURE_NAMES {
        let key = if section == "delta" {
            format!("delta.{}", name)
        } else {
            format!("delta.{}.{}", section, name)
        };
        if gc.get_bool(&key) == Some(true) {
            gather_builtin_feature(name, features, opt);
        }
    }
}
