//! Resolution of option values from command line, git config, features, and defaults.

use clap::parser::ValueSource;
use clap::ArgMatches;

use crate::cli::Opt;
use crate::features::{self, OptionValue};
use crate::gitconfig::GitConfig;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Bool,
    Int,
    Float,
    Str,
    OptStr,
}

fn user_supplied(m: &ArgMatches, id: &str) -> bool {
    matches!(m.value_source(id), Some(ValueSource::CommandLine))
}

fn gitconfig_value(gc: &GitConfig, key: &str, kind: Kind) -> Option<OptionValue> {
    match kind {
        Kind::Bool => gc.get_bool(key).map(OptionValue::Boolean),
        Kind::Int => gc.get_i64(key).map(|n| OptionValue::Int(n.max(0) as usize)),
        Kind::Float => gc.get_f64(key).map(OptionValue::Float),
        Kind::Str | Kind::OptStr => gc.get_string(key).map(OptionValue::Str),
    }
}

/// Look up the value of an option by name, not considering the command line.
fn get_option_value(
    name: &str,
    kind: Kind,
    opt: &Opt,
    features: &[String],
    gc: Option<&GitConfig>,
) -> Option<OptionValue> {
    if let Some(gc) = gc {
        if let Some(v) = gitconfig_value(gc, &format!("delta.{}", name), kind) {
            return Some(v);
        }
    }
    for feature in features {
        if let Some(gc) = gc {
            if let Some(v) = gitconfig_value(gc, &format!("delta.{}.{}", feature, name), kind) {
                return Some(v);
            }
        }
        if let Some(bf) = features::get_builtin_feature(feature) {
            for (oname, git_key, f) in bf {
                if oname == name {
                    if let (Some(key), Some(gc)) = (git_key, gc) {
                        if let Some(v) = gitconfig_value(gc, key, kind) {
                            return Some(v);
                        }
                    }
                    return Some(f(opt));
                }
            }
        }
    }
    None
}

fn to_bool(v: OptionValue) -> Option<bool> {
    match v {
        OptionValue::Boolean(b) => Some(b),
        OptionValue::Str(s) => crate::gitconfig::parse_bool(&s),
        _ => None,
    }
}
fn to_int(v: OptionValue) -> Option<usize> {
    match v {
        OptionValue::Int(n) => Some(n),
        OptionValue::Float(f) => Some(f as usize),
        OptionValue::Str(s) => s.trim().parse().ok(),
        OptionValue::Boolean(_) => None,
    }
}
fn to_float(v: OptionValue) -> Option<f64> {
    match v {
        OptionValue::Float(f) => Some(f),
        OptionValue::Int(n) => Some(n as f64),
        OptionValue::Str(s) => s.trim().parse().ok(),
        OptionValue::Boolean(_) => None,
    }
}
fn to_str(v: OptionValue) -> Option<String> {
    match v {
        OptionValue::Str(s) => Some(s),
        OptionValue::Boolean(b) => Some(b.to_string()),
        OptionValue::Int(n) => Some(n.to_string()),
        OptionValue::Float(f) => Some(f.to_string()),
    }
}

macro_rules! set_option {
    ($opt:ident, $m:ident, $features:ident, $gc:ident, $field:ident, $name:expr, bool) => {
        if !user_supplied($m, stringify!($field)) {
            if let Some(v) = get_option_value($name, Kind::Bool, &$opt, &$features, $gc).and_then(to_bool) {
                $opt.$field = v;
            }
        }
    };
    ($opt:ident, $m:ident, $features:ident, $gc:ident, $field:ident, $name:expr, int) => {
        if !user_supplied($m, stringify!($field)) {
            if let Some(v) = get_option_value($name, Kind::Int, &$opt, &$features, $gc).and_then(to_int) {
                $opt.$field = v;
            }
        }
    };
    ($opt:ident, $m:ident, $features:ident, $gc:ident, $field:ident, $name:expr, float) => {
        if !user_supplied($m, stringify!($field)) {
            if let Some(v) = get_option_value($name, Kind::Float, &$opt, &$features, $gc).and_then(to_float) {
                $opt.$field = v;
            }
        }
    };
    ($opt:ident, $m:ident, $features:ident, $gc:ident, $field:ident, $name:expr, str) => {
        if !user_supplied($m, stringify!($field)) {
            if let Some(v) = get_option_value($name, Kind::Str, &$opt, &$features, $gc).and_then(to_str) {
                $opt.$field = v;
            }
        }
    };
    ($opt:ident, $m:ident, $features:ident, $gc:ident, $field:ident, $name:expr, optstr) => {
        if !user_supplied($m, stringify!($field)) {
            if let Some(v) = get_option_value($name, Kind::OptStr, &$opt, &$features, $gc).and_then(to_str) {
                $opt.$field = Some(v);
            }
        }
    };
}

