    // Lowest-precedence defaults that depend on other options.
    if opt.side_by_side {
        if !user_supplied(m, "minus_style")
            && get_option_value("minus-style", Kind::Str, opt, &features, gc).is_none()
        {
            opt.minus_style = "syntax auto".to_string();
        }
        if !user_supplied(m, "minus_emph_style")
            && get_option_value("minus-emph-style", Kind::Str, opt, &features, gc).is_none()
        {
