    let plus_empty_line_marker_style = Style::from_str(
        &opt.plus_empty_line_marker_style,
        Some(Style::from_colors(None, Some(get_plus_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        false,
    );
    let whitespace_error_style = Style::from_str(&opt.whitespace_error_style, None, None, true_color, false);
    [
        minus_style,
        minus_emph_style,
        minus_non_emph_style,
        minus_empty_line_marker_style,
        zero_style,
        plus_style,
        plus_emph_style,
        plus_non_emph_style,
        plus_empty_line_marker_style,
        whitespace_error_style,
    ]
}

fn make_line_number_styles(opt: &Opt) -> (Style, Style, Style, Style, Style) {
    let true_color = opt.computed.true_color;
    let left = Style::from_str(&opt.line_numbers_left_style, None, None, true_color, false);
    let minus = Style::from_str(&opt.line_numbers_minus_style, None, None, true_color, false);
    let zero = Style::from_str(&opt.line_numbers_zero_style, None, None, true_color, false);
    let plus = Style::from_str(&opt.line_numbers_plus_style, None, None, true_color, false);
    let right = Style::from_str(&opt.line_numbers_right_style, None, None, true_color, false);
    (left, minus, zero, plus, right)
}

fn make_commit_file_hunk_header_styles(opt: &Opt) -> (Style, Style, Style, Style, Style) {
    let true_color = opt.computed.true_color;
    let commit_style = Style::from_str_with_handling_of_special_decoration_attributes(
        &opt.commit_style,
        None,
        Some(&opt.commit_decoration_style),
        true_color,
        false,
    );
    let file_style = Style::from_str_with_handling_of_special_decoration_attributes(
        &opt.file_style,
        None,
        Some(&opt.file_decoration_style),
        true_color,
        false,
    );
    let hunk_header_style = Style::from_str_with_handling_of_special_decoration_attributes(
        &opt.hunk_header_style,
        None,
        Some(&opt.hunk_header_decoration_style),
        true_color,
        false,
    );
    let hunk_header_file_style = Style::from_str(&opt.hunk_header_file_style, None, None, true_color, false);
    let hunk_header_line_number_style = Style::from_str(&opt.hunk_header_line_number_style, None, None, true_color, false);
    (commit_style, file_style, hunk_header_style, hunk_header_file_style, hunk_header_line_number_style)
}

fn make_blame_palette(blame_palette: Option<&str>, is_light_mode: bool) -> Vec<String> {
    match (blame_palette, is_light_mode) {
        (Some(palette), _) => palette.split_whitespace().map(|s| s.to_string()).collect(),
        (None, false) => vec!["#000000".into(), "#222222".into(), "#444444".into()],
        (None, true) => vec!["#FFFFFF".into(), "#DDDDDD".into(), "#BBBBBB".into()],
    }
}

pub fn parse_styles_map(opt: &Opt) -> Option<HashMap<Style, Style>> {
    let s = opt.map_styles.as_ref()?;
    let true_color = opt.computed.true_color;
    let mut map = HashMap::new();
    for pair in s.split(',') {
        let mut parts = pair.split("=>");
        let from = parts.next().map(|s| s.trim());
        let to = parts.next().map(|s| s.trim());
        if let (Some(from), Some(to)) = (from, to) {
            let from_style = Style::from_str(from, None, None, true_color, false);
            let to_style = Style::from_str(to, None, None, true_color, false);
            map.insert(from_style, to_style);
        }
    }
    Some(map)
}

fn parse_file_transformation(s: Option<&str>) -> Option<(Regex, String)> {
    let s = s?;
    // s/pattern/replacement/ with arbitrary delimiter after 's'
    let mut chars = s.chars();
    if chars.next() != Some('s') {
        eprintln!("Invalid value for file-transformation: {}", s);
        std::process::exit(2);
    }
    let delim = match chars.next() {
        Some(d) => d,
        None => {
            eprintln!("Invalid value for file-transformation: {}", s);
            std::process::exit(2);
        }
    };
    let rest: String = chars.collect();
    let parts: Vec<&str> = rest.split(delim).collect();
    if parts.len() < 2 {
        eprintln!("Invalid value for file-transformation: {}", s);
        std::process::exit(2);
    }
    let regex = match Regex::new(parts[0]) {
        Ok(r) => r,
        Err(_) => {
            eprintln!("Invalid value for file-transformation: {}", s);
            std::process::exit(2);
        }
    };
    Some((regex, parts[1].to_string()))
}

impl From<Opt> for Config {
    fn from(opt: Opt) -> Self {
        let true_color = opt.computed.true_color;
        let [minus_style, minus_emph_style, minus_non_emph_style, minus_empty_line_marker_style, zero_style, plus_style, plus_emph_style, plus_non_emph_style, plus_empty_line_marker_style, whitespace_error_style] =
            make_hunk_styles(&opt);
        let (commit_style, file_style, hunk_header_style, hunk_header_file_style, hunk_header_line_number_style) =
            make_commit_file_hunk_header_styles(&opt);
        let (line_numbers_left_style, line_numbers_minus_style, line_numbers_zero_style, line_numbers_plus_style, line_numbers_right_style) =
            make_line_number_styles(&opt);

        let inline_hint_style = Style::from_str(&opt.inline_hint_style, None, None, true_color, false);

        let grep_match_line_style = match &opt.grep_match_line_style {
            Some(s) => Style::from_str(s, None, None, true_color, false),
            None => plus_style,
        };
        let grep_match_word_style = match &opt.grep_match_word_style {
            Some(s) => Style::from_str(s, None, None, true_color, false),
            None => plus_emph_style,
        };
        let grep_context_line_style = match &opt.grep_context_line_style {
            Some(s) => Style::from_str(s, None, None, true_color, false),
            None => zero_style,
        };
        let grep_file_style = Style::from_str(&opt.grep_file_style, None, None, true_color, false);
        let grep_line_number_style = Style::from_str(&opt.grep_line_number_style, None, None, true_color, false);
        let grep_header_file_style = opt
            .grep_header_file_style
            .as_ref()
            .map(|s| Style::from_str(s, None, None, true_color, false));
        let grep_output_type = match opt.grep_output_type.as_deref() {
            Some("ripgrep") => Some(GrepType::Ripgrep),
            Some("classic") => Some(GrepType::Classic),
            _ => None,
        };

        let blame_palette_strings = make_blame_palette(opt.blame_palette.as_deref(), opt.computed.is_light_mode);
        let blame_palette: Vec<AnsiStyle> = blame_palette_strings
            .iter()
            .map(|s| Style::from_str(&format!("normal {}", s), None, None, true_color, false).ansi_term_style)
            .collect();
        let blame_code_style = opt
            .blame_code_style
            .as_ref()
            .map(|s| Style::from_str(s, None, None, true_color, false));
        let blame_separator_style = opt
            .blame_separator_style
            .as_ref()
            .map(|s| Style::from_str(s, None, None, true_color, false));

        let merge_conflict_ours_diff_header_style = Style::from_str_with_handling_of_special_decoration_attributes(
            &opt.merge_conflict_ours_diff_header_style,
            None,
            Some(&opt.merge_conflict_ours_diff_header_decoration_style),
            true_color,
            false,
        );
        let merge_conflict_theirs_diff_header_style = Style::from_str_with_handling_of_special_decoration_attributes(
            &opt.merge_conflict_theirs_diff_header_style,
            None,
            Some(&opt.merge_conflict_theirs_diff_header_decoration_style),
            true_color,
            false,
        );

        let navigate_regex = if opt.navigate || opt.show_themes {
            Some(match &opt.navigate_regex {
                None => make_navigate_regex(
                    opt.show_themes,
                    &opt.file_modified_label,
                    &opt.file_added_label,
                    &opt.file_removed_label,
                    &opt.file_renamed_label,
                    &opt.hunk_label,
                ),
                Some(s) => s.clone(),
            })
        } else {
            None
        };

        let styles_map = parse_styles_map(&opt);

        let tokenization_regex = match Regex::new(&opt.word_diff_regex) {
            Ok(r) => r,
            Err(_) => {
                eprintln!("Invalid word-diff-regex: {}", opt.word_diff_regex);
                std::process::exit(2);
            }
        };
        let commit_regex = match Regex::new(&opt.commit_regex) {
            Ok(r) => r,
            Err(_) => {
                eprintln!("Invalid commit-regex: {}", opt.commit_regex);
                std::process::exit(2);
            }
        };

        let wrap_max_lines_plus1 = adapt_wrap_max_lines_argument(&opt.wrap_max_lines);
        let available_terminal_width = opt.computed.available_terminal_width;
        let side_by_side_data = make_side_by_side_data(available_terminal_width);

        let inline_hint_syntect_style = inline_hint_style;
        let wrap_config = WrapConfig {
            left_symbol: ensure_display_width_1("wrap-left-symbol", opt.wrap_left_symbol.clone()),
            right_symbol: ensure_display_width_1("wrap-right-symbol", opt.wrap_right_symbol.clone()),
            right_prefix_symbol: ensure_display_width_1("wrap-right-prefix-symbol", opt.wrap_right_prefix_symbol.clone()),
            use_wrap_right_permille: {
                let arg = opt.wrap_right_percent;
                if arg >= 0.0 && arg <= 100.0 {
                    (opt.wrap_right_percent * 10.0).round() as usize
                } else {
                    eprintln!("Invalid value for wrap-right-percent: {}", arg);
                    std::process::exit(2);
                }
            },
            max_lines: wrap_max_lines_plus1,
            inline_hint_syntect_style,
        };

        let max_line_length = match (opt.side_by_side, wrap_max_lines_plus1) {
            (false, _) => opt.max_line_length,
            // Ensure there is enough text to wrap, either don't truncate the input at all (0)
            // or ensure there is enough for the requested number of lines.
            // The input can contain ANSI sequences, so round up a bit. This is enough for
            // normal `git diff`, but might not be with ANSI heavy input.
            (true, 0) => 0,
            (true, wrap_max_lines) => {
                let single_pane_width = available_terminal_width / 2;
                let add_25_percent = |x| (x * 125 + 99) / 100_usize;
                std::cmp::max(
                    opt.max_line_length,
                    add_25_percent(single_pane_width * wrap_max_lines),
                )
            }
        };

        let tab_cfg = TabCfg {
            replacement: " ".repeat(opt.tabs),
            width: opt.tabs,
        };

        let line_fill_method = if opt.computed.line_fill_method_ansi {
            BgFillMethod::TryAnsiSequence
        } else {
            BgFillMethod::Spaces
        };

        let hunk_header_style_include_file_path = opt.hunk_header_style.split(' ').any(|s| s == "file");
        let hunk_header_style_include_line_number = opt.hunk_header_style.split(' ').any(|s| s == "line-number");

        let file_regex_replacement = parse_file_transformation(opt.file_transformation.as_deref());

        let syntax_theme = opt.computed.syntax_theme_name.as_ref().map(|n| crate::syntax::theme_info(n));

        Config {
            available_terminal_width,
            background_color_extends_to_terminal_width: opt.computed.background_color_extends_to_terminal_width,
            blame_code_style,
            blame_format: opt.blame_format.clone(),
            blame_separator_format: opt.blame_separator_format.clone(),
            blame_palette,
            blame_palette_strings,
            blame_separator_style,
            blame_timestamp_format: opt.blame_timestamp_format.clone(),
            blame_timestamp_output_format: opt.blame_timestamp_output_format.clone(),
            color_only: opt.color_only,
            commit_regex,
            commit_style,
            decorations_width: opt.computed.decorations_width,
            default_language: opt.default_language.clone(),
            diff_stat_align_width: opt.diff_stat_align_width,
            error_exit_code: 2,
            file_added_label: opt.file_added_label.clone(),
            file_copied_label: opt.file_copied_label.clone(),
            file_modified_label: opt.file_modified_label.clone(),
            file_removed_label: opt.file_removed_label.clone(),
            file_renamed_label: opt.file_renamed_label.clone(),
            file_regex_replacement,
            right_arrow: opt.right_arrow.clone(),
            file_style,
            git_config: None,
            grep_context_line_style,
            grep_file_style,
            grep_header_decoration_style: opt.grep_header_decoration_style.clone(),
            grep_header_file_style,
            grep_line_number_style,
            grep_output_type,
            grep_match_line_style,
            grep_match_word_style,
            grep_separator_symbol: opt.grep_separator_symbol.clone(),
            handle_merge_conflicts: !opt.raw,
            hunk_header_file_style,
            hunk_header_line_number_style,
            hunk_header_style,
            hunk_header_style_include_file_path,
            hunk_header_style_include_line_number,
            hunk_label: opt.hunk_label.clone(),
            hyperlinks: opt.hyperlinks,
            hyperlinks_commit_link_format: opt.hyperlinks_commit_link_format.clone(),
            hyperlinks_file_link_format: opt.hyperlinks_file_link_format.clone(),
            inline_hint_style,
            inspect_raw_lines: if opt.computed.inspect_raw_lines { InspectRawLines::True } else { InspectRawLines::False },
            keep_plus_minus_markers: opt.keep_plus_minus_markers,
            line_buffer_size: opt.line_buffer_size,
            line_fill_method,
            line_numbers: opt.line_numbers,
            line_numbers_format: MinusPlus::new(opt.line_numbers_left_format.clone(), opt.line_numbers_right_format.clone()),
            line_numbers_style_leftright: MinusPlus::new(line_numbers_left_style, line_numbers_right_style),
            line_numbers_style_minusplus: MinusPlus::new(line_numbers_minus_style, line_numbers_plus_style),
            line_numbers_zero_style,
            styles_map,
            max_line_distance: opt.max_line_distance,
            max_line_distance_for_naively_paired_lines: if opt.diff_highlight || opt.diff_so_fancy { 0.0 } else { 0.0 },
            max_line_length,
            max_syntax_highlighting_length: opt.max_syntax_highlighting_length,
            merge_conflict_begin_symbol: opt.merge_conflict_begin_symbol.clone(),
            merge_conflict_end_symbol: opt.merge_conflict_end_symbol.clone(),
            merge_conflict_ours_diff_header_style,
            merge_conflict_theirs_diff_header_style,
            minus_emph_style,
            minus_empty_line_marker_style,
            minus_file: opt.minus_file.as_ref().map(PathBuf::from),
            minus_non_emph_style,
            minus_style,
            navigate: opt.navigate,
            navigate_regex,
            null_style: Style::new(),
            pager: opt.pager.clone(),
            paging_mode: opt.computed.paging_mode,
            plus_emph_style,
            plus_empty_line_marker_style,
            plus_file: opt.plus_file.as_ref().map(PathBuf::from),
            plus_non_emph_style,
            plus_style,
            relative_paths: opt.relative_paths,
            show_themes: opt.show_themes,
            side_by_side: opt.side_by_side,
            side_by_side_data,
            syntax_theme,
            tab_cfg,
            tokenization_regex,
            true_color,
            truncation_symbol: format!("{}→{}", AnsiStyle::new().reverse().prefix(), crate::ansi::RESET),
            whitespace_error_style,
            wrap_config,
            zero_style,
            opt,
        }
    }
}

fn make_navigate_regex(
    show_themes: bool,
    file_modified_label: &str,
    file_added_label: &str,
    file_removed_label: &str,
    file_renamed_label: &str,
    hunk_label: &str,
) -> String {
    if show_themes {
        "^Theme:".to_string()
    } else {
        let optional_regexp = |find: &str| {
            if !find.is_empty() {
                format!("|{}", regex::escape(find))
            } else {
                "".to_string()
            }
        };
        format!(
            "^(commit{}{}{}{}{})",
            optional_regexp(file_added_label),
            optional_regexp(file_removed_label),
            optional_regexp(file_renamed_label),
            optional_regexp(file_modified_label),
            optional_regexp(hunk_label),
        )
    }
}

fn adapt_wrap_max_lines_argument(arg: &str) -> usize {
    if arg == "∞" || arg == "unlimited" || arg.starts_with("inf") {
        0
    } else {
        match arg.parse::<usize>() {
            Ok(n) => n + 1,
            Err(_) => {
                eprintln!("Invalid value for wrap-max-lines: {}", arg);
                std::process::exit(2);
            }
        }
    }
}

fn ensure_display_width_1(what: &str, arg: String) -> String {
    use unicode_width::UnicodeWidthStr;
    match arg.width() {
        0 => {
            eprintln!("Invalid value for {}: {:?} has width 0", what, arg);
            std::process::exit(2);
        }
        1 => arg,
        _ => {
            eprintln!("Invalid value for {}: {:?} has width > 1", what, arg);
            std::process::exit(2);
        }
    }
}

pub fn make_side_by_side_data(available_terminal_width: usize) -> SideBySideData {
    let total = available_terminal_width;
    let left_width = total / 2;
    let right_width = total - left_width;
    SideBySideData {
        left_panel: Panel { width: left_width, offset: 0 },
        right_panel: Panel { width: right_width, offset: 0 },
    }
}

pub fn decoration_style_ansi(style: &Style) -> Option<AnsiStyle> {
    style.decoration_style.ansi_style()
}

#[allow(dead_code)]
pub fn is_no_decoration(style: &Style) -> bool {
    style.decoration_style == DecorationStyle::NoDecoration
}
