fn make_hunk_styles(opt: &Opt) -> [Style; 10] {
    let is_light_mode = opt.computed.is_light_mode;
    let true_color = opt.computed.true_color;
    let minus_style = Style::from_str(
        &opt.minus_style,
        Some(Style::from_colors(None, Some(get_minus_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        false,
    );
    let minus_emph_style = Style::from_str(
        &opt.minus_emph_style,
        Some(Style::from_colors(None, Some(get_minus_emph_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        true,
    );
    let minus_non_emph_style = if opt.minus_non_emph_style == "minus-style" {
        minus_style
    } else {
        Style::from_str(&opt.minus_non_emph_style, Some(minus_style), None, true_color, false)
    };
    let minus_empty_line_marker_style = Style::from_str(
        &opt.minus_empty_line_marker_style,
        Some(Style::from_colors(None, Some(get_minus_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        false,
    );
    let zero_style = Style::from_str(&opt.zero_style, None, None, true_color, false);
    let plus_style = Style::from_str(
        &opt.plus_style,
        Some(Style::from_colors(None, Some(get_plus_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        false,
    );
    let plus_emph_style = Style::from_str(
        &opt.plus_emph_style,
        Some(Style::from_colors(None, Some(get_plus_emph_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        true,
    );
    let plus_non_emph_style = if opt.plus_non_emph_style == "plus-style" {
        plus_style
    } else {
        Style::from_str(&opt.plus_non_emph_style, Some(plus_style), None, true_color, false)
    };
    let plus_empty_line_marker_style = Style::from_str(
        &opt.plus_empty_line_marker_style,
        Some(Style::from_colors(None, Some(get_plus_background_color_default(is_light_mode, true_color)))),
        None,
        true_color,
        false,
    );
    let whitespace_error_style = Style::from_str(&opt.whitespace_error_style, None, None, true_color, false);
    [
        minus_style,
        minus_emph_style,
        minus_non_emph_style,
        minus_empty_line_marker_style,
        zero_style,
        plus_style,
        plus_emph_style,
        plus_non_emph_style,
        plus_empty_line_marker_style,
        whitespace_error_style,
    ]
}

fn make_line_number_styles(opt: &Opt) -> (Style, Style, Style, Style, Style) {
    let true_color = opt.computed.true_color;
    let left = Style::from_str(&opt.line_numbers_left_style, None, None, true_color, false);
    let minus = Style::from_str(&opt.line_numbers_minus_style, None, None, true_color, false);
    let zero = Style::from_str(&opt.line_numbers_zero_style, None, None, true_color, false);
    let plus = Style::from_str(&opt.line_numbers_plus_style, None, None, true_color, false);
    let right = Style::from_str(&opt.line_numbers_right_style, None, None, true_color, false);
    (left, minus, zero, plus, right)
}

fn make_commit_file_hunk_header_styles(opt: &Opt) -> (Style, Style, Style, Style, Style) {
    let true_color = opt.computed.true_color;
    let commit_style = Style::from_str_with_handling_of_special_decoration_attributes(
        &opt.commit_style,
        None,
        Some(&opt.commit_decoration_style),
        true_color,
        false,
    );
    let file_style = Style::from_str_with_handling_of_special_decoration_attributes(
        &opt.file_style,
