fn make_blame_palette(blame_palette: Option<&str>, is_light_mode: bool) -> Vec<String> {
    match (blame_palette, is_light_mode) {
        (Some(palette), _) => palette.split_whitespace().map(|s| s.to_string()).collect(),
        (None, false) => vec!["#000000".into(), "#222222".into(), "#444444".into()],
        (None, true) => vec!["#FFFFFF".into(), "#DDDDDD".into(), "#BBBBBB".into()],
    }
}

pub fn parse_styles_map(opt: &Opt) -> Option<HashMap<Style, Style>> {
    let s = opt.map_styles.as_ref()?;
    let true_color = opt.computed.true_color;
    let mut map = HashMap::new();
    for pair in s.split(',') {
        let mut parts = pair.split("=>");
        let from = parts.next().map(|s| s.trim());
        let to = parts.next().map(|s| s.trim());
        if let (Some(from), Some(to)) = (from, to) {
            let from_style = Style::from_str(from, None, None, true_color, false);
            let to_style = Style::from_str(to, None, None, true_color, false);
            map.insert(from_style, to_style);
        }
    }
    Some(map)
}

fn parse_file_transformation(s: Option<&str>) -> Option<(Regex, String)> {
    let s = s?;
    // s/pattern/replacement/ with arbitrary delimiter after 's'
    let mut chars = s.chars();
    if chars.next() != Some('s') {
        eprintln!("Invalid value for file-transformation: {}", s);
        std::process::exit(2);
    }
    let delim = match chars.next() {
        Some(d) => d,
        None => {
            eprintln!("Invalid value for file-transformation: {}", s);
            std::process::exit(2);
        }
    };
    let rest: String = chars.collect();
    let parts: Vec<&str> = rest.split(delim).collect();
    if parts.len() < 2 {
        eprintln!("Invalid value for file-transformation: {}", s);
        std::process::exit(2);
    }
    let regex = match Regex::new(parts[0]) {
        Ok(r) => r,
        Err(_) => {
            eprintln!("Invalid value for file-transformation: {}", s);
            std::process::exit(2);
        }
    };
    Some((regex, parts[1].to_string()))
}

impl From<Opt> for Config {
    fn from(opt: Opt) -> Self {
        let true_color = opt.computed.true_color;
        let [minus_style, minus_emph_style, minus_non_emph_style, minus_empty_line_marker_style, zero_style, plus_style, plus_emph_style, plus_non_emph_style, plus_empty_line_marker_style, whitespace_error_style] =
            make_hunk_styles(&opt);
        let (commit_style, file_style, hunk_header_style, hunk_header_file_style, hunk_header_line_number_style) =
            make_commit_file_hunk_header_styles(&opt);
        let (line_numbers_left_style, line_numbers_minus_style, line_numbers_zero_style, line_numbers_plus_style, line_numbers_right_style) =
            make_line_number_styles(&opt);

        let inline_hint_style = Style::from_str(&opt.inline_hint_style, None, None, true_color, false);

        let grep_match_line_style = match &opt.grep_match_line_style {
            Some(s) => Style::from_str(s, None, None, true_color, false),
            None => plus_style,
        };
        let grep_match_word_style = match &opt.grep_match_word_style {
            Some(s) => Style::from_str(s, None, None, true_color, false),
            None => plus_emph_style,
        };
        let grep_context_line_style = match &opt.grep_context_line_style {
            Some(s) => Style::from_str(s, None, None, true_color, false),
            None => zero_style,
        };
        let grep_file_style = Style::from_str(&opt.grep_file_style, None, None, true_color, false);
        let grep_line_number_style = Style::from_str(&opt.grep_line_number_style, None, None, true_color, false);
        let grep_header_file_style = opt
            .grep_header_file_style
            .as_ref()
            .map(|s| Style::from_str(s, None, None, true_color, false));
        let grep_output_type = match opt.grep_output_type.as_deref() {
            Some("ripgrep") => Some(GrepType::Ripgrep),
            Some("classic") => Some(GrepType::Classic),
            _ => None,
        };

        let blame_palette_strings = make_blame_palette(opt.blame_palette.as_deref(), opt.computed.is_light_mode);
        let blame_palette: Vec<AnsiStyle> = blame_palette_strings
            .iter()
            .map(|s| Style::from_str(&format!("normal {}", s), None, None, true_color, false).ansi_term_style)
            .collect();
        let blame_code_style = opt
            .blame_code_style
            .as_ref()
            .map(|s| Style::from_str(s, None, None, true_color, false));
        let blame_separator_style = opt
            .blame_separator_style
            .as_ref()
            .map(|s| Style::from_str(s, None, None, true_color, false));

        let merge_conflict_ours_diff_header_style = Style::from_str_with_handling_of_special_decoration_attributes(
