        };

        let hunk_header_style_include_file_path = opt.hunk_header_style.split(' ').any(|s| s == "file");
        let hunk_header_style_include_line_number = opt.hunk_header_style.split(' ').any(|s| s == "line-number");

        let file_regex_replacement = parse_file_transformation(opt.file_transformation.as_deref());

        let syntax_theme = opt.computed.syntax_theme_name.as_ref().map(|n| crate::syntax::theme_info(n));

        Config {
            available_terminal_width,
            background_color_extends_to_terminal_width: opt.computed.background_color_extends_to_terminal_width,
            blame_code_style,
            blame_format: opt.blame_format.clone(),
            blame_separator_format: opt.blame_separator_format.clone(),
            blame_palette,
            blame_palette_strings,
            blame_separator_style,
            blame_timestamp_format: opt.blame_timestamp_format.clone(),
            blame_timestamp_output_format: opt.blame_timestamp_output_format.clone(),
            color_only: opt.color_only,
            commit_regex,
            commit_style,
            decorations_width: opt.computed.decorations_width,
            default_language: opt.default_language.clone(),
            diff_stat_align_width: opt.diff_stat_align_width,
            error_exit_code: 2,
            file_added_label: opt.file_added_label.clone(),
            file_copied_label: opt.file_copied_label.clone(),
            file_modified_label: opt.file_modified_label.clone(),
            file_removed_label: opt.file_removed_label.clone(),
            file_renamed_label: opt.file_renamed_label.clone(),
            file_regex_replacement,
            right_arrow: opt.right_arrow.clone(),
            file_style,
            git_config: None,
            grep_context_line_style,
            grep_file_style,
            grep_header_decoration_style: opt.grep_header_decoration_style.clone(),
            grep_header_file_style,
            grep_line_number_style,
            grep_output_type,
            grep_match_line_style,
            grep_match_word_style,
            grep_separator_symbol: opt.grep_separator_symbol.clone(),
            handle_merge_conflicts: !opt.raw,
            hunk_header_file_style,
            hunk_header_line_number_style,
            hunk_header_style,
            hunk_header_style_include_file_path,
            hunk_header_style_include_line_number,
            hunk_label: opt.hunk_label.clone(),
            hyperlinks: opt.hyperlinks,
            hyperlinks_commit_link_format: opt.hyperlinks_commit_link_format.clone(),
            hyperlinks_file_link_format: opt.hyperlinks_file_link_format.clone(),
            inline_hint_style,
            inspect_raw_lines: if opt.computed.inspect_raw_lines { InspectRawLines::True } else { InspectRawLines::False },
            keep_plus_minus_markers: opt.keep_plus_minus_markers,
            line_buffer_size: opt.line_buffer_size,
            line_fill_method,
            line_numbers: opt.line_numbers,
            line_numbers_format: MinusPlus::new(opt.line_numbers_left_format.clone(), opt.line_numbers_right_format.clone()),
            line_numbers_style_leftright: MinusPlus::new(line_numbers_left_style, line_numbers_right_style),
            line_numbers_style_minusplus: MinusPlus::new(line_numbers_minus_style, line_numbers_plus_style),
            line_numbers_zero_style,
            styles_map,
            max_line_distance: opt.max_line_distance,
            max_line_distance_for_naively_paired_lines: if opt.diff_highlight || opt.diff_so_fancy { 0.0 } else { 0.0 },
            max_line_length,
            max_syntax_highlighting_length: opt.max_syntax_highlighting_length,
            merge_conflict_begin_symbol: opt.merge_conflict_begin_symbol.clone(),
