            minus_emph_style,
            minus_empty_line_marker_style,
            minus_file: opt.minus_file.as_ref().map(PathBuf::from),
            minus_non_emph_style,
            minus_style,
            navigate: opt.navigate,
            navigate_regex,
            null_style: Style::new(),
            pager: opt.pager.clone(),
