fn make_navigate_regex(
    show_themes: bool,
    file_modified_label: &str,
    file_added_label: &str,
    file_removed_label: &str,
    file_renamed_label: &str,
    hunk_label: &str,
) -> String {
    if show_themes {
        "^Theme:".to_string()
    } else {
        let optional_regexp = |find: &str| {
            if !find.is_empty() {
                format!("|{}", regex::escape(find))
            } else {
                "".to_string()
            }
        };
        format!(
            "^(commit{}{}{}{}{})",
            optional_regexp(file_added_label),
            optional_regexp(file_removed_label),
            optional_regexp(file_renamed_label),
            optional_regexp(file_modified_label),
            optional_regexp(hunk_label),
        )
    }
}

fn adapt_wrap_max_lines_argument(arg: &str) -> usize {
    if arg == "∞" || arg == "unlimited" || arg.starts_with("inf") {
        0
    } else {
        match arg.parse::<usize>() {
            Ok(n) => n + 1,
            Err(_) => {
                eprintln!("Invalid value for wrap-max-lines: {}", arg);
                std::process::exit(2);
            }
        }
    }
}

fn ensure_display_width_1(what: &str, arg: String) -> String {
    use unicode_width::UnicodeWidthStr;
    match arg.width() {
        0 => {
            eprintln!("Invalid value for {}: {:?} has width 0", what, arg);
            std::process::exit(2);
        }
        1 => arg,
        _ => {
            eprintln!("Invalid value for {}: {:?} has width > 1", what, arg);
            std::process::exit(2);
        }
    }
}

pub fn make_side_by_side_data(available_terminal_width: usize) -> SideBySideData {
    let total = available_terminal_width;
    let left_width = total / 2;
    let right_width = total - left_width;
    SideBySideData {
        left_panel: Panel { width: left_width, offset: 0 },
        right_panel: Panel { width: right_width, offset: 0 },
    }
}

pub fn decoration_style_ansi(style: &Style) -> Option<AnsiStyle> {
    style.decoration_style.ansi_style()
}

#[allow(dead_code)]
pub fn is_no_decoration(style: &Style) -> bool {
    style.decoration_style == DecorationStyle::NoDecoration
}
