impl<T> std::ops::Index<crate::delta::PanelSide> for MinusPlus<T> {
    type Output = T;
    fn index(&self, side: crate::delta::PanelSide) -> &T {
        match side {
            crate::delta::PanelSide::Left => &self.minus,
            crate::delta::PanelSide::Right => &self.plus,
        }
    }
