/// Expand tabs: replace each tab with `tab_cfg.replacement` (if tab width > 0).
pub fn expand_tabs<'a>(line: &'a str, tab_cfg: &crate::config::TabCfg) -> std::borrow::Cow<'a, str> {
    if tab_cfg.width > 0 && line.contains('\t') {
        std::borrow::Cow::Owned(line.replace('\t', &tab_cfg.replacement))
    } else {
        std::borrow::Cow::Borrowed(line)
    }
}

/// Round up integer division
pub fn div_ceil(a: usize, b: usize) -> usize {
    (a + b - 1) / b
}
