//! Sequence alignment (Levenshtein-style) of token sequences.

use unicode_segmentation::UnicodeSegmentation;

const SUBSTITUTION_COST: usize = 1;
const DELETION_COST: usize = 1;
const INSERTION_COST: usize = 1;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Operation {
    NoOp,
    Substitution,
    Deletion,
    Insertion,
}

#[derive(Clone, Copy, Debug)]
struct Cell {
    parent: usize,
    operation: Operation,
    cost: usize,
}

pub struct Alignment<'a> {
    pub x: Vec<&'a str>,
    pub y: Vec<&'a str>,
    table: Vec<Cell>,
    dim: [usize; 2],
}

impl<'a> Alignment<'a> {
    /// Create alignment of x (the "old" token sequence) and y (the "new").
    /// Both sequences must start with a dummy "" token.
    pub fn new(x: Vec<&'a str>, y: Vec<&'a str>) -> Self {
        let dim = [y.len(), x.len()];
        let table = vec![
            Cell {
                parent: 0,
                operation: Operation::NoOp,
                cost: 0
            };
            dim[0] * dim[1]
        ];
        let mut a = Alignment { x, y, table, dim };
        a.fill();
        a
    }

    fn index(&self, i: usize, j: usize) -> usize {
        i * self.dim[1] + j
    }

    fn fill(&mut self) {
        // Row 0 / column 0: insertions / deletions from the empty sequence
        for i in 1..self.dim[0] {
            let idx = self.index(i, 0);
            let parent = self.index(i - 1, 0);
            self.table[idx] = Cell {
                parent,
                operation: Operation::Insertion,
                cost: self.table[parent].cost + INSERTION_COST,
            };
        }
        for j in 1..self.dim[1] {
            let idx = self.index(0, j);
            let parent = self.index(0, j - 1);
            self.table[idx] = Cell {
                parent,
                operation: Operation::Deletion,
                cost: self.table[parent].cost + DELETION_COST,
            };
        }
        for i in 1..self.dim[0] {
            for j in 1..self.dim[1] {
                let left = self.index(i, j - 1);
                let diag = self.index(i - 1, j - 1);
                let up = self.index(i - 1, j);
                let (diag_op, diag_cost) = if self.x[j] == self.y[i] {
                    (Operation::NoOp, 0)
                } else {
                    (Operation::Substitution, SUBSTITUTION_COST)
                };
                let candidates = [
                    Cell {
                        parent: left,
                        operation: Operation::Deletion,
                        cost: self.table[left].cost + DELETION_COST,
                    },
                    Cell {
                        parent: diag,
                        operation: diag_op,
                        cost: self.table[diag].cost + diag_cost,
                    },
                    Cell {
                        parent: up,
                        operation: Operation::Insertion,
                        cost: self.table[up].cost + INSERTION_COST,
                    },
                ];
                let mut best = candidates[0];
                for c in &candidates[1..] {
                    if c.cost < best.cost {
                        best = *c;
                    }
                }
                let idx = self.index(i, j);
                self.table[idx] = best;
            }
        }
    }

    /// Return the sequence of (operation, x index, y index) from the start of the
    /// alignment to the end.
    pub fn operations(&self) -> Vec<(Operation, usize, usize)> {
        let mut ops = Vec::new();
        let mut idx = self.index(self.dim[0] - 1, self.dim[1] - 1);
        let origin = self.index(0, 0);
        while idx != origin {
            let cell = self.table[idx];
            let i = idx / self.dim[1];
            let j = idx % self.dim[1];
            ops.push((cell.operation, j, i));
            idx = cell.parent;
        }
        ops.reverse();
        ops
    }

    /// Edit distance: (total length of edited tokens, total length of tokens).
    pub fn distance_parts(&self) -> (usize, usize) {
        let mut numer = 0usize;
        let mut denom = 0usize;
        for (op, j, i) in self.operations() {
            let xlen = self.x[j].graphemes(true).count();
            let ylen = self.y[i].graphemes(true).count();
            match op {
                Operation::NoOp => {
                    denom += xlen;
                }
                Operation::Substitution => {
                    numer += xlen.max(ylen);
                    denom += xlen.max(ylen);
                }
                Operation::Deletion => {
                    numer += xlen;
                    denom += xlen;
                }
                Operation::Insertion => {
                    numer += ylen;
                    denom += ylen;
                }
            }
        }
        (numer, denom)
    }

    pub fn normalized_distance(&self) -> f64 {
        let (numer, denom) = self.distance_parts();
        if denom == 0 {
            0.0
        } else {
            numer as f64 / denom as f64
        }
    }
}
