//! Inference of within-line edits between paired minus and plus lines.

use regex::Regex;

use crate::align::{Alignment, Operation};

/// Split line into tokens: alternating non-word and word substrings. The first
/// token is always the empty string (required by the alignment algorithm).
pub fn tokenize<'a>(line: &'a str, regex: &Regex) -> Vec<&'a str> {
    let mut tokens = vec![""];
    let mut offset = 0;
    for m in regex.find_iter(line) {
        if m.start() > offset {
            tokens.push(&line[offset..m.start()]);
        }
        tokens.push(m.as_str());
        offset = m.end();
    }
    if offset < line.len() {
        tokens.push(&line[offset..]);
    }
    tokens
}

pub type LineSections<'a, S> = Vec<(S, &'a str)>;

/// Infer the edit operations responsible for the differences between a
/// collection of old (minus) lines and a collection of new (plus) lines.
/// Returns annotated minus lines and plus lines, and the line alignment.
#[allow(clippy::too_many_arguments)]
pub fn infer_edits<'a, S: Copy + PartialEq>(
    minus_lines: &[&'a str],
    plus_lines: &[&'a str],
    noop_deletions: &[S],
    deletion: S,
    noop_insertions: &[S],
    insertion: S,
    tokenization_regex: &Regex,
    max_line_distance: f64,
    max_line_distance_for_naively_paired_lines: f64,
) -> (Vec<LineSections<'a, S>>, Vec<LineSections<'a, S>>, Vec<(usize, usize)>) {
    let mut annotated_minus_lines: Vec<LineSections<'a, S>> = Vec::new();
    let mut annotated_plus_lines: Vec<LineSections<'a, S>> = Vec::new();
    let mut line_alignment = Vec::new();

    let mut plus_index = 0; // plus lines emitted so far

    'minus_lines_loop: for (minus_index, minus_line) in minus_lines.iter().enumerate() {
        let mut considered = 0; // plus lines considered so far as match for minus_line
        for plus_line in &plus_lines[plus_index..] {
            let alignment = Alignment::new(
                tokenize(minus_line, tokenization_regex),
                tokenize(plus_line, tokenization_regex),
            );
            let (annotated_minus_line, annotated_plus_line, distance) = annotate(
                &alignment,
                noop_deletions[minus_index],
                deletion,
                noop_insertions[plus_index + considered],
                insertion,
                minus_line,
                plus_line,
            );
            if distance <= max_line_distance
                || (considered == 0
                    && minus_lines.len() == plus_lines.len()
                    && distance <= max_line_distance_for_naively_paired_lines)
            {
                // minus_line and plus_line are inferred to be a homologous pair.
                // Emit as unpaired the plus lines already considered and rejected
                for plus_line in &plus_lines[plus_index..(plus_index + considered)] {
                    annotated_plus_lines.push(vec![(noop_insertions[plus_index], *plus_line)]);
                    plus_index += 1;
                }
                annotated_minus_lines.push(annotated_minus_line);
                annotated_plus_lines.push(annotated_plus_line);
                line_alignment.push((minus_index, plus_index));
                plus_index += 1;
                continue 'minus_lines_loop;
            } else {
                considered += 1;
            }
        }
        // No homolog was found for minus i; emit as unpaired.
        annotated_minus_lines.push(vec![(noop_deletions[minus_index], *minus_line)]);
    }
    // Emit any remaining plus lines
    for plus_line in &plus_lines[plus_index..] {
        annotated_plus_lines.push(vec![(noop_insertions[plus_index], *plus_line)]);
        plus_index += 1;
    }
    (annotated_minus_lines, annotated_plus_lines, line_alignment)
}

/// Annotate the paired lines according to the alignment, returning the
/// annotated lines and the normalized distance.
fn annotate<'a, S: Copy + PartialEq>(
    alignment: &Alignment<'a>,
    noop_deletion: S,
    deletion: S,
    noop_insertion: S,
    insertion: S,
    minus_line: &'a str,
    plus_line: &'a str,
) -> (LineSections<'a, S>, LineSections<'a, S>, f64) {
    let mut annotated_minus_line = Vec::new();
    let mut annotated_plus_line = Vec::new();

    let (mut x_offset, mut y_offset) = (0, 0);
    let (mut minus_section_start, mut plus_section_start) = (0, 0);
    let mut d_numer: usize = 0;
    let mut d_denom: usize = 0;

    // Note that the inputs to this function are not necessarily the full lines, but the
    // sequences of tokens produced by the tokenizer, each of which may be empty.
    let mut minus_edit_sections_in_progress: Option<usize> = None;
    let mut plus_edit_sections_in_progress: Option<usize> = None;

    let ops = alignment.operations();

    // Length in bytes of each token
    let x_lens: Vec<usize> = alignment.x.iter().map(|t| t.len()).collect();
    let y_lens: Vec<usize> = alignment.y.iter().map(|t| t.len()).collect();

    let mut ops_iter = ops.iter().peekable();
    while let Some(&(op, j, i)) = ops_iter.next() {
        let x_len = x_lens[j];
        let y_len = y_lens[i];
        match op {
            Operation::NoOp => {
                // close any edit sections in progress
                if let Some(start) = minus_edit_sections_in_progress.take() {
                    annotated_minus_line.push((deletion, &minus_line[start..x_offset]));
                    minus_section_start = x_offset;
                }
                if let Some(start) = plus_edit_sections_in_progress.take() {
                    annotated_plus_line.push((insertion, &plus_line[start..y_offset]));
                    plus_section_start = y_offset;
                }
                d_denom += grapheme_len(alignment.x[j]);
                x_offset += x_len;
                y_offset += y_len;
            }
            Operation::Substitution | Operation::Deletion | Operation::Insertion => {
                // open edit sections: first emit the noop section preceding
                let (del, ins) = match op {
                    Operation::Substitution => (true, true),
                    Operation::Deletion => (true, false),
                    _ => (false, true),
                };
                if del {
                    if minus_edit_sections_in_progress.is_none() {
                        if x_offset > minus_section_start {
