//! Painting of hunk lines.

use std::io::Write;

use unicode_segmentation::UnicodeSegmentation;

use crate::ansi::{self, AnsiStyle, Painted};
use crate::config::{BgFillMethod, Config};
use crate::delta::State;
use crate::edits;
use crate::features::line_numbers::{self, LineNumbersData};
use crate::style::Style;
use crate::utils::MinusPlus;

pub type LineSections<'a, S> = Vec<(S, &'a str)>;

/// A "syntax style": the foreground color determined by syntax highlighting.
/// We only model plain-text highlighting: the theme's default foreground.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SyntectStyle {
    pub foreground: Option<ansi::Color>,
}

pub struct Painter<'p> {
    pub minus_lines: Vec<(String, State)>,
    pub plus_lines: Vec<(String, State)>,
    pub writer: &'p mut dyn Write,
    pub config: &'p Config,
    pub output_buffer: String,
    pub line_numbers_data: Option<LineNumbersData>,
    /// The syntax foreground color used for highlighted text (None = no highlighting).
    pub syntax_fg: Option<ansi::Color>,
    pub highlighter_active: bool,
}

impl<'p> Painter<'p> {
    pub fn new(writer: &'p mut dyn Write, config: &'p Config) -> Self {
        let line_numbers_data = if config.line_numbers {
            Some(LineNumbersData::from_format_strings(&config.line_numbers_format, config))
        } else {
            None
        };
        let syntax_fg = config
            .syntax_theme
            .as_ref()
            .and_then(|t| crate::syntax::theme_fg_to_ansi(t.foreground, config.true_color));
        Painter {
            minus_lines: Vec::new(),
            plus_lines: Vec::new(),
            writer,
            config,
            output_buffer: String::new(),
            line_numbers_data,
            syntax_fg,
            highlighter_active: config.syntax_theme.is_some(),
        }
    }

    pub fn set_syntax(&mut self, _extension: Option<&str>) {
        // Language-specific highlighting is not modelled; everything is plain text.
    }

    pub fn set_highlighter(&mut self) {}

    /// Remove the prefix (`prefix_length` graphemes) and expand tabs.
    pub fn prepare(&self, line: &str, prefix_length: usize) -> String {
        if !line.is_empty() {
            let line: String = line.graphemes(true).skip(prefix_length).collect();
            expand_tabs(&line, self.config)
        } else {
            String::new()
        }
    }

    /// Prepare a raw (ANSI-containing) line: strip the prefix.
    pub fn prepare_raw_line(&self, raw_line: &str, prefix_length: usize) -> String {
        ansi::ansi_preserving_slice(raw_line, prefix_length)
    }

    pub fn paint_buffered_minus_and_plus_lines(&mut self) {
        let minus_lines = std::mem::take(&mut self.minus_lines);
        let plus_lines = std::mem::take(&mut self.plus_lines);
        paint_minus_and_plus_lines(
            MinusPlus::new(&minus_lines, &plus_lines),
            &mut self.line_numbers_data,
            self.syntax_fg,
            &mut self.output_buffer,
            self.config,
        );
    }

    pub fn emit(&mut self) -> std::io::Result<()> {
        self.writer.write_all(self.output_buffer.as_bytes())?;
        self.output_buffer.clear();
        Ok(())
    }

    /// Paint lines in the given state (used for e.g. zero lines and hunk header code).
    pub fn paint_zero_line(&mut self, line: &str, state: State) {
        let lines = vec![(line.to_string(), state)];
        let syntax_sections = get_syntax_style_sections_for_lines(&lines, self.syntax_fg, self.config);
        let diff_sections: Vec<LineSections<Style>> = lines
            .iter()
            .map(|(l, s)| vec![(*self.config.get_style(s), l.as_str())])
            .collect();
        let states: Vec<&State> = lines.iter().map(|(_, s)| s).collect();
        paint_lines(
            &lines,
            &syntax_sections,
            &diff_sections,
            &states,
            &mut self.line_numbers_data,
            &mut self.output_buffer,
            self.config,
        );
    }
}

pub fn expand_tabs(line: &str, config: &Config) -> String {
    if config.tab_cfg.width > 0 && line.contains('\t') {
        line.replace('\t', &config.tab_cfg.replacement)
    } else {
        line.to_string()
    }
}

pub fn get_syntax_style_sections_for_lines<'a>(
    lines: &'a [(String, State)],
    syntax_fg: Option<ansi::Color>,
    config: &Config,
) -> Vec<LineSections<'a, SyntectStyle>> {
    lines
        .iter()
        .map(|(line, state)| {
            let highlight = should_compute_syntax_highlighting(state, config) && config.syntax_theme.is_some();
            let fg = if highlight { syntax_fg } else { None };
            vec![(SyntectStyle { foreground: fg }, line.as_str())]
        })
        .collect()
}

fn should_compute_syntax_highlighting(state: &State, config: &Config) -> bool {
    if config.syntax_theme.is_none() {
        return false;
    }
    match state {
        State::HunkMinus(_, None) | State::HunkMinusWrapped => {
            config.minus_style.is_syntax_highlighted
                || config.minus_emph_style.is_syntax_highlighted
                || config.minus_non_emph_style.is_syntax_highlighted
        }
        State::HunkZero(_, None) | State::HunkZeroWrapped => config.zero_style.is_syntax_highlighted,
        State::HunkPlus(_, None) | State::HunkPlusWrapped => {
            config.plus_style.is_syntax_highlighted
                || config.plus_emph_style.is_syntax_highlighted
                || config.plus_non_emph_style.is_syntax_highlighted
        }
        State::HunkMinus(_, Some(_)) | State::HunkZero(_, Some(_)) | State::HunkPlus(_, Some(_)) => true,
        State::HunkHeader(_, _, _, _) => config.hunk_header_style.is_syntax_highlighted,
        State::Blame(_) => true,
        State::GitShowFile => true,
        State::Grep => true,
        _ => panic!("should_compute_syntax_highlighting: unexpected state"),
    }
}

pub fn paint_minus_and_plus_lines(
    lines: MinusPlus<&Vec<(String, State)>>,
    line_numbers_data: &mut Option<LineNumbersData>,
    syntax_fg: Option<ansi::Color>,
    output_buffer: &mut String,
    config: &Config,
) {
    let syntax_style_sections = MinusPlus::new(
        get_syntax_style_sections_for_lines(lines.minus, syntax_fg, config),
        get_syntax_style_sections_for_lines(lines.plus, syntax_fg, config),
    );
    let (diff_style_sections, lines_have_homolog) = get_diff_style_sections(&lines, config);
    let states = MinusPlus::new(
        lines.minus.iter().map(|(_, s)| s).collect::<Vec<&State>>(),
        lines.plus.iter().map(|(_, s)| s).collect::<Vec<&State>>(),
    );
    if config.side_by_side {
        crate::features::side_by_side::paint_minus_and_plus_lines_side_by_side(
            lines,
            syntax_style_sections,
            diff_style_sections,
            lines_have_homolog,
            states,
            line_numbers_data,
            output_buffer,
            config,
        );
    } else {
        paint_lines(
            lines.minus,
            &syntax_style_sections.minus,
            &diff_style_sections.minus,
            &states.minus,
            line_numbers_data,
            output_buffer,
            config,
        );
        paint_lines(
            lines.plus,
            &syntax_style_sections.plus,
            &diff_style_sections.plus,
            &states.plus,
            line_numbers_data,
            output_buffer,
            config,
        );
    }
}

/// Compute diff style sections (emph / non-emph) for the minus and plus lines.
pub fn get_diff_style_sections<'a>(
    lines: &MinusPlus<&'a Vec<(String, State)>>,
    config: &Config,
) -> (MinusPlus<Vec<LineSections<'a, Style>>>, MinusPlus<Vec<bool>>) {
    let minus_lines: Vec<&str> = lines.minus.iter().map(|(l, _)| l.as_str()).collect();
    let plus_lines: Vec<&str> = lines.plus.iter().map(|(l, _)| l.as_str()).collect();
    let minus_styles: Vec<Style> = lines.minus.iter().map(|(_, s)| *config.get_style(s)).collect();
    let plus_styles: Vec<Style> = lines.plus.iter().map(|(_, s)| *config.get_style(s)).collect();

    let (mut minus_sections, mut plus_sections, line_alignment) = edits::infer_edits(
        &minus_lines,
        &plus_lines,
        &minus_styles,
        config.minus_emph_style,
        &plus_styles,
        config.plus_emph_style,
        &config.tokenization_regex,
        config.max_line_distance,
        config.max_line_distance_for_naively_paired_lines,
    );

    let mut minus_have_homolog = vec![false; minus_lines.len()];
    let mut plus_have_homolog = vec![false; plus_lines.len()];
    for (i, j) in &line_alignment {
        minus_have_homolog[*i] = true;
        plus_have_homolog[*j] = true;
    }

    // Trailing whitespace handling (minus): a trailing whitespace-only
    // non-emph section following an emph section is painted as emph.
    for (sections, (_, state)) in minus_sections.iter_mut().zip(lines.minus.iter()) {
        if matches!(state, State::HunkMinus(_, None)) && sections.len() >= 2 {
            let n = sections.len();
            if sections[n - 1].1.trim().is_empty() && !sections[n - 1].0.is_emph {
                sections[n - 1].0 = config.minus_emph_style;
            }
        }
    }

    let minus_non_emph_style = if config.minus_non_emph_style != config.minus_emph_style {
        Some(config.minus_non_emph_style)
    } else {
        None
    };
    update_styles(lines.minus, &mut minus_sections, None, minus_non_emph_style, &minus_have_homolog, config);
    let plus_non_emph_style = if config.plus_non_emph_style != config.plus_emph_style {
        Some(config.plus_non_emph_style)
    } else {
        None
    };
    update_styles(
        lines.plus,
        &mut plus_sections,
        Some(config.whitespace_error_style),
        plus_non_emph_style,
        &plus_have_homolog,
        config,
    );
    (
        MinusPlus::new(minus_sections, plus_sections),
        MinusPlus::new(minus_have_homolog, plus_have_homolog),
    )
}

fn update_styles<'a>(
    lines: &[(String, State)],
    style_sections: &mut [LineSections<'a, Style>],
    whitespace_error_style: Option<Style>,
    non_emph_style: Option<Style>,
    lines_have_homolog: &[bool],
    _config: &Config,
) {
    for (((_, state), sections), has_homolog) in lines.iter().zip(style_sections.iter_mut()).zip(lines_have_homolog) {
        let is_plain_hunk_line = matches!(
            state,
            State::HunkMinus(_, None) | State::HunkPlus(_, None) | State::HunkZero(_, None)
        );
        // Coalesce adjacent sections with the same style
        coalesce_sections(sections);
        if let (Some(ws_style), true) = (whitespace_error_style, is_plain_hunk_line) {
            if let Some(last) = sections.last().copied() {
                if last.1.trim().is_empty() {
                    if !last.1.is_empty() {
                        let n = sections.len();
                        sections[n - 1].0 = ws_style;
                    }
                } else if !last.0.is_emph {
                    let trimmed = last.1.trim_end();
                    if trimmed.len() < last.1.len() {
                        let n = sections.len();
                        let (head, tail) = last.1.split_at(trimmed.len());
                        sections[n - 1].1 = head;
                        sections.push((ws_style, tail));
                    }
                }
            }
        }
        if let (Some(non_emph), true) = (non_emph_style, *has_homolog && is_plain_hunk_line) {
            for (style, _) in sections.iter_mut() {
                if !style.is_emph && *style != non_emph && style_is_base(style) {
                    *style = non_emph;
                }
            }
        }
    }
}

fn style_is_base(style: &Style) -> bool {
    // The whitespace error style must not be replaced by the non-emph style.
    !style.is_emph
}

fn coalesce_sections(sections: &mut LineSections<'_, Style>) {
    if sections.len() < 2 {
        return;
    }
    let mut out: LineSections<Style> = Vec::with_capacity(sections.len());
    for (style, text) in sections.iter() {
        if let Some(last) = out.last_mut() {
            if last.0 == *style {
                // The sections are contiguous slices of the same line.
                let start = last.1.as_ptr() as usize;
                let end = text.as_ptr() as usize + text.len();
                let len = end - start;
                // SAFETY: both slices come from the same &str and are contiguous.
                let merged: &str = unsafe {
                    std::str::from_utf8_unchecked(std::slice::from_raw_parts(last.1.as_ptr(), len))
                };
                last.1 = merged;
                continue;
            }
        }
        out.push((*style, text));
    }
    *sections = out;
}

/// Paint lines (unified mode).
pub fn paint_lines<'a>(
    lines: &[(String, State)],
    syntax_style_sections: &[LineSections<'a, SyntectStyle>],
    diff_style_sections: &[LineSections<'a, Style>],
    states: &[&State],
    line_numbers_data: &mut Option<LineNumbersData>,
    output_buffer: &mut String,
    config: &Config,
) {
    for (i, ((syntax_sections, diff_sections), state)) in syntax_style_sections
        .iter()
        .zip(diff_style_sections.iter())
        .zip(states.iter())
        .enumerate()
    {
        let _ = &lines[i];
        let painted_prefix = get_painted_prefix(state, config);
        let (mut line, _line_is_empty) = paint_line(
            syntax_sections,
            diff_sections,
            state,
            line_numbers_data,
            None,
            painted_prefix,
            config,
        );
        let (bg_fill_mode, fill_style) = get_should_right_fill_background_color_and_fill_style(diff_sections, state, config);
        if let Some(BgFillMethod::TryAnsiSequence) = bg_fill_mode {
            right_fill_background_color(&mut line, &fill_style);
        }
        output_buffer.push_str(&line);
        output_buffer.push('\n');
    }
}

pub fn get_painted_prefix(state: &State, config: &Config) -> Option<Painted> {
    if !config.keep_plus_minus_markers {
        return None;
    }
    let (prefix, style) = match state {
        State::HunkMinus(diff_type, _) => (diff_type_prefix(diff_type, '-'), config.minus_style),
        State::HunkZero(diff_type, _) => (diff_type_prefix(diff_type, ' '), config.zero_style),
        State::HunkPlus(diff_type, _) => (diff_type_prefix(diff_type, '+'), config.plus_style),
        _ => return None,
    };
    Some(Painted::new(style.ansi_term_style, prefix))
}

fn diff_type_prefix(diff_type: &crate::delta::DiffType, marker: char) -> String {
    match diff_type {
        crate::delta::DiffType::Unified => marker.to_string(),
        crate::delta::DiffType::Combined(parents, _) => {
            // For combined diffs the prefix is the raw prefix stored in the parents info.
            match parents {
                crate::delta::MergeParents::Prefix(p) => p.clone(),
                crate::delta::MergeParents::Number(n) => marker.to_string().repeat(*n),
                crate::delta::MergeParents::Unknown => marker.to_string(),
            }
        }
    }
}

/// Paint a single line: returns (painted line, line_is_empty).
pub fn paint_line<'a>(
    syntax_sections: &[(SyntectStyle, &'a str)],
    diff_sections: &[(Style, &'a str)],
    state: &State,
    line_numbers_data: &mut Option<LineNumbersData>,
    side_by_side_panel: Option<crate::delta::PanelSide>,
    painted_prefix: Option<Painted>,
    config: &Config,
) -> (String, bool) {
    let mut ansi_strings: Vec<Painted> = Vec::new();
    let output_line_numbers = line_numbers_data.is_some();
    if output_line_numbers {
        ansi_strings.extend(line_numbers::format_and_paint_line_numbers(
            line_numbers_data.as_mut().unwrap(),
            side_by_side_panel,
            state,
            config,
        ));
    }
    let superimposed = superimpose_style_sections(syntax_sections, diff_sections, config.true_color);
    let mut handled_prefix = false;
    let mut line_is_empty = true;
    for (section_style, text) in &superimposed {
        if !handled_prefix {
            if let Some(p) = &painted_prefix {
                ansi_strings.push(p.clone());
            }
            handled_prefix = true;
        }
        if !text.is_empty() {
            ansi_strings.push(Painted::new(section_style.ansi_term_style, text.clone()));
            line_is_empty = false;
        }
    }
    if !handled_prefix {
        if let Some(p) = &painted_prefix {
            ansi_strings.push(p.clone());
        }
    }
    (ansi::paint_strings(&ansi_strings), line_is_empty)
}

pub fn get_should_right_fill_background_color_and_fill_style(
    diff_sections: &[(Style, &str)],
    state: &State,
    config: &Config,
) -> (Option<BgFillMethod>, Style) {
    let (style, non_emph_style) = match state {
        State::HunkMinus(_, None) | State::HunkMinusWrapped => (config.minus_style, config.minus_non_emph_style),
        State::HunkZero(_, None) | State::HunkZeroWrapped => (config.zero_style, config.zero_style),
        State::HunkPlus(_, None) | State::HunkPlusWrapped => (config.plus_style, config.plus_non_emph_style),
        State::HunkMinus(_, Some(_)) | State::HunkZero(_, Some(_)) | State::HunkPlus(_, Some(_)) => {
            let style = diff_sections.last().map(|(s, _)| *s).unwrap_or(config.null_style);
            (style, style)
        }
        State::Blame(_) => {
            let style = diff_sections.first().map(|(s, _)| *s).unwrap_or(config.null_style);
            (style, style)
        }
        _ => (config.null_style, config.null_style),
    };
    let fill_style = if style_sections_contain_more_than_one_style(diff_sections) {
        non_emph_style
    } else {
        style
    };
    let bg_fill_mode = if !fill_style.has_background() {
        None
    } else if config.side_by_side {
        Some(config.line_fill_method)
    } else if config.background_color_extends_to_terminal_width {
        Some(BgFillMethod::TryAnsiSequence)
    } else {
        None
    };
    (bg_fill_mode, fill_style)
}

pub fn style_sections_contain_more_than_one_style(sections: &[(Style, &str)]) -> bool {
    if sections.len() > 1 {
        let (first_style, _) = sections[0];
        sections.iter().any(|(style, _)| *style != first_style)
    } else {
        false
    }
}

pub fn right_fill_background_color(line: &mut String, fill_style: &Style) {
    line.push_str(&fill_style.ansi_term_style.paint("\x1b[0K"));
}

/// Superimpose syntax highlighting (foreground) onto diff styles.
pub fn superimpose_style_sections<'a>(
    syntax_sections: &[(SyntectStyle, &'a str)],
    diff_sections: &[(Style, &'a str)],
    true_color: bool,
) -> Vec<(Style, String)> {
    let _ = true_color;
    // Both section lists cover the same text; walk through them by bytes.
    let mut out: Vec<(Style, String)> = Vec::new();
    let mut si = 0;
    let mut s_off = 0; // offset into current syntax section
    for (diff_style, diff_text) in diff_sections {
        let mut remaining = *diff_text;
        while !remaining.is_empty() {
            if si >= syntax_sections.len() {
                // No more syntax sections: use diff style as-is
                push_section(&mut out, superimpose(None, diff_style), remaining);
                break;
            }
            let (syn_style, syn_text) = &syntax_sections[si];
            let syn_remaining = &syn_text[s_off..];
            if syn_remaining.is_empty() {
                si += 1;
                s_off = 0;
                continue;
            }
            let take = std::cmp::min(remaining.len(), syn_remaining.len());
            // ensure char boundary
            let mut take = take;
            while take < remaining.len() && !remaining.is_char_boundary(take) {
                take += 1;
            }
            let (chunk, rest) = remaining.split_at(take);
            push_section(&mut out, superimpose(Some(syn_style), diff_style), chunk);
            remaining = rest;
            s_off += take;
            if s_off >= syn_text.len() {
                si += 1;
                s_off = 0;
            }
        }
        if diff_text.is_empty() && out.is_empty() {
            out.push((*diff_style, String::new()));
        }
    }
    if out.is_empty() {
        if let Some((style, _)) = diff_sections.first() {
            out.push((*style, String::new()));
        }
    }
    out
}

fn superimpose(syntax_style: Option<&SyntectStyle>, diff_style: &Style) -> Style {
    if diff_style.is_syntax_highlighted {
        if let Some(fg) = syntax_style.and_then(|s| s.foreground) {
            let mut s = *diff_style;
            s.ansi_term_style.foreground = Some(fg);
            return s;
        }
    }
    *diff_style
}

fn push_section(out: &mut Vec<(Style, String)>, style: Style, text: &str) {
    if let Some(last) = out.last_mut() {
        if last.0 == style {
            last.1.push_str(text);
            return;
        }
    }
    out.push((style, text.to_string()));
}

/// Paint a plain (non-hunk) text with a style, honoring `is_syntax_highlighted`.
pub fn paint_text_with_style(text: &str, style: &Style, syntax_fg: Option<ansi::Color>, config: &Config) -> String {
    let mut s = *style;
    if style.is_syntax_highlighted && config.syntax_theme.is_some() {
        if let Some(fg) = syntax_fg {
            s.ansi_term_style.foreground = Some(fg);
        }
    }
    s.ansi_term_style.paint(text)
}

pub fn ansi_style_with_fg(style: &Style, fg: Option<ansi::Color>) -> AnsiStyle {
    let mut a = style.ansi_term_style;
    if style.is_syntax_highlighted {
        if let Some(fg) = fg {
            a.foreground = Some(fg);
        }
    }
    a
}
