//! The main line-processing state machine.

use std::io::{BufRead, Write};

use crate::ansi;
use crate::config::Config;
use crate::paint::Painter;
use crate::style::DecorationStyle;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MergeParents {
    Number(usize),
    Prefix(String),
    Unknown,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum InMergeConflict {
    Yes,
    No,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DiffType {
    Unified,
    Combined(MergeParents, InMergeConflict),
}

impl DiffType {
    pub fn n_parents(&self) -> usize {
        match self {
            DiffType::Unified => 1,
            DiffType::Combined(MergeParents::Number(n), _) => *n,
            DiffType::Combined(MergeParents::Prefix(p), _) => p.len(),
            DiffType::Combined(MergeParents::Unknown, _) => 1,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParsedHunkHeader {
    pub code_fragment: String,
    pub line_numbers_and_hunk_lengths: Vec<(usize, usize)>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MergeConflictCommit {
    Ours,
    Ancestral,
    Theirs,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum State {
    CommitMeta,
    DiffHeader(DiffType),
    HunkHeader(DiffType, ParsedHunkHeader, String, String),
    HunkZero(DiffType, Option<String>),
    HunkMinus(DiffType, Option<String>),
    HunkPlus(DiffType, Option<String>),
    MergeConflict(MergeParents, MergeConflictCommit),
    SubmoduleLog,
    SubmoduleShort(String),
    Blame(String),
    GitShowFile,
    Grep,
    Unknown,
    HunkZeroWrapped,
    HunkMinusWrapped,
    HunkPlusWrapped,
}

impl State {
    pub fn is_in_hunk(&self) -> bool {
        matches!(
            self,
            State::HunkHeader(..)
                | State::HunkZero(..)
                | State::HunkMinus(..)
                | State::HunkPlus(..)
                | State::MergeConflict(..)
        )
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Source {
    GitDiff,
    DiffUnified,
    Unknown,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PanelSide {
    Left,
    Right,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FileEvent {
    Change,
    Copy,
    Rename,
    ModeChange,
    NoEvent,
}

pub struct StateMachine<'a> {
    pub line: String,
    pub raw_line: String,
    pub state: State,
    pub source: Source,
    pub minus_file: String,
    pub plus_file: String,
    pub minus_file_event: FileEvent,
    pub plus_file_event: FileEvent,
    pub diff_line: String,
    pub mode_info: String,
    pub painter: Painter<'a>,
    pub config: &'a Config,
    pub handled_diff_header_header_line_file_pair: Option<(String, String)>,
    pub current_file_pair: Option<(String, String)>,
    pub blame_key_colors: std::collections::HashMap<String, String>,
    pub grep_data: crate::handlers::grep::GrepData,
    pub merge_conflict_lines: crate::handlers::merge_conflict::MergeConflictLines,
}

pub fn delta<I>(lines: I, writer: &mut dyn Write, config: &Config) -> std::io::Result<()>
where
    I: Iterator<Item = std::io::Result<Vec<u8>>>,
{
    StateMachine::new(writer, config).handle_lines(lines)
}

impl<'a> StateMachine<'a> {
    pub fn new(writer: &'a mut dyn Write, config: &'a Config) -> Self {
        StateMachine {
            line: String::new(),
            raw_line: String::new(),
            state: State::Unknown,
            source: Source::Unknown,
            minus_file: String::new(),
            plus_file: String::new(),
            minus_file_event: FileEvent::NoEvent,
            plus_file_event: FileEvent::NoEvent,
            diff_line: String::new(),
            mode_info: String::new(),
            painter: Painter::new(writer, config),
            config,
            handled_diff_header_header_line_file_pair: None,
            current_file_pair: None,
            blame_key_colors: Default::default(),
            grep_data: Default::default(),
            merge_conflict_lines: Default::default(),
        }
    }

    fn ingest_line(&mut self, raw_line_bytes: &[u8]) {
        self.raw_line = String::from_utf8_lossy(raw_line_bytes).to_string();
        // Strip the newline (and CR)
        if self.raw_line.ends_with('\n') {
            self.raw_line.pop();
            if self.raw_line.ends_with('\r') {
                self.raw_line.pop();
            }
        }
        if self.config.max_line_length > 0 && self.raw_line.len() > self.config.max_line_length {
            self.raw_line = ansi::truncate_str(&self.raw_line, self.config.max_line_length, "").to_string();
        }
        self.line = ansi::strip_ansi_codes(&self.raw_line);
    }

    pub fn handle_lines<I>(&mut self, mut lines: I) -> std::io::Result<()>
    where
        I: Iterator<Item = std::io::Result<Vec<u8>>>,
    {
        while let Some(Ok(raw_line_bytes)) = lines.next() {
            self.ingest_line(&raw_line_bytes);
            if self.source == Source::Unknown {
                self.source = detect_source(&self.line);
            }
            let _ = self.handle_commit_meta_header_line()?
                || self.handle_diff_stat_line()?
                || self.handle_diff_header_diff_line()?
                || self.handle_diff_header_file_operation_line()?
                || self.handle_diff_header_minus_line()?
                || self.handle_diff_header_plus_line()?
                || self.handle_hunk_header_line()?
                || self.handle_diff_header_mode_line()?
                || self.handle_diff_header_misc_line()?
                || self.handle_submodule_log_line()?
                || self.handle_submodule_short_line()?
                || self.handle_merge_conflict_line()?
                || self.handle_hunk_line()?
                || self.handle_blame_line()?
                || self.handle_git_show_file_line()?
                || self.handle_grep_line()?
                || self.should_skip_line()
                || self.emit_line_unchanged()?;
        }
        self.handle_pending_line_with_diff_name()?;
        self.painter.paint_buffered_minus_and_plus_lines();
        self.painter.emit()?;
        Ok(())
    }

    /// Should a handle_* function be called on this element?
    pub fn should_handle(&self) -> bool {
        let style = self.config.get_style_for_state(&self.state);
        !(style.is_raw && style.decoration_style == DecorationStyle::NoDecoration)
    }

    pub fn should_skip_line(&self) -> bool {
        matches!(self.state, State::DiffHeader(DiffType::Unified))
            && self.should_handle()
            && !self.config.color_only
    }

    pub fn emit_line_unchanged(&mut self) -> std::io::Result<bool> {
        // Emit the line unchanged, except that in side-by-side / line-number modes
        // hunk lines would have been handled elsewhere.
        self.painter.emit()?;
        writeln!(self.painter.writer, "{}", self.raw_line)?;
        Ok(true)
    }
}

pub fn detect_source(line: &str) -> Source {
    if line.starts_with("commit ") || line.starts_with("diff --git ") {
        Source::GitDiff
    } else if line.starts_with("diff -") || line.starts_with("--- ") {
        Source::DiffUnified
    } else {
        Source::Unknown
    }
}

impl Config {
    pub fn get_style_for_state(&self, state: &State) -> &crate::style::Style {
        match state {
            State::CommitMeta => &self.commit_style,
            State::DiffHeader(_) => &self.file_style,
            State::HunkHeader(..) => &self.hunk_header_style,
            State::SubmoduleLog => &self.file_style,
            State::HunkMinus(_, _) | State::HunkMinusWrapped => &self.minus_style,
            State::HunkZero(_, _) | State::HunkZeroWrapped => &self.zero_style,
            State::HunkPlus(_, _) | State::HunkPlusWrapped => &self.plus_style,
            _ => &self.null_style,
        }
    }
}

/// Read lines from a BufRead, yielding raw bytes including the trailing newline.
pub struct ByteLines<R: BufRead> {
    reader: R,
}

impl<R: BufRead> ByteLines<R> {
    pub fn new(reader: R) -> Self {
        ByteLines { reader }
    }
}

impl<R: BufRead> Iterator for ByteLines<R> {
    type Item = std::io::Result<Vec<u8>>;
    fn next(&mut self) -> Option<Self::Item> {
        let mut buf = Vec::new();
        match self.reader.read_until(b'\n', &mut buf) {
            Ok(0) => None,
            Ok(_) => Some(Ok(buf)),
            Err(e) => Some(Err(e)),
        }
    }
}
EOF
