use regex::Regex;
use std::sync::OnceLock;

use crate::delta::{State, StateMachine};

fn diff_stat_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^ ([^\|]+?) +(\| +[0-9]+ .*)$").unwrap())
}

impl<'a> StateMachine<'a> {
    #[inline]
    fn test_diff_stat_line(&self) -> bool {
        (self.state == State::CommitMeta || self.state == State::Unknown) && self.line.starts_with(' ')
    }

    pub fn handle_diff_stat_line(&mut self) -> std::io::Result<bool> {
        if !self.test_diff_stat_line() {
            return Ok(false);
        }
        let mut handled_line = false;
        if self.config.relative_paths {
            if let Some(cwd) = cwd_relative_to_repo_root() {
                if let Some(replacement_line) =
                    relativize_path_in_diff_stat_line(&self.raw_line, &cwd, self.config.diff_stat_align_width)
                {
                    self.painter.emit()?;
                    writeln!(self.painter.writer, "{}", replacement_line)?;
                    handled_line = true
                }
            }
        }
        Ok(handled_line)
    }
}

pub fn cwd_relative_to_repo_root() -> Option<String> {
    std::env::var("GIT_PREFIX").ok()
}

/// Relativize the path in a diff stat line, keeping the alignment of the `|`.
pub fn relativize_path_in_diff_stat_line(line: &str, cwd_relative_to_repo_root: &str, diff_stat_align_width: usize) -> Option<String> {
    let caps = diff_stat_regex().captures(line)?;
    let path_relative_to_repo_root = caps.get(1)?.as_str();
    let relative_path = crate::handlers::diff_header::relativize_path(path_relative_to_repo_root, cwd_relative_to_repo_root)?;
    let suffix = caps.get(2)?.as_str();
    let pad_width = diff_stat_align_width.saturating_sub(unicode_width::UnicodeWidthStr::width(relative_path.as_str()));
    Some(format!(" {}{} {}", relative_path, " ".repeat(pad_width), suffix))
}
EOF
