        self.plus_file = String::new();
        self.minus_file_event = FileEvent::NoEvent;
        self.plus_file_event = FileEvent::NoEvent;
        self.mode_info = String::new();
        if !self.should_skip_line() {
            self.emit_line_unchanged()?;
        }
        Ok(true)
    }

    #[inline]
    fn test_diff_header_file_operation_line(&self) -> bool {
        false
    }

    pub fn handle_diff_header_file_operation_line(&mut self) -> std::io::Result<bool> {
        if !self.test_diff_header_file_operation_line() {
            return Ok(false);
        }
        Ok(false)
    }

    #[inline]
    fn test_diff_header_minus_line(&self) -> bool {
        (matches!(self.state, State::DiffHeader(_)) || self.source == Source::DiffUnified)
            && (self.line.starts_with("--- ")
                || self.line.starts_with("rename from ")
                || self.line.starts_with("copy from "))
    }

    pub fn handle_diff_header_minus_line(&mut self) -> std::io::Result<bool> {
        if !self.test_diff_header_minus_line() {
            return Ok(false);
        }
        let mut handled_line = false;
        self.painter.paint_buffered_minus_and_plus_lines();
        if !matches!(self.state, State::DiffHeader(_)) {
            self.state = State::DiffHeader(DiffType::Unified);
        }
        let (file, event) = parse_diff_header_line(&self.line, self.source == Source::GitDiff);
        self.minus_file = file;
        self.minus_file_event = event;
        if self.source == Source::DiffUnified {
            self.painter.set_syntax(get_file_extension_from_marker_line(&self.line));
        } else {
            self.painter.set_syntax(get_file_extension_from_diff_header_line_file_path(&self.minus_file));
        }
        // In color_only mode, raw_line should be printed with the file style.
        if self.config.color_only {
            write_generic_diff_header_header_line(&self.line, &self.raw_line, &mut self.painter, self.config)?;
            handled_line = true;
        }
