    }

    #[inline]
    fn test_diff_header_plus_line(&self) -> bool {
        (matches!(self.state, State::DiffHeader(_)) || self.source == Source::DiffUnified)
            && (self.line.starts_with("+++ ")
                || self.line.starts_with("rename to ")
                || self.line.starts_with("copy to "))
    }

    pub fn handle_diff_header_plus_line(&mut self) -> std::io::Result<bool> {
        if !self.test_diff_header_plus_line() {
            return Ok(false);
        }
        let mut handled_line = false;
        self.painter.paint_buffered_minus_and_plus_lines();
        if !matches!(self.state, State::DiffHeader(_)) {
            self.state = State::DiffHeader(DiffType::Unified);
        }
        let (file, event) = parse_diff_header_line(&self.line, self.source == Source::GitDiff);
        self.plus_file = file;
        self.plus_file_event = event;
        self.painter.set_syntax(get_file_extension_from_diff_header_line_file_path(&self.plus_file));
        self.current_file_pair = Some((self.minus_file.clone(), self.plus_file.clone()));

        // In color_only mode, raw_line should be printed with the file style.
        if self.config.color_only {
            write_generic_diff_header_header_line(&self.line, &self.raw_line, &mut self.painter, self.config)?;
            handled_line = true;
        } else if self.should_handle() && self.handled_diff_header_header_line_file_pair != self.current_file_pair {
