            }
            self.handled_diff_header_header_line_file_pair = Some((self.minus_file.clone(), self.plus_file.clone()));
            self.diff_line = String::new();
        }
        Ok(())
    }
}

/// Write a file header line with decoration.
pub fn write_generic_diff_header_header_line(
    line: &str,
    raw_line: &str,
    painter: &mut Painter,
    config: &Config,
) -> std::io::Result<()> {
    // If file_style is "omit", we'll skip the process and print nothing.
    // However in the case of color_only mode, we won't skip because we can't change raw_line structure.
    if config.file_style.is_omitted && !config.color_only {
        return Ok(());
    }
    if config.color_only {
        if config.file_style.is_raw {
            writeln!(painter.writer, "{}", raw_line)?;
        } else {
            writeln!(painter.writer, "{}", config.file_style.ansi_term_style.paint(line))?;
        }
        return Ok(());
    }
    let (mut draw_fn, pad, decoration_ansi_term_style) = draw::get_draw_function(config.file_style.decoration_style);
    // Prints the new line below file-meta-line.
    writeln!(painter.writer)?;
    draw_fn(
        painter.writer,
        &format!("{}{}", line, if pad { " " } else { "" }),
        &format!("{}{}", raw_line, if pad { " " } else { "" }),
        &config.decorations_width,
        config.file_style,
        decoration_ansi_term_style,
    )?;
    Ok(())
}

pub fn get_file_change_description_from_file_paths(
    minus_file: &str,
    plus_file: &str,
    comparing: bool,
    minus_file_event: &FileEvent,
    plus_file_event: &FileEvent,
    config: &Config,
) -> String {
    let format_label = |label: &str| {
        if !label.is_empty() {
            format!("{} ", label)
        } else {
            "".to_string()
        }
    };
    let format_file = |file: &str| -> String {
        let file = if config.relative_paths {
            match crate::handlers::diff_stat::cwd_relative_to_repo_root() {
                Some(cwd) => relativize_path(file, &cwd).unwrap_or_else(|| file.to_string()),
                None => file.to_string(),
            }
        } else {
            file.to_string()
        };
        let file = match &config.file_regex_replacement {
            Some((re, replacement)) => re.replace_all(&file, replacement.as_str()).to_string(),
            None => file,
        };
        if config.hyperlinks {
            hyperlinks::format_osc8_file_hyperlink(&file, None, &file, config)
        } else {
            file
        }
    };
    if comparing {
        format!(
            "{}{} {} {}",
            format_label(&config.file_modified_label),
            format_file(minus_file),
            config.right_arrow,
            format_file(plus_file)
        )
    } else {
        match (minus_file, plus_file, minus_file_event, plus_file_event) {
            (minus_file, plus_file, _, _) if minus_file == plus_file => format!(
                "{}{}",
                format_label(&config.file_modified_label),
                format_file(plus_file)
            ),
            (minus_file, "/dev/null", _, _) => format!(
                "{}{}",
                format_label(&config.file_removed_label),
                format_file(minus_file)
            ),
            ("/dev/null", plus_file, _, _) => format!(
                "{}{}",
                format_label(&config.file_added_label),
                format_file(plus_file)
            ),
            (minus_file, plus_file, _, FileEvent::Rename) | (minus_file, plus_file, FileEvent::Rename, _) => format!(
                "{}{} {} {}",
                format_label(&config.file_renamed_label),
                format_file(minus_file),
                config.right_arrow,
                format_file(plus_file)
            ),
            (minus_file, plus_file, _, FileEvent::Copy) | (minus_file, plus_file, FileEvent::Copy, _) => format!(
                "{}{} {} {}",
                format_label(&config.file_copied_label),
                format_file(minus_file),
                config.right_arrow,
                format_file(plus_file)
            ),
            (minus_file, plus_file, _, _) => format!(
                "{}{} {} {}",
                format_label(&config.file_modified_label),
                format_file(minus_file),
                config.right_arrow,
                format_file(plus_file)
            ),
        }
    }
}

/// Parse a "--- a/path" / "+++ b/path" / "rename from path" line.
pub fn parse_diff_header_line(line: &str, git_diff_name: bool) -> (String, FileEvent) {
    if let Some(rest) = line.strip_prefix("--- ").or_else(|| line.strip_prefix("+++ ")) {
        (_parse_file_path(rest, git_diff_name), FileEvent::Change)
    } else if let Some(rest) = line.strip_prefix("rename from ") {
        (_parse_file_path(rest, git_diff_name), FileEvent::Rename)
    } else if let Some(rest) = line.strip_prefix("rename to ") {
        (_parse_file_path(rest, git_diff_name), FileEvent::Rename)
    } else if let Some(rest) = line.strip_prefix("copy from ") {
        (_parse_file_path(rest, git_diff_name), FileEvent::Copy)
    } else if let Some(rest) = line.strip_prefix("copy to ") {
        (_parse_file_path(rest, git_diff_name), FileEvent::Copy)
    } else {
        ("".to_string(), FileEvent::NoEvent)
    }
}

fn _parse_file_path(s: &str, git_diff_name: bool) -> String {
    // If the file name contains a space, git appends a tab character in the diff metadata lines.
    let s = if git_diff_name {
        s.strip_suffix('\t').unwrap_or(s)
    } else {
        s.split('\t').next().unwrap_or("")
    };
    // Strip quotes around the path
    let s = if s.len() >= 2 && s.starts_with('"') && s.ends_with('"') {
        &s[1..s.len() - 1]
    } else {
        s
    };
    let path = if s == "/dev/null" {
        s
    } else if git_diff_name && DIFF_PREFIXES.iter().any(|p| s.starts_with(p)) {
        &s[2..]
    } else {
        s
    };
    path.to_string()
}

/// Given "diff --git a/src/main.rs b/src/main.rs", return Some("src/main.rs").
pub fn get_repeated_file_path_from_diff_line(line: &str) -> Option<String> {
    if let Some(line) = line.strip_prefix("diff --git ") {
        let graphemes: Vec<&str> = line.graphemes(true).collect();
        let midpoint = graphemes.len() / 2;
        if midpoint < graphemes.len() && graphemes[midpoint] == " " {
            let first_path = _parse_file_path(&graphemes[..midpoint].concat(), true);
            let second_path = _parse_file_path(&graphemes[midpoint + 1..].concat(), true);
            if first_path == second_path {
                return Some(first_path);
            }
        }
    } else if let Some(line) = line.strip_prefix("diff --cc ") {
        return Some(line.to_string());
    } else if let Some(line) = line.strip_prefix("diff --combined ") {
        return Some(line.to_string());
    }
    None
}

pub fn get_file_extension_from_marker_line(line: &str) -> Option<&str> {
    line.split('\t')
        .next()
        .and_then(|column| column.split(' ').nth(1))
        .and_then(|file| file.split('.').last())
}

pub fn get_file_extension_from_diff_header_line_file_path(path: &str) -> Option<&str> {
    if path.is_empty() || path == "/dev/null" {
        None
    } else {
        get_extension(path).map(|ex| ex.trim())
    }
}

fn get_extension(s: &str) -> Option<&str> {
    let path = Path::new(s);
    path.extension()
        .and_then(|e| e.to_str())
        .or_else(|| path.file_name().and_then(|s| s.to_str()))
}

/// Relativize `path` (relative to repo root) with respect to `cwd` (also
/// relative to repo root, e.g. "sub/").
pub fn relativize_path(path: &str, cwd_relative_to_repo_root: &str) -> Option<String> {
    if path == "/dev/null" {
        return Some(path.to_string());
    }
    let base = Path::new(cwd_relative_to_repo_root);
    let path = Path::new(path);
    let base_components: Vec<Component> = base.components().collect();
    let path_components: Vec<Component> = path.components().collect();
    let mut i = 0;
    while i < base_components.len() && i < path_components.len() && base_components[i] == path_components[i] {
        i += 1;
    }
    let mut result = PathBuf::new();
    for _ in i..base_components.len() {
        result.push("..");
    }
    for c in &path_components[i..] {
        result.push(c.as_os_str());
    }
    Some(result.to_string_lossy().to_string())
}

#[allow(dead_code)]
pub fn cow_str(s: &str) -> Cow<str> {
    Cow::from(s)
}
