//! Hunk header lines: `@@ -1,3 +1,3 @@ code`

use std::fmt::Write as _;

use regex::Regex;
use std::sync::OnceLock;

use crate::ansi::Painted;
use crate::config::Config;
use crate::delta::{DiffType, InMergeConflict, MergeParents, ParsedHunkHeader, State, StateMachine};
use crate::features::hyperlinks;
use crate::handlers::draw;
use crate::paint::Painter;
use crate::style::DecorationStyle;

fn hunk_header_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^(@+)\s+(.+?)\s+@+(.*)$").unwrap())
}

fn hunk_header_file_coordinate_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"[-+]([0-9]+)(?:,([0-9]+))?").unwrap())
}

pub fn parse_hunk_header(line: &str) -> Option<ParsedHunkHeader> {
    let caps = hunk_header_regex().captures(line)?;
    let file_coordinates = &caps[2];
    let mut line_numbers_and_hunk_lengths = Vec::new();
    for caps in hunk_header_file_coordinate_regex().captures_iter(file_coordinates) {
        let n: usize = caps[1].parse().ok()?;
        let len: usize = caps.get(2).map(|m| m.as_str().parse().unwrap_or(1)).unwrap_or(1);
        line_numbers_and_hunk_lengths.push((n, len));
    }
    if line_numbers_and_hunk_lengths.is_empty() {
        return None;
    }
    let code_fragment = caps[3].to_string();
    Some(ParsedHunkHeader {
        code_fragment,
        line_numbers_and_hunk_lengths,
    })
}

impl<'a> StateMachine<'a> {
    #[inline]
    fn test_hunk_header_line(&self) -> bool {
        self.line.starts_with("@@")
    }

    pub fn handle_hunk_header_line(&mut self) -> std::io::Result<bool> {
        if !self.test_hunk_header_line() {
            return Ok(false);
        }
        let parsed = match parse_hunk_header(&self.line) {
            Some(p) => p,
            None => return Ok(false),
        };
        self.painter.paint_buffered_minus_and_plus_lines();
        self.handle_pending_line_with_diff_name()?;
        let diff_type = match &self.state {
            State::DiffHeader(DiffType::Combined(_, _)) | State::HunkHeader(DiffType::Combined(_, _), ..) => {
                let n = parsed.line_numbers_and_hunk_lengths.len().saturating_sub(1).max(1);
                DiffType::Combined(MergeParents::Number(n), InMergeConflict::No)
            }
            State::HunkZero(DiffType::Combined(p, _), _)
            | State::HunkMinus(DiffType::Combined(p, _), _)
            | State::HunkPlus(DiffType::Combined(p, _), _) => DiffType::Combined(p.clone(), InMergeConflict::No),
            _ => {
                if self.line.starts_with("@@@") {
                    let n = parsed.line_numbers_and_hunk_lengths.len().saturating_sub(1).max(1);
                    DiffType::Combined(MergeParents::Number(n), InMergeConflict::No)
                } else {
                    DiffType::Unified
                }
            }
        };
        self.state = State::HunkHeader(diff_type, parsed, self.line.clone(), self.raw_line.clone());
        Ok(true)
    }

    /// Emit the hunk header line held in the state (called when the first hunk line arrives).
    pub fn emit_hunk_header_line(&mut self, parsed: &ParsedHunkHeader, line: &str, raw_line: &str) -> std::io::Result<bool> {
        self.painter.set_highlighter();
        self.painter.emit()?;
        if let Some(data) = self.painter.line_numbers_data.as_mut() {
            data.initialize_hunk(&parsed.line_numbers_and_hunk_lengths, self.plus_file.clone());
        }
        if self.config.hunk_header_style.is_raw {
            write_hunk_header_raw(&mut self.painter, line, raw_line, self.config)?;
        } else if self.config.hunk_header_style.is_omitted {
            writeln!(self.painter.writer)?;
        } else {
            // Add a blank line below the hunk-header-line for readability, unless color_only mode is active.
            if !self.config.color_only {
                writeln!(self.painter.writer)?;
            }
            write_hunk_header(
                &parsed.code_fragment,
                &parsed.line_numbers_and_hunk_lengths,
                &mut self.painter,
                line,
                &self.plus_file,
                self.config,
            )?;
        }
        self.painter.set_highlighter();
        Ok(true)
    }
}

fn write_hunk_header_raw(painter: &mut Painter, line: &str, raw_line: &str, config: &Config) -> std::io::Result<()> {
    let (mut draw_fn, pad, decoration_ansi_term_style) = draw::get_draw_function(config.hunk_header_style.decoration_style);
    if config.hunk_header_style.decoration_style != DecorationStyle::NoDecoration {
        writeln!(painter.writer)?;
    }
    draw_fn(
        painter.writer,
        &format!("{}{}", line, if pad { " " } else { "" }),
        &format!("{}{}", raw_line, if pad { " " } else { "" }),
        &config.decorations_width,
        config.hunk_header_style,
        decoration_ansi_term_style,
    )?;
    Ok(())
}

pub fn write_hunk_header(
    code_fragment: &str,
    line_numbers: &[(usize, usize)],
    painter: &mut Painter,
    line: &str,
    plus_file: &str,
    config: &Config,
) -> std::io::Result<()> {
    let (mut draw_fn, _, decoration_ansi_term_style) = draw::get_draw_function(config.hunk_header_style.decoration_style);
    let line = if config.color_only {
        format!(" {}", &line)
    } else if !code_fragment.is_empty() {
        format!("{} ", code_fragment)
    } else {
        "".to_string()
    };

    let file_with_line_number = get_painted_file_with_line_number(line_numbers, plus_file, config);

    if !line.is_empty() || !file_with_line_number.is_empty() {
        write_to_output_buffer(&file_with_line_number, line, painter, config);
        let buf = std::mem::take(&mut painter.output_buffer);
        draw_fn(
            painter.writer,
            &buf,
            &buf,
            &config.decorations_width,
            config.null_style,
            decoration_ansi_term_style,
        )?;
    }
    Ok(())
}

fn get_painted_file_with_line_number(line_numbers: &[(usize, usize)], plus_file: &str, config: &Config) -> String {
    let mut parts: Vec<Painted> = Vec::new();
    let plus_line_number = line_numbers.last().map(|(n, _)| *n).unwrap_or(0);
    if !config.hunk_label.is_empty() {
        parts.push(Painted::new(config.hunk_header_file_style.ansi_term_style, config.hunk_label.clone()));
        parts.push(Painted::new(Default::default(), " "));
    }
    if config.hunk_header_style_include_file_path {
        parts.push(Painted::new(config.hunk_header_file_style.ansi_term_style, plus_file));
    }
    if config.hunk_header_style_include_line_number {
        if config.hunk_header_style_include_file_path {
            parts.push(Painted::new(Default::default(), ":"));
        }
        parts.push(Painted::new(
            config.hunk_header_line_number_style.ansi_term_style,
            plus_line_number.to_string(),
        ));
    }
    let mut s = crate::ansi::paint_strings(&parts);
    if config.hyperlinks
        && !s.is_empty()
        && (config.hunk_header_style_include_file_path || config.hunk_header_style_include_line_number)
    {
        s = hyperlinks::format_osc8_file_hyperlink(plus_file, Some(plus_line_number), &s, config);
    }
    if config.hunk_header_style_include_file_path || config.hunk_header_style_include_line_number {
        s.push(':');
    }
    s
}

fn write_to_output_buffer(file_with_line_number: &str, line: String, painter: &mut Painter, config: &Config) {
    if !file_with_line_number.is_empty() {
        let _ = write!(&mut painter.output_buffer, "{}", file_with_line_number);
    }
    if !line.is_empty() {
        let state = State::HunkHeader(
            DiffType::Unified,
            ParsedHunkHeader {
                code_fragment: String::new(),
                line_numbers_and_hunk_lengths: vec![],
            },
            String::new(),
            String::new(),
        );
        let fg = painter.syntax_fg;
        let painted = crate::paint::paint_text_with_style(&line, &config.hunk_header_style, fg, config);
        painter.output_buffer.push_str(&painted);
        let _ = state;
    } else if !file_with_line_number.is_empty() {
        painter.output_buffer.push(' ');
    }
}
