            Some(State::HunkMinus(diff_type, _)) => {
                if let State::HunkPlus(_, _) = self.state {
                    // We have just entered a new subhunk; process the previous one
                    // and flush the line buffers.
                    self.painter.paint_buffered_minus_and_plus_lines();
                }
                let n_parents = diff_type.n_parents();
                let line = self.painter.prepare(&self.line, n_parents);
                let raw_line = self.maybe_raw_line(
                    n_parents,
                    &[self.config.minus_style, self.config.minus_emph_style, self.config.git_minus_style()],
                );
                let state = State::HunkMinus(diff_type, raw_line);
                self.painter.minus_lines.push((line, state.clone()));
                state
            }
            Some(State::HunkPlus(diff_type, _)) => {
                let n_parents = diff_type.n_parents();
                let line = self.painter.prepare(&self.line, n_parents);
                let raw_line = self.maybe_raw_line(
                    n_parents,
                    &[self.config.plus_style, self.config.plus_emph_style, self.config.git_plus_style()],
                );
                let state = State::HunkPlus(diff_type, raw_line);
                self.painter.plus_lines.push((line, state.clone()));
                state
            }
            Some(State::HunkZero(diff_type, _)) => {
                // We are in a zero (unchanged) line, therefore we have just completed a subhunk;
                // process it and flush the line buffers.
                self.painter.paint_buffered_minus_and_plus_lines();
                let n_parents = diff_type.n_parents();
                let line = self.painter.prepare(&self.line, n_parents);
                let raw_line = self.maybe_raw_line(n_parents, &[self.config.zero_style]);
                let state = State::HunkZero(diff_type, raw_line);
                self.painter.paint_zero_line(&line, state.clone());
                state
            }
            _ => {
                // The first character here could be e.g. '\' from '\ No newline at end of file'.
                self.painter.paint_buffered_minus_and_plus_lines();
                let expanded = crate::paint::expand_tabs(&self.raw_line, self.config);
                self.painter.output_buffer.push_str(&expanded);
                self.painter.output_buffer.push('\n');
                State::HunkZero(DiffType::Unified, None)
            }
        };
        self.painter.emit()?;
