    }

    fn maybe_raw_line(&self, prefix_length: usize, styles: &[Style]) -> Option<String> {
        let emit_raw_line = self.config.inspect_raw_lines == InspectRawLines::True
            && line_has_style_other_than(&self.raw_line, styles);
        if emit_raw_line {
            Some(self.painter.prepare_raw_line(&self.raw_line, prefix_length))
        } else {
            None
        }
    }
}

