pub fn line_has_style_other_than(line: &str, styles: &[Style]) -> bool {
    if !string_starts_with_ansi_style_sequence(line) {
        return false;
    }
    for style in styles {
        if style.is_applied_to(line) {
            return false;
        }
    }
    true
}

fn string_starts_with_ansi_style_sequence(s: &str) -> bool {
    matches!(ansi::elements(s).first(), Some(ansi::Element::Sgr(_, _, _)))
}

