        }
        cmd.env("LESSCHARSET", "UTF-8");
    }
    cmd.args(&args);
    cmd.stdin(std::process::Stdio::piped());
    cmd.spawn().ok()
}

fn print_through_pager(text: &str) {
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let _ = out.write_all(text.as_bytes());
    let _ = out.flush();
}

/// Compute derived option values.
fn compute_values(opt: &mut Opt) {
    let stdout_is_term = io::stdout().is_terminal();
    opt.computed.stdout_is_term = stdout_is_term;

    // true color
    opt.computed.true_color = match opt.true_color.as_str() {
        "always" => true,
        "never" => false,
        _ => match opt.bit24_color.as_deref() {
            Some("always") => true,
            Some("never") => false,
            _ => {
                let colorterm = std::env::var("COLORTERM").unwrap_or_default();
                colorterm == "truecolor" || colorterm == "24bit"
            }
        },
    };

    // light/dark mode and syntax theme
    let bat_theme = std::env::var("BAT_THEME").ok().filter(|s| !s.is_empty());
    let theme_arg = opt.syntax_theme.clone().or(bat_theme);
    let (is_light_mode, theme_name) = match (&theme_arg, opt.light, opt.dark) {
        (_, true, _) => (true, theme_arg.clone()),
        (_, _, true) => (false, theme_arg.clone()),
        (Some(name), false, false) => (syntax::is_light_syntax_theme(name), Some(name.clone())),
        (None, false, false) => (false, None),
    };
    opt.computed.is_light_mode = is_light_mode;
    let default_theme = if is_light_mode {
        syntax::DEFAULT_LIGHT_SYNTAX_THEME
    } else {
        syntax::DEFAULT_DARK_SYNTAX_THEME
    };
    opt.computed.syntax_theme_name = match theme_name {
        Some(name) if syntax::is_no_syntax_highlighting_theme_name(&name) => None,
        Some(name) => {
            if syntax::theme_exists(&name) {
                Some(name)
            } else {
                eprintln!("\x1b[33m[bat warning]\x1b[0m: Unknown theme '{}', using default.", name);
                Some(syntax::DEFAULT_DARK_SYNTAX_THEME.to_string())
            }
        }
        None => Some(default_theme.to_string()),
    };

    // width
    let terminal_width = if stdout_is_term {
        terminal_width().unwrap_or(80)
    } else {
        80
    };
    let (available_terminal_width, decorations_width, background_color_extends) = parse_width(opt.width.as_deref(), terminal_width);
    opt.computed.available_terminal_width = available_terminal_width;
    opt.computed.decorations_width = decorations_width;
    opt.computed.background_color_extends_to_terminal_width = background_color_extends;

    opt.computed.inspect_raw_lines = opt.inspect_raw_lines != "false";

    opt.computed.paging_mode = match opt.paging.as_str() {
        "always" => PagingMode::Always,
        "never" => PagingMode::Never,
        _ => PagingMode::QuitIfOneScreen,
    };
    if opt.color_only {
        opt.computed.paging_mode = PagingMode::Never;
    }

    opt.computed.line_fill_method_ansi = match opt.line_fill_method.as_deref() {
        Some("ansi") => stdout_is_term,
        Some("spaces") => false,
        _ => stdout_is_term,
    };
}

fn terminal_width() -> Option<usize> {
    // Use ioctl TIOCGWINSZ via libc-free approach: read from `stty size`? Avoid spawning;
    // fall back to COLUMNS.
    unsafe {
        #[repr(C)]
        struct WinSize {
            ws_row: u16,
            ws_col: u16,
            ws_xpixel: u16,
            ws_ypixel: u16,
        }
        extern "C" {
            fn ioctl(fd: i32, request: u64, ...) -> i32;
        }
        let mut ws = WinSize {
            ws_row: 0,
            ws_col: 0,
            ws_xpixel: 0,
            ws_ypixel: 0,
        };
        const TIOCGWINSZ: u64 = 0x5413;
        if ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize) == 0 && ws.ws_col > 0 {
            return Some(ws.ws_col as usize);
        }
    }
    std::env::var("COLUMNS").ok().and_then(|c| c.parse().ok())
}

fn parse_width(width: Option<&str>, terminal_width: usize) -> (usize, Width, bool) {
    match width {
        Some("variable") => (terminal_width, Width::Variable, false),
        Some(s) => {
            let s = s.trim();
            let n = if let Some(rest) = s.strip_prefix('-') {
                // "-N": terminal width minus N
                let n: usize = match rest.parse() {
                    Ok(n) => n,
                    Err(_) => {
                        eprintln!("Invalid value for width: \"{}\" is not a negative integer", s);
                        std::process::exit(2);
                    }
                };
                if n > terminal_width {
                    eprintln!(
                        "Invalid value for width: the current terminal width of {} minus {} is negative",
                        terminal_width, n
                    );
                    std::process::exit(2);
                }
                terminal_width - n
            } else if let Some(idx) = s.find('-') {
                let (a, b) = (&s[..idx], &s[idx..]);
                let a: usize = match a.parse() {
                    Ok(n) => n,
                    Err(_) => {
                        eprintln!("Invalid value for width: \"{}\" is not an integer", s);
                        std::process::exit(2);
                    }
                };
                let bn: usize = match b[1..].parse() {
                    Ok(n) => n,
                    Err(_) => {
                        eprintln!("Invalid value for width: \"{}\" (from \"{}\") is not a negative integer", b, s);
                        std::process::exit(2);
                    }
                };
                if bn >= a {
                    eprintln!("Invalid value for width: expression \"{}\" is not positive", s);
                    std::process::exit(2);
                }
                a - bn
            } else {
                match s.parse::<usize>() {
                    Ok(n) => n,
                    Err(_) => {
                        eprintln!("Invalid value for width: \"{}\" is not an integer", s);
                        std::process::exit(2);
                    }
                }
            };
            (n, Width::Fixed(n), true)
        }
        None => (terminal_width, Width::Fixed(terminal_width), true),
    }
}
