pub fn parse_ansi() -> i32 {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        let _ = writeln!(out, "{}", crate::ansi::explain_ansi(&line, true));
    }
    let _ = out.flush();
    0
}

/// Diff two files using `git diff --no-index` (falling back to `diff -u`) and process the output.
pub fn diff(config: &Config) -> i32 {
    let minus = match &config.minus_file {
        Some(f) => f.clone(),
        None => {
            eprintln!("Usage: delta [OPTIONS] [MINUS_FILE] [PLUS_FILE]");
            return config.error_exit_code;
        }
    };
    let plus = match &config.plus_file {
        Some(f) => f.clone(),
        None => {
            eprintln!("Usage: delta [OPTIONS] [MINUS_FILE] [PLUS_FILE]");
            return config.error_exit_code;
        }
    };
    let mut cmd = std::process::Command::new("git");
    cmd.args(["diff", "--no-index", "--color"]);
    for arg in config.opt.diff_args.split_whitespace() {
        cmd.arg(arg);
    }
    cmd.arg(&minus).arg(&plus);
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::inherit());
    let child = match cmd.spawn() {
        Ok(c) => c,
        Err(_) => {
            // fall back to diff -u
            let mut c = std::process::Command::new("diff");
            c.arg("-u").arg(&minus).arg(&plus);
            c.stdout(std::process::Stdio::piped());
            match c.spawn() {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("Failed to execute diff: {}", e);
                    return config.error_exit_code;
                }
            }
        }
    };
    let mut child = child;
    let stdout = child.stdout.take().unwrap();
    let reader = io::BufReader::new(stdout);
    let code = crate::run_delta(crate::delta::ByteLines::new(reader), config);
    let status = child.wait();
    match status {
        Ok(s) => {
            // git diff exits 1 when there are differences; delta mirrors that
            if let Some(c) = s.code() {
                if c != 0 && c != 1 {
                    return c;
                }
                return if code != 0 { code } else { c };
            }
            code
        }
        Err(_) => code,
    }
}
