def eq_swapped(x, y, i, j):
    if i < len(x) and j < len(y): return x[i] == y[j]
    return False
def eq_both(x, y, i, j):
    return x[j]==y[i] and (i >= len(x) or j >= len(y) or x[i]==y[j])
def eq_prev(x, y, i, j):
    return x[j]==y[i] and x[j-1]==y[i-1]
def eq_next(x, y, i, j):
    return x[j]==y[i] and (j+1 >= len(x) or i+1 >= len(y) or x[j+1]==y[i+1])
def eq_prevornext(x, y, i, j):
