import sys
exec("def render" + open('/tmp/exp/dp4.py').read().split("def render")[1].split("def annotate")[0])
def all_optimal(x, y):
    # x, y token lists (no leading ""), unit del/ins, no sub. Return list of op-sequences (strings over N/D/I) with min cost.
    n, m = len(x), len(y)
    D = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        for j in range(m+1):
            if i == 0 and j == 0: continue
            c = []
            if i > 0: c.append(D[i-1][j] + 1)
            if j > 0: c.append(D[i][j-1] + 1)
            if i > 0 and j > 0 and x[i-1] == y[j-1]: c.append(D[i-1][j-1])
            D[i][j] = min(c)
    results = []
    def rec(i, j, acc):
        if i == 0 and j == 0:
            results.append(acc[::-1]); return
        if i > 0 and j > 0 and x[i-1] == y[j-1] and D[i-1][j-1] == D[i][j]:
            rec(i-1, j-1, acc + [('N', i-1, j-1)])
        if i > 0 and D[i-1][j] + 1 == D[i][j]:
