{"command":"cd /workspace && cat > src/align.rs <<'EOF'
//! Alignment of token sequences.
//!
//! The alignment minimizes the number of edit operations (deletions and
//! insertions; substitutions are not used) and, secondarily, the number of
//! contiguous edit regions. Ties are broken in favour of insertions, then
//! deletions, then matches, scanning from the end of the sequences.

const REGION_COST: usize = 1;
const OP_COST: usize = 2;
const INF: usize = usize::MAX / 4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Operation {
    NoOp,
    Deletion,
    Insertion,
    /// A whitespace match that is displayed as an edit on both sides.
    Absorbed,
}

#[derive(Clone, Copy, Debug)]
struct Back {
    from_edit: bool,
    i: usize,
    j: usize,
    op: Operation,
}

/// Compute the alignment of x (old) and y (new). Both sequences must start
/// with a dummy "" token. Returns the operations in order, each with the
/// indices (j into x, i into y) of the tokens it consumes.
pub fn align(x: &[&str], y: &[&str]) -> Vec<(Operation, usize, usize)> {
    let n = y.len();
    let m = x.len();
    let idx = |i: usize, j: usize| i * m + j;
    // Cost of best alignment of x[..=j], y[..=i] ending in a match (M) or an edit (E).
    let mut cost_m = vec![INF; n * m];
    let mut cost_e = vec![INF; n * m];
    let mut back_m: Vec<Option<Back>> = vec![None; n * m];
    let mut back_e: Vec<Option<Back>> = vec![None; n * m];
    cost_m[0] = 0;
    for i in 0..n {
        for j in 0..m {
            if i == 0 && j == 0 {
                continue;
            }
            // Edit state: candidates in preference order (strict improvement required to replace).
            let mut best: Option<(usize, Back)> = None;
            let mut consider = |c: usize, b: Back| {
                if c < INF {
                    match best {
                        Some((bc, _)) if bc <= c => {}
                        _ => best = Some((c, b)),
                    }
                }
            };
            if i > 0 {
                consider(
                    cost_m[idx(i - 1, j)].saturating_add(REGION_COST + OP_COST),
                    Back { from_edit: false, i: i - 1, j, op: Operation::Insertion },
                );
                consider(
                    cost_e[idx(i - 1, j)].saturating_add(OP_COST),
                    Back { from_edit: true, i: i - 1, j, op: Operation::Insertion },
                );
            }
            if j > 0 {
                consider(
                    cost_m[idx(i, j - 1)].saturating_add(REGION_COST + OP_COST),
                    Back { from_edit: false, i, j: j - 1, op: Operation::Deletion },
                );
                consider(
                    cost_e[idx(i, j - 1)].saturating_add(OP_COST),
                    Back { from_edit: true, i, j: j - 1, op: Operation::Deletion },
                );
            }
            if let Some((c, b)) = best {
                cost_e[idx(i, j)] = c;
                back_e[idx(i, j)] = Some(b);
            }
            // Match state
            if i > 0 && j > 0 && x[j] == y[i] {
                let ce = cost_e[idx(i - 1, j - 1)];
                let cm = cost_m[idx(i - 1, j - 1)];
                if ce < INF && ce <= cm {
                    cost_m[idx(i, j)] = ce;
                    back_m[idx(i, j)] = Some(Back { from_edit: true, i: i - 1, j: j - 1, op: Operation::NoOp });
                } else if cm < INF {
                    cost_m[idx(i, j)] = cm;
                    back_m[idx(i, j)] = Some(Back { from_edit: false, i: i - 1, j: j - 1, op: Operation::NoOp });
                }
            }
        }
    }
    let mut i = n - 1;
    let mut j = m - 1;
    let mut in_edit = cost_e[idx(i, j)] <= cost_m[idx(i, j)];
    let mut ops = Vec::new();
    while !(i == 0 && j == 0) {
        let b = if in_edit { back_e[idx(i, j)] } else { back_m[idx(i, j)] };
        let b = match b {
            Some(b) => b,
            None => break,
        };
        ops.push((b.op, j, i));
        in_edit = b.from_edit;
        i = b.i;
        j = b.j;
    }
    ops.reverse();
    ops
}

fn is_whitespace(token: &str) -> bool {
    !token.is_empty() && token.chars().all(char::is_whitespace)
}

/// Convert runs of whitespace matches that are surrounded by edits into
/// "absorbed" operations, which are displayed as edits on both sides.
pub fn absorb_whitespace(ops: &mut [(Operation, usize, usize)], x: &[&str], y: &[&str]) {
    let n = ops.len();
    let is_edit = |op: Operation| matches!(op, Operation::Deletion | Operation::Insertion);
    let mut k = 0;
    while k < n {
        if ops[k].0 == Operation::NoOp && is_whitespace(x[ops[k].1]) {
            let mut e = k;
            while e < n && ops[e].0 == Operation::NoOp && is_whitespace(x[ops[e].1]) {
                e += 1;
            }
            // The run is ops[k..e]. It must be preceded by an edit, and followed by an edit or the end.
            if k > 0 && is_edit(ops[k - 1].0) && (e == n || is_edit(ops[e].0)) {
                let mut has_deletion = false;
                let mut has_insertion = false;
                let mut p = k;
                while p > 0 && is_edit(ops[p - 1].0) {
                    match ops[p - 1].0 {
                        Operation::Deletion => has_deletion = true,
                        Operation::Insertion => has_insertion = true,
                        _ => {}
                    }
                    p -= 1;
                }
                let x_cond = ops[k].1 == 1 || has_deletion;
                let y_cond = ops[k].2 == 1 || has_insertion;
                if x_cond && y_cond {
                    for q in k..e {
                        ops[q].0 = Operation::Absorbed;
                    }
                }
            }
            k = e;
        } else {
            k += 1;
        }
    }
}
