    whitespace_error: Option<S>,
    tokenization_regex: &Regex,
    max_line_distance: f64,
    max_line_distance_for_naively_paired_lines: f64,
) -> (Vec<LineSections<'a, S>>, Vec<LineSections<'a, S>>, Vec<(usize, usize)>) {
    let mut annotated_minus_lines: Vec<LineSections<'a, S>> = Vec::new();
    let mut annotated_plus_lines: Vec<LineSections<'a, S>> = Vec::new();
    let mut line_alignment = Vec::new();

    let mut plus_index = 0; // plus lines emitted so far

    'minus_lines_loop: for (minus_index, minus_line) in minus_lines.iter().enumerate() {
        let mut considered = 0; // plus lines considered so far as match for minus_line
        for plus_line in &plus_lines[plus_index..] {
            let x = tokenize(minus_line, tokenization_regex);
            let y = tokenize(plus_line, tokenization_regex);
            let (annotated_minus_line, annotated_plus_line, distance) = annotate(
                &x,
                &y,
                noop_deletions[minus_index],
                deletion,
                noop_insertions[plus_index + considered],
                insertion,
                whitespace_error,
                minus_line,
                plus_line,
            );
            if distance <= max_line_distance
                || (considered == 0
                    && minus_lines.len() == plus_lines.len()
                    && distance <= max_line_distance_for_naively_paired_lines)
            {
                // Emit as unpaired the plus lines already considered and rejected
                for plus_line in &plus_lines[plus_index..(plus_index + considered)] {
                    annotated_plus_lines.push(unpaired_plus_sections(plus_line, noop_insertions[plus_index], whitespace_error));
                    plus_index += 1;
                }
                annotated_minus_lines.push(annotated_minus_line);
                annotated_plus_lines.push(annotated_plus_line);
                line_alignment.push((minus_index, plus_index));
                plus_index += 1;
                continue 'minus_lines_loop;
            } else {
                considered += 1;
            }
        }
        // No homolog was found for minus i; emit as unpaired.
        annotated_minus_lines.push(vec![(noop_deletions[minus_index], *minus_line)]);
    }
    // Emit any remaining plus lines
    for plus_line in &plus_lines[plus_index..] {
        annotated_plus_lines.push(unpaired_plus_sections(plus_line, noop_insertions[plus_index], whitespace_error));
        plus_index += 1;
    }
    (annotated_minus_lines, annotated_plus_lines, line_alignment)
}

fn distance_contribution(section: &str) -> usize {
    section.trim().graphemes(true).count()
}

/// Annotate the paired lines according to the alignment, returning the
/// annotated lines and the normalized distance.
#[allow(clippy::too_many_arguments)]
fn annotate<'a, S: Copy + PartialEq>(
    x: &[&'a str],
    y: &[&'a str],
    noop_deletion: S,
    deletion: S,
    noop_insertion: S,
    insertion: S,
    whitespace_error: Option<S>,
    minus_line: &'a str,
    plus_line: &'a str,
) -> (LineSections<'a, S>, LineSections<'a, S>, f64) {
    let mut ops = align::align(x, y);

    // Distance, computed from the coalesced raw operations.
    let mut d_numer: usize = 0;
    let mut d_denom: usize = 0;
    {
        let mut x_off = 0usize;
        let mut y_off = 0usize;
        let mut k = 0;
        while k < ops.len() {
            let op = ops[k].0;
            let mut e = k;
            let (mut xl, mut yl) = (0usize, 0usize);
            while e < ops.len() && ops[e].0 == op {
                match op {
                    Operation::NoOp | Operation::Absorbed => {
                        xl += x[ops[e].1].len();
                        yl += y[ops[e].2].len();
                    }
                    Operation::Deletion => xl += x[ops[e].1].len(),
                    Operation::Insertion => yl += y[ops[e].2].len(),
                }
                e += 1;
            }
            let ms = &minus_line[x_off..x_off + xl];
            let ps = &plus_line[y_off..y_off + yl];
            match op {
                Operation::NoOp | Operation::Absorbed => {
                    d_denom += distance_contribution(ms) + distance_contribution(ps);
                }
                Operation::Deletion => {
                    let d = distance_contribution(ms);
                    d_numer += d;
                    d_denom += d;
                }
                Operation::Insertion => {
                    let d = distance_contribution(ps);
                    d_numer += d;
                    d_denom += d;
                }
            }
            x_off += xl;
            y_off += yl;
            k = e;
        }
    }

    align::absorb_whitespace(&mut ops, x, y);

    // Determine, for the plus line, which trailing whitespace tokens get the whitespace error style.
    // Trailing whitespace is an error unless it is part of an insertion run containing non-whitespace.
    let mut plus_ws_error = vec![false; ops.len()];
    if whitespace_error.is_some() {
        // index of the last op consuming a y token
        let mut k = ops.len();
        while k > 0 {
            let (op, _, i) = ops[k - 1];
            match op {
                Operation::Deletion => {
                    k -= 1;
                    continue;
                }
                _ => {
                    if !is_whitespace(y[i]) {
                        break;
                    }
                }
            }
            k -= 1;
        }
        // ops[k..] consume only whitespace y tokens (plus deletions)
        for q in k..ops.len() {
            match ops[q].0 {
                Operation::NoOp | Operation::Absorbed => plus_ws_error[q] = true,
                Operation::Insertion => {
                    // find the edit run containing q
                    let mut s = q;
                    while s > 0 && matches!(ops[s - 1].0, Operation::Deletion | Operation::Insertion) {
                        s -= 1;
                    }
                    let mut e = q;
                    while e < ops.len() && matches!(ops[e].0, Operation::Deletion | Operation::Insertion) {
                        e += 1;
                    }
                    let run_has_non_ws = (s..e).any(|r| ops[r].0 == Operation::Insertion && !is_whitespace(y[ops[r].2]));
                    if !run_has_non_ws {
                        plus_ws_error[q] = true;
                    }
                }
                Operation::Deletion => {}
            }
        }
    }

    let mut annotated_minus_line: LineSections<'a, S> = Vec::new();
    let mut annotated_plus_line: LineSections<'a, S> = Vec::new();
    let mut x_off = 0usize;
    let mut y_off = 0usize;
    for (q, &(op, j, i)) in ops.iter().enumerate() {
        match op {
            Operation::NoOp => {
                push_section(&mut annotated_minus_line, noop_deletion, &minus_line[x_off..x_off + x[j].len()]);
                let ps = if plus_ws_error[q] { whitespace_error.unwrap() } else { noop_insertion };
                push_section(&mut annotated_plus_line, ps, &plus_line[y_off..y_off + y[i].len()]);
                x_off += x[j].len();
                y_off += y[i].len();
            }
            Operation::Absorbed => {
                push_section(&mut annotated_minus_line, deletion, &minus_line[x_off..x_off + x[j].len()]);
                let ps = if plus_ws_error[q] { whitespace_error.unwrap() } else { insertion };
                push_section(&mut annotated_plus_line, ps, &plus_line[y_off..y_off + y[i].len()]);
                x_off += x[j].len();
                y_off += y[i].len();
            }
            Operation::Deletion => {
                push_section(&mut annotated_minus_line, deletion, &minus_line[x_off..x_off + x[j].len()]);
                x_off += x[j].len();
            }
            Operation::Insertion => {
                let ps = if plus_ws_error[q] { whitespace_error.unwrap() } else { insertion };
                push_section(&mut annotated_plus_line, ps, &plus_line[y_off..y_off + y[i].len()]);
                y_off += y[i].len();
            }
        }
    }
    if annotated_minus_line.is_empty() {
        annotated_minus_line.push((noop_deletion, &minus_line[..0]));
    }
    if annotated_plus_line.is_empty() {
        annotated_plus_line.push((noop_insertion, &plus_line[..0]));
    }
    let distance = if d_denom == 0 { 0.0 } else { d_numer as f64 / d_denom as f64 };
    (annotated_minus_line, annotated_plus_line, distance)
}

/// Push a section, merging with the previous one if the style is the same
/// (sections are contiguous slices of the same line).
fn push_section<'a, S: Copy + PartialEq>(sections: &mut LineSections<'a, S>, style: S, text: &'a str) {
    if let Some(last) = sections.last_mut() {
        if last.0 == style {
            let start = last.1.as_ptr() as usize;
            let end = text.as_ptr() as usize + text.len();
            // SAFETY: both slices are contiguous subslices of the same line.
            let merged: &'a str = unsafe {
                std::str::from_utf8_unchecked(std::slice::from_raw_parts(last.1.as_ptr(), end - start))
            };
            last.1 = merged;
            return;
        }
    }
    sections.push((style, text));
}
