            let full: String = texts.concat();
            let syntax_sections: Vec<(SyntectStyle, &str)> = vec![(SyntectStyle { foreground: syntax_fg }, full.as_str())];
            let (line, _) = paint::paint_line(
                &syntax_sections,
                &diff_sections,
                state,
                line_numbers_data,
                Some(side),
                painted_prefix,
                config,
            );
            line
        }
        None => {
            // Empty panel: only line numbers (blank), without incrementing counters.
            let mut strings: Vec<Painted> = Vec::new();
            if let Some(data) = line_numbers_data.as_mut() {
                strings.extend(format_blank_line_numbers(data, side, base_state, config));
            }
            ansi::paint_strings(&strings)
        }
    };
    let tw = ansi::measure_text_width(&line);
    if tw > pw {
        line = ansi::truncate_str(&line, pw, &config.truncation_symbol).to_string();
    } else {
        let fill_width = pw - tw;
        let (method, fill_style) = fill;
        let has_bg = fill_style.has_background() && row.is_some();
        match (method, has_bg, side) {
            (Some(BgFillMethod::TryAnsiSequence), true, PanelSide::Right) => {
                paint::right_fill_background_color(&mut line, &fill_style);
            }
            (Some(_), true, _) => {
                if fill_width > 0 {
                    line.push_str(&fill_style.ansi_term_style.paint(&" ".repeat(fill_width)));
                }
            }
            (_, _, PanelSide::Left) => {
                line.push_str(&" ".repeat(fill_width));
            }
            _ => {}
        }
    }
    line
}

/// Blank line numbers for an empty panel (no counter increments).
fn format_blank_line_numbers(data: &LineNumbersData, side: PanelSide, state: &State, config: &Config) -> Vec<Painted> {
    let (minus_style, zero_style, plus_style) = (
        config.line_numbers_style_minusplus.minus,
        config.line_numbers_zero_style,
        config.line_numbers_style_minusplus.plus,
    );
    let (minus_number_style, plus_number_style) = match state {
        State::HunkZero(..) | State::HunkZeroWrapped => (zero_style, zero_style),
        _ => (minus_style, plus_style),
    };
    let format_data = match side {
        PanelSide::Left => &data.format_data.minus,
        PanelSide::Right => &data.format_data.plus,
    };
    let style = match side {
        PanelSide::Left => config.line_numbers_style_leftright.minus,
        PanelSide::Right => config.line_numbers_style_leftright.plus,
    };
    let mut out = Vec::new();
    let mut suffix = "";
    for placeholder in format_data {
        out.push(Painted::new(style.ansi_term_style, placeholder.prefix.as_str()));
        let width = match placeholder.width {
            Some(w) => std::cmp::max(w, data.hunk_max_line_number_width),
            None => data.hunk_max_line_number_width,
        };
        let alignment = placeholder.alignment_spec.unwrap_or(line_numbers::Align::Center);
        match &placeholder.placeholder {
            Some(line_numbers::Placeholder::NumberMinus) => {
                out.push(Painted::new(minus_number_style.ansi_term_style, line_numbers::format_line_number(None, alignment, width, placeholder.precision, None, config)))
            }
            Some(line_numbers::Placeholder::NumberPlus) => {
                out.push(Painted::new(plus_number_style.ansi_term_style, line_numbers::format_line_number(None, alignment, width, placeholder.precision, None, config)))
            }
            _ => {}
        }
        suffix = placeholder.suffix.as_str();
    }
    out.push(Painted::new(style.ansi_term_style, suffix));
    out
}

/// Wrap one line into rows for the given panel.
fn wrap_for_panel(
    diff_sections: &[(Style, &str)],
    state: &State,
    side: PanelSide,
    line_numbers_data: &Option<LineNumbersData>,
    config: &Config,
) -> Vec<Row> {
    let width = available_line_width(side, line_numbers_data, config);
    let (_, fill_style) = fill_style_for(diff_sections, state, config);
    let hint = inline_hint_style_with_bg(&fill_style, config);
    let sections: Vec<(Style, &str)> = diff_sections.to_vec();
    let total: usize = sections.iter().map(|(_, t)| text_width(t)).sum();
    // Account for a keep-plus-minus-markers prefix occupying one column.
    let prefix_width = if config.keep_plus_minus_markers { 1 } else { 0 };
    if total + prefix_width <= width || config.wrap_config.max_lines == 1 {
        vec![sections.into_iter().map(|(s, t)| (s, t.to_string())).collect()]
    } else {
        wrap_line(&sections, width.saturating_sub(prefix_width), &fill_style, &hint, config)
    }
}

#[allow(clippy::too_many_arguments)]
pub fn paint_minus_and_plus_lines_side_by_side<'a>(
    lines: MinusPlus<&Vec<(String, State)>>,
    syntax_style_sections: MinusPlus<Vec<LineSections<'a, SyntectStyle>>>,
    diff_style_sections: MinusPlus<Vec<LineSections<'a, Style>>>,
    line_alignment: Vec<(Option<usize>, Option<usize>)>,
    states: MinusPlus<Vec<&State>>,
    line_numbers_data: &mut Option<LineNumbersData>,
    output_buffer: &mut String,
    config: &Config,
) {
    let _ = lines;
    for (minus_index, plus_index) in line_alignment {
        let minus_rows: Option<(Vec<Row>, &State, (Option<BgFillMethod>, Style))> = minus_index.map(|i| {
            let state = states.minus[i];
            let sections = &diff_style_sections.minus[i];
            let rows = wrap_for_panel(sections, state, PanelSide::Left, line_numbers_data, config);
            (rows, state, fill_style_for(sections, state, config))
        });
        let plus_rows: Option<(Vec<Row>, &State, (Option<BgFillMethod>, Style))> = plus_index.map(|j| {
            let state = states.plus[j];
            let sections = &diff_style_sections.plus[j];
            let rows = wrap_for_panel(sections, state, PanelSide::Right, line_numbers_data, config);
            (rows, state, fill_style_for(sections, state, config))
        });
        let n_rows = std::cmp::max(
            minus_rows.as_ref().map(|r| r.0.len()).unwrap_or(1),
            plus_rows.as_ref().map(|r| r.0.len()).unwrap_or(1),
        );
        let minus_fg = minus_index.and_then(|i| syntax_style_sections.minus[i].first().and_then(|(s, _)| s.foreground));
        let plus_fg = plus_index.and_then(|j| syntax_style_sections.plus[j].first().and_then(|(s, _)| s.foreground));
        for k in 0..n_rows {
            // left
            let left = match &minus_rows {
                Some((rows, state, fill)) => {
                    let row_state = if k == 0 { (*state).clone() } else { wrapped_state(state) };
                    let prefix = if k == 0 { paint::get_painted_prefix_side_by_side(state, config) } else { None };
                    paint_panel_row(rows.get(k), minus_fg, &row_state, state, PanelSide::Left, *fill, prefix, line_numbers_data, config)
                }
                None => {
                    let state = plus_rows.as_ref().map(|r| r.1).unwrap();
                    paint_panel_row(None, None, state, state, PanelSide::Left, (None, config.null_style), None, line_numbers_data, config)
                }
            };
            let right = match &plus_rows {
                Some((rows, state, fill)) => {
                    let row_state = if k == 0 { (*state).clone() } else { wrapped_state(state) };
                    let prefix = if k == 0 { paint::get_painted_prefix_side_by_side(state, config) } else { None };
                    paint_panel_row(rows.get(k), plus_fg, &row_state, state, PanelSide::Right, *fill, prefix, line_numbers_data, config)
                }
                None => {
                    let state = minus_rows.as_ref().map(|r| r.1).unwrap();
                    paint_panel_row(None, None, state, state, PanelSide::Right, (None, config.null_style), None, line_numbers_data, config)
                }
            };
            output_buffer.push_str(&left);
            output_buffer.push_str(&right);
            output_buffer.push('\n');
        }
    }
}

pub fn paint_zero_lines_side_by_side<'a>(
    lines: &[(String, State)],
    syntax_style_sections: &[LineSections<'a, SyntectStyle>],
    diff_style_sections: &[LineSections<'a, Style>],
    states: &[&State],
    line_numbers_data: &mut Option<LineNumbersData>,
    output_buffer: &mut String,
    config: &Config,
) {
    let _ = lines;
    for ((syntax_sections, diff_sections), state) in syntax_style_sections.iter().zip(diff_style_sections).zip(states) {
        let fg = syntax_sections.first().and_then(|(s, _)| s.foreground);
        let fill = fill_style_for(diff_sections, state, config);
        let left_rows = wrap_for_panel(diff_sections, state, PanelSide::Left, line_numbers_data, config);
        let right_rows = wrap_for_panel(diff_sections, state, PanelSide::Right, line_numbers_data, config);
        let n_rows = std::cmp::max(left_rows.len(), right_rows.len());
        for k in 0..n_rows {
            let row_state = if k == 0 { (*state).clone() } else { wrapped_state(state) };
            let prefix = if k == 0 { paint::get_painted_prefix(state, config) } else { None };
            let left = paint_panel_row(left_rows.get(k), fg, &row_state, state, PanelSide::Left, fill, prefix.clone(), line_numbers_data, config);
            let right = paint_panel_row(right_rows.get(k), fg, &row_state, state, PanelSide::Right, fill, prefix, line_numbers_data, config);
            output_buffer.push_str(&left);
            output_buffer.push_str(&right);
            output_buffer.push('\n');
        }
    }
}
