pub fn wrap_line(
    sections: &[(Style, &str)],
    syntax_fg: Option<ansi::Color>,
    line_width: usize,
    fill_style: &Style,
    inline_hint_style: &Style,
    config: &Config,
) -> Vec<Row> {
    let wrap_config = &config.wrap_config;
    let mut result: Vec<Row> = Vec::new();
    let mut curr_line: Row = Vec::new();
    let mut curr_len: usize = 0;
    let symbol_style = *inline_hint_style;
    let symbol_fg = config.inline_hint_style.ansi_term_style.foreground;
    let mut stack: Vec<(Style, String)> = sections.iter().rev().map(|(s, t)| (*s, t.to_string())).collect();
    let line_limit_reached = |result: &Vec<Row>| wrap_config.max_lines > 0 && result.len() + 1 >= wrap_config.max_lines;
    let mut limit_hit = false;

    while let Some((style, text)) = stack.pop() {
        if line_limit_reached(&result) || line_width == 0 {
            stack.push((style, text));
            limit_hit = true;
            break;
        }
        let tw = text_width(&text);
        let new_len = curr_len + tw;
        let must_split = if new_len < line_width {
            curr_line.push((style, syntax_fg, text.clone()));
            curr_len = new_len;
            false
        } else if new_len == line_width {
            if stack.is_empty() {
                curr_line.push((style, syntax_fg, text.clone()));
                curr_len = new_len;
                false
            } else {
                true
            }
        } else {
            true
        };
        if must_split {
            // Fill the current line up to line_width - 1 columns, then the wrap symbol.
            let available = (line_width - 1).saturating_sub(curr_len);
            let mut used = 0;
            let mut split_byte = 0;
            for (idx, g) in text.grapheme_indices(true) {
                let w = g.width();
                if used + w > available {
                    break;
                }
                used += w;
                split_byte = idx + g.len();
            }
            let this_line = &text[..split_byte];
            let next_line = &text[split_byte..];
            if !this_line.is_empty() {
                curr_line.push((style, syntax_fg, this_line.to_string()));
            }
            stack.push((style, next_line.to_string()));
            curr_line.push((symbol_style, symbol_fg, wrap_config.left_symbol.clone()));
            result.push(std::mem::take(&mut curr_line));
            curr_len = 0;
        }
    }
    // Anything left over (line limit reached) goes onto the final line; it will be truncated.
    while let Some((style, text)) = stack.pop() {
        curr_len += text_width(&text);
        curr_line.push((style, syntax_fg, text));
    }
    if !curr_line.is_empty() || result.is_empty() {
        result.push(curr_line);
    }

    // Right-align a short final line when the content was wrapped exactly once.
    if result.len() == 2 && !limit_hit {
        let last_width: usize = result[1].iter().map(|(_, _, t)| text_width(t)).sum();
        if line_width > 0 && last_width * 1000 / line_width < wrap_config.use_wrap_right_permille {
            if let Some(last) = result[0].last_mut() {
                if last.2 == wrap_config.left_symbol {
                    last.2 = wrap_config.right_symbol.clone();
                }
            }
            let pad = (line_width - 1).saturating_sub(last_width);
            let mut new_last: Row = Vec::new();
            new_last.push((*fill_style, None, " ".repeat(pad)));
            new_last.push((symbol_style, symbol_fg, wrap_config.right_prefix_symbol.clone()));
            new_last.extend(result[1].drain(..));
            result[1] = new_last;
        }
    }
    result
}

