//! Merge conflict rendering (for `diff --cc` output containing conflict markers).

use std::io::Write;

use unicode_segmentation::UnicodeSegmentation;

use crate::config::Config;
use crate::delta::{DiffType, InMergeConflict, MergeConflictCommit, MergeParents, State, StateMachine};
use crate::handlers::draw;
use crate::paint::Painter;
use crate::utils::MinusPlus;

#[derive(Default)]
pub struct MergeConflictLines {
    pub ours: Vec<(String, State)>,
    pub ancestral: Vec<(String, State)>,
    pub theirs: Vec<(String, State)>,
    pub ours_name: String,
    pub ancestral_name: String,
    pub theirs_name: String,
}

impl MergeConflictLines {
    fn clear(&mut self) {
        *self = MergeConflictLines::default();
    }
}

fn n_parents(mp: &MergeParents) -> usize {
    match mp {
        MergeParents::Number(n) => *n,
        MergeParents::Prefix(p) => p.len(),
        MergeParents::Unknown => 1,
    }
}

fn parse_merge_marker<'a>(line: &'a str, marker: &str) -> Option<&'a str> {
    if let Some(rest) = line.strip_prefix(marker) {
        if rest.is_empty() || rest.starts_with(' ') {
            return Some(rest.trim_start());
        }
    }
    None
}

impl<'a> StateMachine<'a> {
    pub fn handle_merge_conflict_line(&mut self) -> std::io::Result<bool> {
        if !self.config.handle_merge_conflicts {
            return Ok(false);
        }
        let merge_parents = match &self.state {
            State::HunkHeader(DiffType::Combined(mp, InMergeConflict::No), _, _, _)
            | State::HunkZero(DiffType::Combined(mp, InMergeConflict::No), _)
            | State::HunkMinus(DiffType::Combined(mp, InMergeConflict::No), _)
            | State::HunkPlus(DiffType::Combined(mp, InMergeConflict::No), _) => mp.clone(),
            State::MergeConflict(mp, _) => mp.clone(),
            _ => return Ok(false),
        };
        let n = n_parents(&merge_parents);
        let rest: String = self.line.graphemes(true).skip(n).collect();
        let number_parents = MergeParents::Number(n);
        match self.state.clone() {
            State::MergeConflict(_, commit) => {
                match commit {
                    MergeConflictCommit::Ours => {
                        if let Some(name) = parse_merge_marker(&rest, "|||||||") {
                            self.merge_conflict_lines.ancestral_name = name.to_string();
                            self.state = State::MergeConflict(number_parents, MergeConflictCommit::Ancestral);
                        } else if rest.starts_with("=======") {
                            self.state = State::MergeConflict(number_parents, MergeConflictCommit::Theirs);
                        } else {
                            let line = self.painter.prepare(&self.line, n);
                            let state = State::HunkPlus(DiffType::Combined(number_parents, InMergeConflict::Yes), None);
                            self.merge_conflict_lines.ours.push((line, state));
                        }
                    }
                    MergeConflictCommit::Ancestral => {
                        if rest.starts_with("=======") {
                            self.state = State::MergeConflict(number_parents, MergeConflictCommit::Theirs);
                        } else {
                            let line = self.painter.prepare(&self.line, n);
                            let state = State::HunkMinus(DiffType::Combined(number_parents, InMergeConflict::Yes), None);
