                if let Some(name) = parse_merge_marker(&rest, "<<<<<<<") {
                    self.painter.paint_buffered_minus_and_plus_lines();
                    self.merge_conflict_lines.clear();
                    self.merge_conflict_lines.ours_name = name.to_string();
                    self.state = State::MergeConflict(number_parents, MergeConflictCommit::Ours);
                    Ok(true)
                } else {
                    Ok(false)
                }
            }
        }
    }

    fn paint_buffered_merge_conflict_lines(&mut self) -> std::io::Result<()> {
        self.painter.emit()?;
        write_merge_conflict_bar(&self.config.merge_conflict_begin_symbol, &mut self.painter, self.config)?;
        let lines = std::mem::take(&mut self.merge_conflict_lines);
        for (derived, header_style) in [
            (MergeConflictCommit::Ours, self.config.merge_conflict_ours_diff_header_style),
            (MergeConflictCommit::Theirs, self.config.merge_conflict_theirs_diff_header_style),
        ] {
            let (name, derived_lines) = match derived {
