            );
            self.painter.emit()?;
        }
        write_merge_conflict_bar(&self.config.merge_conflict_end_symbol, &mut self.painter, self.config)?;
        Ok(())
    }
}

fn write_merge_conflict_bar(s: &str, painter: &mut Painter, config: &Config) -> std::io::Result<()> {
    let width = config.available_terminal_width;
    let unit_width = unicode_width::UnicodeWidthStr::width(s);
    let mut bar = String::new();
    if unit_width > 0 {
        let n = (width + unit_width - 1) / unit_width;
        bar = s.repeat(n);
        // truncate to width (by graphemes)
        let mut out = String::new();
        let mut w = 0;
        for g in bar.graphemes(true) {
            let gw = unicode_width::UnicodeWidthStr::width(g);
            if w + gw > width {
                break;
            }
            out.push_str(g);
            w += gw;
        }
        bar = out;
    }
    writeln!(painter.writer, "{}", bar)
}

fn write_diff_header(
    name: &str,
