    let text = if ancestral.is_empty() {
        name.to_string()
    } else {
        format!("ancestor {} {}{}", config.right_arrow, name, if pad { " " } else { "" })
    };
    draw_fn(
        painter.writer,
        &text,
        &text,
        &config.decorations_width,
        header_style,
        decoration_ansi_term_style,
    )
}
