//! Submodule-related lines.

use crate::delta::{State, StateMachine};
use crate::handlers::diff_header::write_generic_diff_header_header_line;

impl<'a> StateMachine<'a> {
    #[inline]
    fn test_submodule_log_line(&self) -> bool {
        self.line.starts_with("Submodule ")
    }

    /// Handle "Submodule <name> <hash>..<hash>:" (and similar) lines, rendering them as a header.
    pub fn handle_submodule_log_line(&mut self) -> std::io::Result<bool> {
        if !self.test_submodule_log_line() {
            return Ok(false);
        }
        self.painter.paint_buffered_minus_and_plus_lines();
        self.handle_pending_line_with_diff_name()?;
        self.state = State::SubmoduleLog;
        if self.should_handle() && !self.config.color_only {
            self.painter.emit()?;
            let line = self.line.clone();
            let raw_line = self.raw_line.clone();
            write_generic_diff_header_header_line(&line, &raw_line, &mut self.painter, self.config)?;
            return Ok(true);
        }
        Ok(false)
    }

    #[inline]
    fn test_submodule_short_line(&self) -> bool {
        (matches!(self.state, State::HunkHeader(..)) && self.line.starts_with("-Subproject commit "))
            || (matches!(self.state, State::SubmoduleShort(_)) && self.line.starts_with("+Subproject commit "))
    }

    /// Handle "-Subproject commit <hash>" / "+Subproject commit <hash>" line pairs.
    pub fn handle_submodule_short_line(&mut self) -> std::io::Result<bool> {
        if !self.test_submodule_short_line() {
            return Ok(false);
        }
        if let Some(commit) = get_submodule_short_commit(&self.line) {
            if let State::HunkHeader(..) = self.state {
                self.state = State::SubmoduleShort(commit.to_string());
            }
        }
        Ok(true)
    }
}

fn get_submodule_short_commit(line: &str) -> Option<&str> {
    line.strip_prefix("-Subproject commit ")
        .or_else(|| line.strip_prefix("+Subproject commit "))
        .map(|s| s.trim())
}
