{"command":"cd /workspace && cat > src/handlers/grep.rs <<'EOF'
//! Rendering of `rg --json` output.

use std::io::Write;

use crate::ansi::Painted;
use crate::delta::{State, StateMachine};
use crate::features::hyperlinks;
use crate::handlers::draw;
use crate::style::{DecorationStyle, Style};

#[derive(Default)]
pub struct GrepData {
    pub path: String,
    pub prev_line_number: Option<usize>,
    pub prev_was_context: bool,
    pub printed_header: bool,
}

#[derive(Debug)]
struct RgLine {
    kind: String,
    path: Option<String>,
    text: Option<String>,
    line_number: Option<usize>,
    submatches: Vec<(usize, usize)>,
}

// --- minimal JSON parser -------------------------------------------------

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(items) => items.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }
    fn as_num(&self) -> Option<f64> {
        match self {
            Json::Num(n) => Some(*n),
            _ => None,
        }
    }
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
}

impl<'a> Parser<'a> {
    fn ws(&mut self) {
        while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn parse(&mut self) -> Option<Json> {
        self.ws();
        let c = *self.s.get(self.i)?;
        match c {
            b'{' => {
                self.i += 1;
                let mut items = Vec::new();
                loop {
                    self.ws();
                    if self.s.get(self.i) == Some(&b'}') {
                        self.i += 1;
                        break;
                    }
                    let k = match self.parse()? {
                        Json::Str(s) => s,
                        _ => return None,
                    };
                    self.ws();
                    if self.s.get(self.i) != Some(&b':') {
                        return None;
                    }
                    self.i += 1;
                    let v = self.parse()?;
                    items.push((k, v));
                    self.ws();
                    match self.s.get(self.i) {
                        Some(b',') => self.i += 1,
                        Some(b'}') => {
                            self.i += 1;
                            break;
                        }
                        _ => return None,
                    }
                }
                Some(Json::Obj(items))
            }
            b'[' => {
                self.i += 1;
                let mut items = Vec::new();
                loop {
                    self.ws();
                    if self.s.get(self.i) == Some(&b']') {
                        self.i += 1;
                        break;
                    }
                    items.push(self.parse()?);
                    self.ws();
                    match self.s.get(self.i) {
                        Some(b',') => self.i += 1,
                        Some(b']') => {
                            self.i += 1;
                            break;
                        }
                        _ => return None,
                    }
                }
                Some(Json::Arr(items))
            }
            b'"' => {
                self.i += 1;
                let mut out: Vec<u8> = Vec::new();
                loop {
                    let c = *self.s.get(self.i)?;
                    self.i += 1;
                    match c {
                        b'"' => break,
                        b'\\' => {
                            let e = *self.s.get(self.i)?;
                            self.i += 1;
                            match e {
                                b'n' => out.push(b'\n'),
                                b't' => out.push(b'\t'),
                                b'r' => out.push(b'\r'),
                                b'b' => out.push(8),
                                b'f' => out.push(12),
                                b'/' => out.push(b'/'),
                                b'\\' => out.push(b'\\'),
                                b'"' => out.push(b'"'),
                                b'u' => {
                                    let hex = std::str::from_utf8(self.s.get(self.i..self.i + 4)?).ok()?;
                                    self.i += 4;
                                    let mut cp = u32::from_str_radix(hex, 16).ok()?;
                                    if (0xD800..0xDC00).contains(&cp) {
                                        // surrogate pair
                                        if self.s.get(self.i) == Some(&b'\\') && self.s.get(self.i + 1) == Some(&b'u') {
                                            let hex2 = std::str::from_utf8(self.s.get(self.i + 2..self.i + 6)?).ok()?;
                                            let lo = u32::from_str_radix(hex2, 16).ok()?;
                                            self.i += 6;
                                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        }
                                    }
                                    let ch = char::from_u32(cp).unwrap_or('\u{FFFD}');
                                    let mut buf = [0u8; 4];
                                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                                }
                                _ => return None,
                            }
                        }
                        _ => out.push(c),
                    }
                }
                Some(Json::Str(String::from_utf8_lossy(&out).to_string()))
            }
            b't' => {
                if self.s[self.i..].starts_with(b"true") {
                    self.i += 4;
                    Some(Json::Bool(true))
                } else {
                    None
                }
            }
            b'f' => {
                if self.s[self.i..].starts_with(b"false") {
                    self.i += 5;
                    Some(Json::Bool(false))
                } else {
                    None
                }
            }
            b'n' => {
                if self.s[self.i..].starts_with(b"null") {
                    self.i += 4;
                    Some(Json::Null)
                } else {
                    None
                }
            }
            _ => {
                let start = self.i;
                while self.i < self.s.len() && matches!(self.s[self.i], b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9') {
                    self.i += 1;
                }
                let t = std::str::from_utf8(&self.s[start..self.i]).ok()?;
                t.parse::<f64>().ok().map(Json::Num)
            }
        }
    }
}

fn parse_rg_line(line: &str) -> Option<RgLine> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with('{') {
        return None;
    }
    let mut p = Parser { s: trimmed.as_bytes(), i: 0 };
    let json = p.parse()?;
    p.ws();
    if p.i != p.s.len() {
        return None;
    }
    let kind = json.get("type")?.as_str()?.to_string();
    if !matches!(kind.as_str(), "begin" | "match" | "context" | "end" | "summary") {
        return None;
    }
    let data = json.get("data");
    let path = data
        .and_then(|d| d.get("path"))
        .and_then(|p| p.get("text"))
        .and_then(|t| t.as_str())
        .map(|s| s.to_string());
    let text = data
        .and_then(|d| d.get("lines"))
        .and_then(|l| l.get("text"))
        .and_then(|t| t.as_str())
        .map(|s| s.to_string());
    let line_number = data
        .and_then(|d| d.get("line_number"))
        .and_then(|n| n.as_num())
        .map(|n| n as usize);
    let mut submatches = Vec::new();
    if let Some(Json::Arr(items)) = data.and_then(|d| d.get("submatches")) {
        for it in items {
            if let (Some(s), Some(e)) = (
                it.get("start").and_then(|n| n.as_num()),
