            'B' => out.push_str(MONTHS_LONG[(dt.month - 1) as usize]),
            'd' => out.push_str(&format!("{:02}", dt.day)),
            'e' => out.push_str(&format!("{:2}", dt.day)),
            'a' => out.push_str(DAYS_SHORT[dt.weekday() as usize]),
            'A' => out.push_str(DAYS_LONG[dt.weekday() as usize]),
