            'c' => out.push_str(&format!(
                "{} {} {:2} {:02}:{:02}:{:02} {}",
                DAYS_SHORT[dt.weekday() as usize],
                MONTHS_SHORT[(dt.month - 1) as usize],
                dt.day,
                dt.hour,
                dt.minute,
                dt.second,
                dt.year
            )),
            'z' => {
                let sign = if dt.offset < 0 { '-' } else { '+' };
                let a = dt.offset.abs();
                if colon {
                    out.push_str(&format!("{}{:02}:{:02}", sign, a / 3600, (a % 3600) / 60));
                } else {
                    out.push_str(&format!("{}{:02}{:02}", sign, a / 3600, (a % 3600) / 60));
                }
            }
            'Z' => {
                let sign = if dt.offset < 0 { '-' } else { '+' };
                let a = dt.offset.abs();
                out.push_str(&format!("{}{:02}:{:02}", sign, a / 3600, (a % 3600) / 60));
            }
            's' => out.push_str(&format!("{}", dt.timestamp())),
            '%' => out.push('%'),
            'n' => out.push('\n'),
            't' => out.push('\t'),
            other => {
                out.push('%');
                out.push(other);
            }
        }
    }
    out
}

pub fn now_timestamp() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// Humanized relative time, e.g. "3 hours ago", "in 2 days", "now".
pub fn humanize(ts: i64, now: i64) -> String {
    let diff = now - ts; // positive = past
    let n = diff.abs();
    const MINUTE: i64 = 60;
    const HOUR: i64 = 3600;
    const DAY: i64 = 86400;
    const WEEK: i64 = 7 * DAY;
    const MONTH: i64 = 30 * DAY;
    const YEAR: i64 = 365 * DAY;
    let text = if n > 547 * DAY {
        format!("{} years", std::cmp::max(n / YEAR, 2))
    } else if n > 345 * DAY {
        "a year".to_string()
    } else if n > 45 * DAY {
        format!("{} months", std::cmp::max(n / MONTH, 2))
    } else if n > 29 * DAY {
        "a month".to_string()
    } else if n > 10 * DAY + 12 * HOUR {
        format!("{} weeks", std::cmp::max(n / WEEK, 2))
    } else if n > 6 * DAY + 12 * HOUR {
        "a week".to_string()
    } else if n > 35 * HOUR {
        format!("{} days", std::cmp::max(n / DAY, 2))
    } else if n > 23 * HOUR {
        "a day".to_string()
    } else if n > 89 * MINUTE {
        format!("{} hours", std::cmp::max(n / HOUR, 2))
    } else if n > 44 * MINUTE {
        "an hour".to_string()
    } else if n > 89 {
        format!("{} minutes", std::cmp::max(n / MINUTE, 2))
    } else if n > 44 {
        "a minute".to_string()
    } else if n > 10 {
        format!("{} seconds", n)
    } else {
        return "now".to_string();
    };
    if diff >= 0 {
        format!("{} ago", text)
    } else {
        format!("in {}", text)
    }
}
