//! `git blame` output.

use std::io::Write;
use std::sync::OnceLock;

use regex::Regex;
use unicode_width::UnicodeWidthStr;

use crate::ansi::Painted;
use crate::delta::{State, StateMachine};
use crate::features::line_numbers::{self, Align, Placeholder};
use crate::style::Style;
use crate::timeutil;

#[derive(Debug)]
pub struct BlameLine<'a> {
    pub commit: &'a str,
    pub author: &'a str,
    pub time: &'a str,
    pub line_number: usize,
    pub code: &'a str,
}

fn blame_line_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        Regex::new(
            r"(?x)
^
(
    \^?[0-9a-f]{4,40} # commit hash (^ is 'boundary commit' marker)
)
(?:\ .+)?            # optional file name
[\ ]
\(                   # open (
(
    [^\ ].*[^\ ]      # author name
)
[\ ]+
(                     # timestamp
    [0-9]{4}-[0-9]{2}-[0-9]{2}\ [0-9]{2}:[0-9]{2}:[0-9]{2}\ [-+][0-9]{4}
)
[\ ]+
(
    [0-9]+            # line number
)
\)                   # close )
(
    .*                # code
)
$
",
        )
        .unwrap()
    })
}

pub fn parse_git_blame_line<'a>(line: &'a str, _timestamp_format: &str) -> Option<BlameLine<'a>> {
    let caps = blame_line_regex().captures(line)?;
    let commit = caps.get(1)?.as_str();
    let author = caps.get(2)?.as_str();
    let time = caps.get(3)?.as_str();
    let line_number: usize = caps.get(4)?.as_str().parse().ok()?;
    let code = caps.get(5)?.as_str();
    Some(BlameLine {
        commit,
        author,
        time,
        line_number,
        code,
    })
}

impl<'a> StateMachine<'a> {
    pub fn handle_blame_line(&mut self) -> std::io::Result<bool> {
        let previous_key = match &self.state {
            State::Blame(key) => Some(key.clone()),
            State::Unknown => None,
            _ => return Ok(false),
        };
        if self.config.color_only || self.config.opt.raw {
            return Ok(false);
        }
        let line = self.line.clone();
        let blame = match parse_git_blame_line(&line, &self.config.blame_timestamp_format) {
            Some(b) => b,
            None => return Ok(false),
        };
        self.painter.emit()?;
        let config = self.config;
        let key = blame.commit.to_string();
        let is_repeat = previous_key.as_deref() == Some(key.as_str());
        let color_index = self.get_blame_color_index(&key, previous_key.as_deref());
        let bg_style = Style::from_ansi_style(config.blame_palette[color_index]);

        // Metadata
        let metadata = format_blame_metadata(&config.blame_format, &blame, config);
        let metadata = if is_repeat {
            " ".repeat(metadata.width())
        } else {
            metadata
        };
        let mut out = String::new();
        out.push_str(&bg_style.ansi_term_style.paint(&metadata));

        // Separator
        let separator_style = config.blame_separator_style.unwrap_or(bg_style);
        let (prefix, number, suffix) = format_blame_separator(&config.blame_separator_format, blame.line_number, is_repeat);
        out.push_str(&separator_style.ansi_term_style.paint(&prefix));
        out.push_str(&bg_style.ansi_term_style.paint(&number));
        out.push_str(&separator_style.ansi_term_style.paint(&suffix));

        // Code
        let code_style = match config.blame_code_style {
            Some(s) => s,
            None => {
                let mut s = bg_style;
                s.is_syntax_highlighted = true;
                s
            }
        };
        let code = crate::paint::expand_tabs(blame.code, config);
        let fg = if config.syntax_theme.is_some() { self.painter.syntax_fg } else { None };
        let ansi = crate::paint::ansi_style_with_fg(&code_style, fg);
        let painted_code = crate::ansi::paint_strings(&[Painted::new(ansi, code)]);
        out.push_str(&painted_code);
        if code_style.has_background() && config.background_color_extends_to_terminal_width {
            out.push_str(&code_style.ansi_term_style.paint("\x1b[0K"));
        }
        writeln!(self.painter.writer, "{}", out)?;
        self.state = State::Blame(key);
        Ok(true)
    }

    fn get_blame_color_index(&mut self, key: &str, previous_key: Option<&str>) -> usize {
        if let Some(i) = self.blame_key_colors.get(key) {
            return i.parse().unwrap_or(0);
        }
        let n_commits = self.blame_key_colors.len();
        let n_colors = self.config.blame_palette.len().max(1);
        let previous_index: Option<usize> = previous_key
            .and_then(|k| self.blame_key_colors.get(k))
            .and_then(|s| s.parse().ok());
        let mut index = n_commits % n_colors;
        if Some(index) == previous_index {
            index = (n_commits + 1) % n_colors;
        }
        self.blame_key_colors.insert(key.to_string(), index.to_string());
        index
    }
}

fn pad_value(value: &str, align: Option<Align>, width: Option<usize>, precision: Option<usize>) -> String {
    let value: String = match precision {
        Some(p) => value.chars().take(p).collect(),
        None => value.to_string(),
    };
    let width = width.unwrap_or(15);
    line_numbers::pad(&value, width, align.unwrap_or(Align::Left))
}

pub fn format_blame_metadata(format: &str, blame: &BlameLine, config: &crate::config::Config) -> String {
    let data = line_numbers::parse_line_number_format(format, true);
    let mut out = String::new();
    for placeholder in &data {
        out.push_str(&placeholder.prefix);
        let value = match &placeholder.placeholder {
            Some(Placeholder::Str(s)) if s == "timestamp" => Some(format_timestamp(blame.time, config)),
            Some(Placeholder::Str(s)) if s == "author" => Some(blame.author.to_string()),
            Some(Placeholder::Str(s)) if s == "commit" => Some(blame.commit.to_string()),
            Some(Placeholder::Str(s)) => {
                // Unknown placeholder: reproduce literally
                let mut lit = format!("{{{}", s);
                if placeholder.alignment_spec.is_some() || placeholder.width.is_some() || placeholder.precision.is_some() {
                    lit.push(':');
                    match placeholder.alignment_spec {
                        Some(Align::Left) => lit.push('<'),
                        Some(Align::Center) => lit.push('^'),
                        Some(Align::Right) => lit.push('>'),
                        None => {}
                    }
                    if let Some(w) = placeholder.width {
                        lit.push_str(&w.to_string());
                    }
                    if let Some(p) = placeholder.precision {
                        lit.push_str(&format!(".{}", p));
                    }
                }
                lit.push('}');
                out.push_str(&lit);
                None
            }
            Some(Placeholder::Number) => Some(blame.line_number.to_string()),
            Some(Placeholder::NumberMinus) | Some(Placeholder::NumberPlus) | None => None,
        };
        if let Some(v) = value {
            out.push_str(&pad_value(&v, placeholder.alignment_spec, placeholder.width, placeholder.precision));
        }
    }
    if let Some(last) = data.last() {
        out.push_str(&last.suffix);
    }
    out
}

fn format_timestamp(time: &str, config: &crate::config::Config) -> String {
    match timeutil::parse(time, &config.blame_timestamp_format) {
        Some(dt) => match &config.blame_timestamp_output_format {
            Some(fmt) => timeutil::format(&dt, fmt),
            None => timeutil::humanize(dt.timestamp(), timeutil::now_timestamp()),
        },
        None => time.to_string(),
    }
}

/// Returns (prefix, number, suffix) for the blame separator.
fn format_blame_separator(format: &str, line_number: usize, is_repeat: bool) -> (String, String, String) {
    if format == "none" {
        return (String::new(), String::new(), "│".to_string());
    }
    let data = line_numbers::parse_line_number_format(format, true);
    let mut placeholder_data = None;
    for p in &data {
        if matches!(p.placeholder, Some(Placeholder::Number)) {
            placeholder_data = Some(p);
            break;
        }
    }
    match placeholder_data {
        None => (String::new(), String::new(), format.to_string()),
        Some(p) => {
            let width = p.width.unwrap_or(4);
            let align = p.alignment_spec.unwrap_or(Align::Center);
            let show = if p.fmt_type == "_block" {
                !is_repeat
            } else if let Some(n) = p.fmt_type.strip_prefix("_every-") {
                match n.parse::<usize>() {
                    Ok(n) if n > 0 => !(is_repeat && line_number % n == 0),
                    _ => true,
                }
            } else {
                true
            };
            let number = if show {
                line_numbers::pad(&line_number.to_string(), width, align)
            } else {
                " ".repeat(width)
            };
            (p.prefix.clone(), number, p.suffix.clone())
        }
    }
}
